// Shared OpenAI helper — uses fetch so no openai package import is needed
async function openAiChat(messages: Array<{role: string; content: string}>, maxTokens = 100): Promise<string> {
  if (!process.env.OPENAI_API_KEY) return '';
  const resp = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${process.env.OPENAI_API_KEY}` },
    body: JSON.stringify({ model: 'gpt-4o-mini', messages, max_tokens: maxTokens, temperature: 0.7 })
  });
  const data: any = await resp.json();
  return data?.choices?.[0]?.message?.content?.trim() || '';
}
