  // Lazy-loaded Stripe instance to avoid startup blocking
  let _stripe: Stripe | null = null;
  let _stripeInitialized = false;
  let _stripeError: string | null = null;

  function getStripe(): Stripe {
    if (_stripeInitialized) {
      if (_stripeError) {
        throw new Error(_stripeError);
      }
      return _stripe!;
    }

    _stripeInitialized = true;
    // In production always use live keys; in development always use test keys.
    // NODE_ENV is the authoritative signal — secrets/env flags are ignored here
    // so that developers can never accidentally charge real cards locally.
    const useLiveStripe = process.env.NODE_ENV === 'production';
    const stripeSecretKey = useLiveStripe
      ? process.env.STRIPE_SECRET_KEY_LIVE
      : process.env.TESTING_STRIPE_SECRET_KEY;

    if (!stripeSecretKey) {
      const keyType = useLiveStripe ? 'STRIPE_SECRET_KEY_LIVE' : 'TESTING_STRIPE_SECRET_KEY';
      _stripeError = `Missing required ${keyType} - billing features disabled`;
      console.warn(`⚠️ ${keyType} not found - billing routes will not work`);
      throw new Error(_stripeError);
    }

    // Validate key prefix matches the expected environment
    const expectedPrefix = useLiveStripe ? 'sk_live_' : 'sk_test_';
    if (!stripeSecretKey.startsWith(expectedPrefix)) {
      _stripeError = `${useLiveStripe ? 'STRIPE_SECRET_KEY_LIVE' : 'TESTING_STRIPE_SECRET_KEY'} must start with ${expectedPrefix}`;
      console.error(`❌ Invalid Stripe key - must use ${useLiveStripe ? 'live' : 'test'} keys in ${useLiveStripe ? 'production' : 'development'}`);
      throw new Error(_stripeError);
    }

    console.log(`✅ Stripe initialised in ${useLiveStripe ? 'LIVE' : 'TEST'} mode (NODE_ENV=${process.env.NODE_ENV})`);
    _stripe = new Stripe(stripeSecretKey, {
      apiVersion: '2024-06-20',
    });
    
    return _stripe;
  }

