  async function ensureTrialPlanExists(): Promise<string> {
    const plans = await storage.getSubscriptionPlans(true);
    if (plans.length > 0) {
      return plans[0].id;
    }
    const allPlans = await storage.getSubscriptionPlans(false);
    if (allPlans.length > 0) {
      return allPlans[0].id;
    }
    console.log('📋 No subscription plans found, creating default trial plan...');
    try {
      const trialPlan = await storage.createSubscriptionPlan({
        planName: 'Free Trial',
        stripePriceId: 'trial_price_default',
        planDescription: '14-day free trial with full features',
        monthlyPrice: 0,
        features: ['AI Receptionist', 'Phone Number', 'Call Management', 'SMS Messaging'],
        maxPhoneNumbers: 1,
        isActive: true,
        planType: 'monthly',
        displayOrder: 0,
      } as any);
      console.log(`✅ Default trial plan created: ${trialPlan.id}`);
      return trialPlan.id;
    } catch (err: any) {
      if (err.message?.includes('duplicate') || err.code === '23505') {
        console.log('📋 Trial plan already exists (concurrent creation), fetching...');
        const retryPlans = await storage.getSubscriptionPlans(false);
        if (retryPlans.length > 0) return retryPlans[0].id;
      }
      throw err;
    }
  }

  // Helper function to get raw business information text from user's onboarding data
  async function getRawBusinessInfoForUser(userId: string): Promise<string | null> {
    try {
      console.log(`🔍 Searching for raw business information text for user: ${userId}`);

      // FIRST: Check restaurant_data for AI-generated rawBusinessInfo (highest priority)
      try {
        const voiceAgents = await storage.getUserVoiceAgents(userId);
        if (voiceAgents && voiceAgents.length > 0) {
          const agentId = voiceAgents[0].id;
          const restaurantData = await storage.getRestaurantData(agentId);
          
          if (restaurantData?.rawBusinessInfo && restaurantData.rawBusinessInfo.trim()) {
            console.log(`✅ Found AI-generated business info in restaurant_data.rawBusinessInfo (${restaurantData.rawBusinessInfo.length} chars)`);
            
            // Return the AI-generated business info (which already includes website in the formatted text)
            return restaurantData.rawBusinessInfo;
          } else if (restaurantData) {
            console.log(`📋 Found business name from existing voice agent: ${restaurantData.businessName}`);
          }
        }
      } catch (err) {
        console.log('ℹ️ No restaurant data found, checking signup progress...');
      }

      // SECOND: Get signup progress data
      const signupProgress = await storage.getSignupProgress(userId);

      if (signupProgress?.stepData) {
        const stepData = signupProgress.stepData as any;

        // Check for raw businessInfo text DIRECTLY in stepData (primary location)
        if (stepData.businessInfo) {
          const businessInfo = stepData.businessInfo;
          if (typeof businessInfo === 'string' && businessInfo.trim()) {
            console.log(`✅ Found raw business info text in stepData.businessInfo (${businessInfo.length} chars)`);
            return businessInfo;
          }
        }

        // Check for raw businessInfo text in businessOnboarding
        if (stepData.businessOnboarding?.businessInfo) {
          const businessInfo = stepData.businessOnboarding.businessInfo;
          if (typeof businessInfo === 'string' && businessInfo.trim()) {
            console.log(`✅ Found raw business info text in businessOnboarding.businessInfo (${businessInfo.length} chars)`);
            return businessInfo;
          }
        }

        // Check for raw businessInfo text in agentCreationData
        if (stepData.agentCreationData?.businessInfo) {
          const businessInfo = stepData.agentCreationData.businessInfo;
          if (typeof businessInfo === 'string' && businessInfo.trim()) {
            console.log(`✅ Found raw business info text in agentCreationData.businessInfo (${businessInfo.length} chars)`);
            return businessInfo;
          }
        }

        // Fallback: Try to construct text from structured data if available
        const extracted = stepData.businessOnboarding || stepData.agentCreationData?.businessData;
        if (extracted) {
          const businessName = extracted.businessName || extracted.name;
          if (businessName && businessName.trim() && businessName !== 'Your Business') {
            console.log(`⚠️ No raw text found, constructing from structured data`);

            const parts = [];
            if (businessName) parts.push(`Business Name: ${businessName}`);
            if (extracted.address || extracted.physicalAddress) parts.push(`Address: ${extracted.address || extracted.physicalAddress}`);
            if (extracted.phone || extracted.phoneNumber) parts.push(`Phone: ${extracted.phone || extracted.phoneNumber}`);
            if (extracted.email) parts.push(`Email: ${extracted.email}`);
            if (extracted.website) parts.push(`Website: ${extracted.website}`);
            if (extracted.hours || extracted.businessHours) parts.push(`Hours: ${extracted.hours || extracted.businessHours}`);
            if (extracted.services) parts.push(`Services: ${extracted.services}`);
            if (extracted.description || extracted.overview) parts.push(`Description: ${extracted.description || extracted.overview}`);

            const constructedText = parts.join('\n');
            console.log(`✅ Constructed business info text (${constructedText.length} chars)`);
            return constructedText;
          }
        }
      }

      console.log(`❌ No business information text found for user ${userId}`);
      return null;

    } catch (error) {
      console.error(`❌ Error getting raw business info for user ${userId}:`, error);
      return null;
    }
  }

