  // Helper function to automatically provision phone number for user after payment
  async function provisionPhoneNumberForUser(userId: string, subscriptionId?: string): Promise<void> {
    try {
      console.log(`📞 Starting automated subscription provisioning for user: ${userId}, subscription: ${subscriptionId}`);

      // Route to appropriate provisioning method based on subscription context
      if (subscriptionId) {
        console.log(`🚀 Using automated subscription provisioning service: ${subscriptionId}`);

        // Get raw business information text from user's onboarding data
        const businessInfoText = await getRawBusinessInfoForUser(userId);
        if (!businessInfoText) {
          console.log(`❌ No business information found for user ${userId}. User must complete business onboarding first.`);
          throw new Error(`Business information required for subscription provisioning. User ${userId} must complete business onboarding first.`);
        } else {
          console.log(`✅ Found business information for user ${userId} (${businessInfoText.length} characters), starting automated provisioning`);

          // Pass raw text to SubscriptionProvisioningService - it will handle extraction with OpenAI
          await subscriptionProvisioningService.provisionSubscription(userId, subscriptionId, businessInfoText);
        }
        return;
      } else {
        console.log(`🔴 Using legacy provisioning flow for non-subscription user: ${userId}`);
        // Fall back to legacy provisioning for non-subscription flows
        await legacyProvisionPhoneNumberForUser(userId);
        return;
      }
    } catch (error) {
      console.error(`❌ Automated subscription provisioning failed for user ${userId}:`, error);
      // Don't throw to prevent webhook failures
    }
  }

  // Legacy provisioning function (renamed from original)
  async function legacyProvisionPhoneNumberForUser(userId: string): Promise<void> {
    try {
      console.log(`📞 [LEGACY] Provisioning phone number for user: ${userId}`);

      // Validate input parameters
      if (!userId) {
        console.error('❌ No userId provided for phone number provisioning');
        return;
      }

      // Get user information
      const user = await storage.getUser(userId);
      if (!user) {
        console.error(`❌ User not found: ${userId}`);
        return;
      }

      // Enhanced idempotency protection for legacy flow: check if user has any phone numbers
      const existingPhoneNumbers = await storage.getUserPhoneNumbers(userId);
      if (existingPhoneNumbers && existingPhoneNumbers.length > 0) {
        console.log(`✅ User ${userId} already has phone number(s), skipping legacy provisioning`);
        return;
      }

      // Additional protection: create a temporary lock record to prevent race conditions
      const lockId = `phone-provisioning-${userId}-legacy`;
      console.log(`🔒 Creating provisioning lock: ${lockId}`);

      // Get business information from multiple sources in priority order
      let businessInfo: any = null;
      
      try {
        // First, try to get business info from signup progress
        const signupProgress = await storage.getSignupProgress(userId);
        if (signupProgress?.stepData?.businessOnboarding) {
          businessInfo = signupProgress.stepData.businessOnboarding;
          console.log(`📍 Found business info from signup progress: ${businessInfo.businessName || 'Unknown Business'}`);
        }
        
        // If not found in signup progress, try to get from restaurant data
        if (!businessInfo || !businessInfo.businessName) {
          try {
            const restaurants = await storage.getUserRestaurants(userId);
            if (restaurants && restaurants.length > 0) {
              const restaurant = restaurants[0]; // Use the first restaurant
              businessInfo = {
                businessName: restaurant.name,
                address: restaurant.address || `${restaurant.city}, ${restaurant.state}`,
                phone: restaurant.phone || '',
                website: restaurant.website || '',
                businessType: 'restaurant'
              };
              console.log(`📍 Found business info from restaurant data: ${businessInfo.businessName}`);
            }
          } catch (restaurantError) {
            console.log('No restaurant data found');
          }
        }
        
        // If still not found, try to get from enhanced restaurant profiles
        if (!businessInfo || !businessInfo.businessName) {
          try {
            const enhancedProfiles = await storage.getEnhancedRestaurantProfilesByUserId(userId);
            if (enhancedProfiles && enhancedProfiles.length > 0) {
              const profile = enhancedProfiles[0]; // Use the first profile
              businessInfo = {
                businessName: profile.businessName,
                address: profile.address,
                phone: profile.phone || '',
                website: profile.website || '',
                businessType: 'restaurant'
              };
              console.log(`📍 Found business info from enhanced profile: ${businessInfo.businessName}`);
            }
          } catch (profileError) {
            console.log('No enhanced profile data found');
          }
        }
      } catch (error) {
        console.log('Error retrieving business data:', error);
      }
      
      // If no business info found anywhere, create a default one based on user info
      if (!businessInfo || !businessInfo.businessName) {
        businessInfo = {
          businessName: user.firstName ? `${user.firstName}'s Business` : 'Your Business',
          address: '123 Main St, New York, NY 10001', // Default address for phone provisioning
          phone: '',
          website: '',
          businessType: 'restaurant'
        };
        console.log(`📍 Using default business info for phone provisioning: ${businessInfo.businessName}`);
      }

      console.log(`📍 Extracting address components for: ${businessInfo.businessName}`);

      // Extract comprehensive business profile including address components with error handling
      let businessProfile: any = null;
      let addressComponents = null;
      let useAreaCodeSearch = false;
      
      try {
        businessProfile = await businessExtractor.extractComprehensiveBusinessProfile(
          `${businessInfo.businessName}, ${businessInfo.address}`
        );

        if (!businessProfile?.addressComponents) {
          console.warn(`⚠️ Unable to parse address components for ${businessInfo.businessName}, proceeding with generic phone search`);
          // Continue with generic phone number search without area code targeting
          addressComponents = null;
          useAreaCodeSearch = false;
        } else {
          console.log(`✅ Successfully parsed address components for ${businessInfo.businessName}`);
          addressComponents = businessProfile.addressComponents;
          useAreaCodeSearch = true;
        }
      } catch (extractorError) {
        console.warn(`⚠️ Business profile extraction failed for ${businessInfo.businessName}, proceeding with generic phone search:`, extractorError);
        // If extraction fails completely, continue with generic search
        businessProfile = null;
        addressComponents = null;
        useAreaCodeSearch = false;
      }
      const customerName = user.firstName && user.lastName 
        ? `${user.firstName} ${user.lastName}` 
        : user.email || businessInfo.businessName;

      // Attempt to create emergency address for E911 compliance (only if we have address components)
      let emergencyAddress: { sid: string } | null = null;
      if (addressComponents && useAreaCodeSearch) {
        try {
          // Validate address components before creating emergency address
          const hasValidAddressData = (
            addressComponents.street && 
            addressComponents.city && 
            addressComponents.state &&
            addressComponents.postalCode &&
            addressComponents.postalCode !== '00000' &&
            addressComponents.city !== 'Unknown' &&
            addressComponents.state !== 'Unknown'
          );

          if (hasValidAddressData) {
            console.log(`🏠 Creating emergency address for: ${customerName}`);
            emergencyAddress = await twilioService.createEmergencyAddress({
              customerName,
              street: addressComponents.street,
              city: addressComponents.city,
              region: addressComponents.state,
              postalCode: addressComponents.postalCode,
              isoCountry: addressComponents.countryCode || 'US'
            });
            console.log(`✅ Emergency address created successfully: ${emergencyAddress.sid}`);
          } else {
            console.log(`⚠️ Incomplete address data - skipping E911 emergency address creation`);
            console.log(`Address components:`, {
              street: addressComponents.street || 'missing',
              city: addressComponents.city || 'missing',
              state: addressComponents.state || 'missing',
              postalCode: addressComponents.postalCode || 'missing'
            });
          }
        } catch (error) {
          console.warn(`⚠️ Failed to create emergency address, continuing without E911:`, error);
          emergencyAddress = null;
        }
      } else {
        console.log(`⚠️ No parsed address available, skipping E911 emergency address creation`);
        emergencyAddress = null;
      }

      // Helper function to get area code based on location
      function getAreaCodeFromLocation(state: string, city: string): string | null {
        // Map of major US states to their primary area codes
        const areaCodes: { [key: string]: string[] } = {
          'NY': ['212', '646', '917', '929', '718'],
          'CA': ['415', '510', '650', '408', '310', '213'],
          'FL': ['305', '786', '407', '321', '561'],
          'TX': ['214', '469', '972', '713', '281', '832'],
          'IL': ['312', '773', '708', '847'],
          'NJ': ['201', '973', '908', '609'],
          'PA': ['215', '267', '610', '484'],
          'OH': ['216', '440', '330', '614'],
          'MI': ['313', '248', '586', '734'],
          'GA': ['404', '678', '770', '470'],
          'NC': ['704', '980', '919', '984'],
          'VA': ['703', '571', '757', '804'],
          'WA': ['206', '425', '253', '360'],
          'AZ': ['602', '623', '480', '520'],
          'MA': ['617', '857', '781', '978'],
          'IN': ['317', '765', '812', '219'],
          'TN': ['615', '629', '901', '731'],
          'MO': ['314', '636', '417', '573'],
          'MD': ['301', '240', '410', '443'],
          'WI': ['414', '262', '920', '608'],
          'MN': ['612', '651', '763', '952'],
          'CO': ['303', '720', '970', '719'],
          'AL': ['205', '251', '256', '334'],
          'SC': ['803', '843', '864', '854'],
          'LA': ['504', '985', '225', '318'],
          'KY': ['502', '859', '270', '364'],
          'OR': ['503', '971', '541', '458'],
          'OK': ['405', '918', '580', '539'],
          'CT': ['203', '475', '860', '959'],
          'IA': ['515', '563', '641', '712'],
          'MS': ['601', '769', '228', '662'],
          'AR': ['501', '870', '479', '327'],
          'KS': ['316', '620', '785', '913'],
          'UT': ['801', '385', '435', '385'],
          'NV': ['702', '725', '775', '928'],
          'NM': ['505', '575', '575', '505'],
          'NE': ['402', '531', '308', '308'],
          'WV': ['304', '681', '681', '304'],
          'ID': ['208', '986', '986', '208'],
          'HI': ['808', '808', '808', '808'],
          'NH': ['603', '603', '603', '603'],
          'ME': ['207', '207', '207', '207'],
          'RI': ['401', '401', '401', '401'],
          'MT': ['406', '406', '406', '406'],
          'DE': ['302', '302', '302', '302'],
          'SD': ['605', '605', '605', '605'],
          'ND': ['701', '701', '701', '701'],
          'AK': ['907', '907', '907', '907'],
          'VT': ['802', '802', '802', '802'],
          'WY': ['307', '307', '307', '307']
        };

        const stateAreaCodes = areaCodes[state?.toUpperCase()];
        return stateAreaCodes ? stateAreaCodes[0] : null;
      }

      // Search for available phone numbers with SMS and voice support
      console.log(`🔍 Searching for available phone numbers...`);
      let availableNumbers;
      let selectedNumber;

      // Try to get a number in the business area code first (only if we have address components)
      if (useAreaCodeSearch && addressComponents && addressComponents.state && addressComponents.city) {
        try {
          const areaCode = getAreaCodeFromLocation(addressComponents.state, addressComponents.city);
          if (areaCode) {
            console.log(`🎯 Trying area code ${areaCode} for ${addressComponents.city}, ${addressComponents.state}`);
            availableNumbers = await twilioService.searchAvailablePhoneNumbers({
              areaCode,
              smsEnabled: true,
              voiceEnabled: true,
              type: 'local',
              limit: 5
            });
          }
        } catch (error) {
          console.log(`⚠️ Area code search failed, will search without restrictions:`, error);
        }
      } else {
        console.log(`⚠️ Skipping area code search (no address components), searching for any available number`);
      }

      // Fallback: search without area code restrictions
      if (!availableNumbers || availableNumbers.length === 0) {
        console.log(`🔄 Searching for any available local number...`);
        try {
          availableNumbers = await twilioService.searchAvailablePhoneNumbers({
            smsEnabled: true,
            voiceEnabled: true,
            type: 'local',
            limit: 10
          });
        } catch (error) {
          console.log(`⚠️ Local number search failed, trying toll-free:`, error);
        }
      }

      // Last resort: try toll-free numbers
      if (!availableNumbers || availableNumbers.length === 0) {
        console.log(`🔄 Trying toll-free numbers as fallback...`);
        try {
          availableNumbers = await twilioService.searchAvailablePhoneNumbers({
            smsEnabled: true,
            voiceEnabled: true,
            type: 'toll-free',
            limit: 5
          });
        } catch (error) {
          console.error(`❌ Toll-free number search also failed:`, error);
        }
      }

      if (!availableNumbers || availableNumbers.length === 0) {
        console.error(`❌ No available phone numbers found after trying all options`);
        return;
      }

      selectedNumber = availableNumbers[0];
      console.log(`✅ Selected phone number: ${selectedNumber.phoneNumber} (${selectedNumber.locality || 'N/A'})`);
      
      // Configure webhook URLs for the user's AI receptionist
      const baseUrl = process.env.REPLIT_DOMAINS?.split(',')[0] 
        ? `https://${process.env.REPLIT_DOMAINS.split(',')[0]}`
        : `https://${process.env.REPL_SLUG}.${process.env.REPLIT_CLUSTER || 'replit'}.repl.co`;
      
      const voiceWebhookUrl = `${baseUrl}/api/voice/incoming?userId=${userId}`;
      const smsWebhookUrl = `${baseUrl}/api/sms/incoming?userId=${userId}`;

      // Purchase the phone number with webhook configuration and retry logic
      console.log(`💰 Purchasing phone number: ${selectedNumber.phoneNumber}`);
      const purchaseOptions: any = {
        voiceUrl: voiceWebhookUrl,
        smsUrl: smsWebhookUrl,
        friendlyName: `${businessInfo.businessName} - AI Receptionist`
      };
      
      // Only include emergency address if we have one
      if (emergencyAddress?.sid) {
        purchaseOptions.emergencyAddressSid = emergencyAddress.sid;
        console.log(`📍 Including emergency address: ${emergencyAddress.sid}`);
      } else {
        console.log(`⚠️ No emergency address available - proceeding without E911 compliance`);
      }
      
      let purchasedNumber;
      let retryCount = 0;
      const maxRetries = 3;
      
      while (retryCount < maxRetries) {
        try {
          purchasedNumber = await twilioService.purchasePhoneNumber(selectedNumber.phoneNumber, purchaseOptions);
          console.log(`✅ Successfully purchased phone number: ${purchasedNumber.phoneNumber}`);

          // CRITICAL: Explicitly enable SMS on the purchased number to ensure SMS alerts work in production
          try {
            console.log(`📱 Explicitly enabling SMS on newly purchased number ${purchasedNumber.phoneNumber}...`);
            await twilioService.updatePhoneNumberConfiguration(purchasedNumber.sid, {
              ...purchaseOptions,
              enableSMS: true
            });
            console.log(`✅ SMS capability explicitly enabled on ${purchasedNumber.phoneNumber}`);
          } catch (smsEnableError) {
            console.error(`⚠️ Warning: Failed to explicitly enable SMS:`, smsEnableError);
            // Don't fail the entire purchase if SMS enablement fails
          }

          break;
        } catch (error: any) {
          retryCount++;
          console.log(`⚠️ Failed to purchase phone number (attempt ${retryCount}/${maxRetries}):`, error.message);
          
          if (retryCount >= maxRetries) {
            console.error(`❌ Failed to purchase phone number after ${maxRetries} attempts`);
            throw error;
          }
          
          // If this number is no longer available, try the next one from our list
          if (retryCount < availableNumbers.length) {
            selectedNumber = availableNumbers[retryCount];
            console.log(`🔄 Trying alternative phone number: ${selectedNumber.phoneNumber}`);
          } else {
            // Search for new numbers if we've exhausted our list
            console.log(`🔄 Searching for new available numbers...`);
            try {
              const newNumbers = await twilioService.searchAvailablePhoneNumbers({
                smsEnabled: true,
                voiceEnabled: true,
                type: 'local',
                limit: 5
              });
              if (newNumbers.length > 0) {
                selectedNumber = newNumbers[0];
                console.log(`🔄 Found new phone number to try: ${selectedNumber.phoneNumber}`);
              } else {
                throw new Error('No more available phone numbers found');
              }
            } catch (searchError) {
              console.error(`❌ Failed to find alternative numbers:`, searchError);
              throw error;
            }
          }
        }
      }

      // Store business info in signup progress for later retrieval
      try {
        const existingProgress = await storage.getSignupProgress(userId);
        const updatedStepData = {
          ...existingProgress?.stepData,
          businessOnboarding: businessInfo,
          phoneProvisioningData: {
            businessProfile,
            phoneNumber: purchasedNumber.phoneNumber,
            createdAt: new Date().toISOString()
          }
        };
        
        if (existingProgress) {
          await storage.updateSignupProgress(existingProgress.id, {
            stepData: updatedStepData
          });
        } else {
          await storage.saveSignupProgress({
            userId,
            sessionId: `phone-${Date.now()}`,
            currentStep: 'phone-provisioned',
            stepData: updatedStepData,
            completedSteps: ['payment', 'phone-provisioning']
          });
        }
        console.log(`✅ Stored business info in signup progress for user ${userId}`);
      } catch (error) {
        console.error(`⚠️ Failed to store business info in signup progress:`, error);
      }

      // Store phone number in database with robust error handling for uniqueness constraints
      try {
        await storage.createPhoneNumberAssignment({
          userId,
          subscriptionId: subscriptionId || '', // Use provided subscription ID or empty string
          restaurantId: null, // Will be linked when AI agent is created
          twilioPhoneNumberSid: purchasedNumber.sid,
          phoneNumber: purchasedNumber.phoneNumber,
          phoneNumberType: selectedNumber.phoneNumber.startsWith('+1800') || selectedNumber.phoneNumber.startsWith('+1833') || selectedNumber.phoneNumber.startsWith('+1844') || selectedNumber.phoneNumber.startsWith('+1855') || selectedNumber.phoneNumber.startsWith('+1866') || selectedNumber.phoneNumber.startsWith('+1877') || selectedNumber.phoneNumber.startsWith('+1888') ? 'toll-free' : 'local',
          status: 'active',
          monthlyCost: 1.15 // Standard Twilio local number cost
        });
        console.log(`✅ Phone number ${purchasedNumber.phoneNumber} successfully stored in database for user ${userId}`);
      } catch (dbError: any) {
        console.error(`❌ Database error storing phone number assignment:`, dbError);
        
        // If there's a unique constraint violation, this means another process already assigned this number
        if (dbError.message?.includes('unique constraint') || dbError.code === '23505') {
          console.error(`❌ Phone number ${purchasedNumber.phoneNumber} was already assigned to another user - this should not happen!`);
          
          // Release the phone number back to Twilio since we can't use it
          try {
            await twilioService.releasePhoneNumber(purchasedNumber.sid);
            console.log(`🔄 Released phone number ${purchasedNumber.phoneNumber} back to Twilio`);
          } catch (releaseError) {
            console.error(`❌ Failed to release phone number back to Twilio:`, releaseError);
          }
          
          throw new Error(`Phone number assignment failed due to duplicate number: ${purchasedNumber.phoneNumber}`);
        } else {
          // For other database errors, still throw to prevent silent failures
          throw dbError;
        }
      }

      console.log(`✅ Successfully provisioned phone number ${purchasedNumber.phoneNumber} for user ${userId}`);

      // Create AI receptionist after successful phone provisioning
      try {
        console.log(`🤖 Creating AI receptionist for user ${userId} with phone ${purchasedNumber.phoneNumber}`);

        // Check if user already has AI receptionists to avoid duplicates
        const existingReceptionists = await storage.getUserVoiceAgents(userId);
        if (!existingReceptionists || existingReceptionists.length === 0) {

          // Use new Retell agent creation with retell-llm engine
          await createRetellAgentForUser(userId);

          console.log(`✅ AI receptionist created successfully with retell-llm engine`);

          // Get the created agent to link phone number
          const agents = await storage.getUserVoiceAgents(userId);
          const newAgent = agents[0];

          if (newAgent) {
            // Link the phone number to the AI agent
            try {
              await storage.updatePhoneNumberAssignment(purchasedNumber.phoneNumber, {
                restaurantId: newAgent.id
              });
              console.log(`🔗 Linked phone number ${purchasedNumber.phoneNumber} to AI agent ${newAgent.id}`);

              // Connect agent to phone number in Retell
              if (newAgent.retellAgentId) {
                const retellProvider = new RetellProvider(storage);
                await retellProvider.connectAgentToPhoneNumber(newAgent.retellAgentId, purchasedNumber.phoneNumber);
                console.log(`📞 Connected Retell agent ${newAgent.retellAgentId} to phone ${purchasedNumber.phoneNumber}`);
              }
            } catch (linkError) {
              console.warn(`⚠️ Failed to link phone number to AI agent:`, linkError);
            }
          }

        } else {
          console.log(`✅ User already has ${existingReceptionists.length} AI receptionist(s), skipping creation`);
        }

      } catch (aiError) {
        console.error(`❌ Failed to create AI receptionist for user ${userId}:`, aiError);
        // Don't fail phone provisioning if AI creation fails
      }

    } catch (error) {
      console.error(`❌ Error provisioning phone number for user ${userId}:`, error);
      // Don't throw error to prevent webhook failure - just log and continue
    }
  }

