  // Helper function to provision phone number with enhanced user lookup for direct checkout
  async function provisionPhoneNumberWithUserLookup(params: {
    userId?: string,
    email?: string,
    subscriptionId?: string
  }): Promise<void> {
    try {
      let userId = params.userId;

      // If no userId provided, try to find user by email
      if (!userId && params.email) {
        console.log(`🔍 Looking up user by email: ${params.email}`);
        try {
          const user = await storage.getUserByEmail(params.email);
          if (user) {
            userId = user.id;
            console.log(`✅ Found user ${userId} for email ${params.email}`);
          } else {
            console.error(`❌ No user found for email: ${params.email}`);
            return;
          }
        } catch (error) {
          console.error(`❌ Error looking up user by email ${params.email}:`, error);
          return;
        }
      }

      if (!userId) {
        console.error('❌ Cannot provision phone number: no userId or email provided');
        return;
      }

      // Call the main provisioning function
      await provisionPhoneNumberForUser(userId, params.subscriptionId);
      
    } catch (error) {
      console.error('❌ Error in enhanced phone number provisioning:', error);
    }
  }

