  // Helper function to get database plan ID from plan slug
  async function getDbPlanIdFromSlug(planSlug: string): Promise<string | null> {
    try {
      // Map plan slugs to database plan names
      const slugToNameMap: { [key: string]: string } = {
        'small': 'Small',
        'medium': 'Medium', 
        'large': 'Large'
      };

      const dbPlanName = slugToNameMap[planSlug];
      if (!dbPlanName) {
        console.error(`❌ No database plan name found for slug: ${planSlug}`);
        return null;
      }

      // Look up the plan in the database by name
      const plans = await storage.getSubscriptionPlans();
      const plan = plans.find(p => p.planName === dbPlanName);
      
      if (!plan) {
        console.error(`❌ No plan found in database with name: ${dbPlanName}`);
        return null;
      }

      return plan.id;
    } catch (error) {
      console.error(`❌ Error getting database plan ID for slug ${planSlug}:`, error);
      return null;
    }
  }

  // Helper function to create a one-time $1.15 discount coupon for phone number cost
  async function createPhoneNumberDiscountCoupon() {
    const stripe = getStripe();
    const coupons = await stripe.coupons.list({ limit: 1 });
    const existingCoupon = coupons.data.find(c => c.name === 'Phone Number Discount');
    
    if (existingCoupon) {
      return existingCoupon.id;
    }
    
    const coupon = await stripe.coupons.create({
      name: 'Phone Number Discount',
      amount_off: 115, // $1.15 in cents
      currency: 'usd',
      duration: 'once',
      max_redemptions: 10000
    });
    
    return coupon.id;
  }



  // Consolidated login endpoint (handles both post-payment and direct login)
  app.post('/api/auth/login', async (req, res) => {
    try {
      const { email, password, loginAfterPayment, paymentToken } = req.body;

      // PRIVACY: Redact email for compliance (GDPR, CCPA, NIST-800-53)
      const redactedEmail = email ? email.replace(/(.{2})(.*)(@.*)/, '$1***$3') : 'none';
      console.log('🔐 Login attempt:', {
        email: redactedEmail,
        hasPassword: !!password,
        loginAfterPayment: !!loginAfterPayment
      });

      // --- POST-PAYMENT LOGIN (token-gated) ---
      // The frontend sends a one-time paymentToken issued by /api/auth/verify-email.
      // We look the user up by that token (stored in emailVerificationToken field),
      // verify it hasn't expired, clear it, and create a session. No password needed.
      if (loginAfterPayment === true) {
        if (!paymentToken || typeof paymentToken !== 'string' || paymentToken.trim().length === 0) {
          console.log('❌ loginAfterPayment attempted without a paymentToken');
          return res.status(401).json({ message: "Invalid or missing payment token." });
        }

        const tokenUser = await storage.getUserByVerificationToken(paymentToken);
        if (!tokenUser) {
          console.log('❌ Payment token not found or already consumed');
          return res.status(401).json({ message: "Payment session expired. Please log in with your email and password." });
        }

        // Validate expiry (stored in emailVerificationExpires)
        if (tokenUser.emailVerificationExpires) {
          const expiry = new Date(tokenUser.emailVerificationExpires);
          if (expiry < new Date()) {
            console.log('❌ Payment token expired');
            return res.status(401).json({ message: "Payment session expired. Please log in with your email and password." });
          }
        }

        // Consume the token (one-time use)
        await storage.clearEmailVerificationToken(tokenUser.id);
        console.log(`✅ Payment token validated and consumed for user ${tokenUser.email}`);

        // Fall through to session creation with tokenUser
        const sessionUser = {
          claims: {
            sub: tokenUser.id,
            email: tokenUser.email,
            first_name: tokenUser.firstName,
            last_name: tokenUser.lastName,
            profile_image_url: tokenUser.profileImageUrl
          },
          access_token: tokenUser.id,
          expires_at: Math.floor(Date.now() / 1000) + (7 * 24 * 60 * 60)
        };

        return (req as any).login(sessionUser, (err: any) => {
          if (err) {
            console.error('Login error:', err);
            return res.status(500).json({ message: "Login failed. Please try again." });
          }
          (req as any).session.save((saveErr: any) => {
            if (saveErr) {
              console.error('Session save error:', saveErr);
              return res.status(500).json({ message: "Login successful but session failed. Please try logging in again." });
            }
            return res.json({
              success: true,
              message: "Login successful",
              user: {
                id: tokenUser.id,
                email: tokenUser.email,
                firstName: tokenUser.firstName,
                lastName: tokenUser.lastName,
              }
            });
          });
        });
      }

      // --- STANDARD PASSWORD LOGIN ---
      if (!email) {
        return res.status(400).json({
          message: "Email is required"
        });
      }

      // Validate email format
      if (!directAuthService.validateEmail(email)) {
        return res.status(400).json({
          message: "Please enter a valid email address"
        });
      }

      // Find user by email
      let user;
      try {
        user = await storage.getUserByEmail(email);
      } catch (error) {
        console.log('❌ User not found in database');
        return res.status(401).json({
          message: "Invalid email or password"
        });
      }

      if (!user) {
        console.log('❌ User not found');
        return res.status(401).json({
          message: "Invalid email or password"
        });
      }

      console.log('👤 User found:', {
        id: user.id,
        email: user.email,
        hasPasswordHash: !!user.passwordHash
      });

      // Check if email is verified
      if (!user.emailVerified) {
        console.log('❌ Email not verified for user:', user.email);
        return res.status(400).json({
          message: "Email not verified. Please check your inbox for the verification link."
        });
      }

      // Password is REQUIRED for direct login
      if (!password || password.trim().length === 0) {
        console.log('❌ Password not provided or empty');
        return res.status(400).json({
          message: "Email and password are required"
        });
      }

      // Check if user has a password hash (users who signed up via OAuth won't have one)
      if (!user.passwordHash || user.passwordHash.trim().length === 0) {
        console.log('❌ User has no password hash - likely OAuth user');
        return res.status(401).json({
          message: "Invalid email or password. Please try logging in with Google/Replit."
        });
      }

      // Verify the password using bcrypt
      const isPasswordValid = await directAuthService.verifyPassword(password, user.passwordHash);
      console.log('🔑 Password validation result:', isPasswordValid);

      if (!isPasswordValid) {
        console.log('❌ Invalid password provided');
        return res.status(401).json({
          message: "Invalid email or password"
        });
      }

      console.log('✅ Password validated successfully');

      // Create session user object
      const sessionUser = {
        claims: {
          sub: user.id,
          email: user.email,
          first_name: user.firstName,
          last_name: user.lastName,
          profile_image_url: user.profileImageUrl
        },
        access_token: user.id,
        expires_at: Math.floor(Date.now() / 1000) + (7 * 24 * 60 * 60) // 7 days
      };

      // Regenerate session ID before login to prevent session fixation attacks
      await new Promise<void>((resolve, reject) => {
        (req as any).session.regenerate((err: any) => {
          if (err) reject(err); else resolve();
        });
      });

      // Log in the user through Passport and save session
      return (req as any).login(sessionUser, (err: any) => {
        if (err) {
          console.error('Login error:', err);
          return res.status(500).json({ 
            message: "Login failed. Please try again." 
          });
        }
        
        // Ensure session is saved before responding
        (req as any).session.save((saveErr: any) => {
          if (saveErr) {
            console.error('Session save error:', saveErr);
            return res.status(500).json({ 
              message: "Login successful but session failed. Please try logging in again." 
            });
          }
          
          return res.json({ 
            success: true, 
            message: "Login successful",
            user: {
              id: user.id,
              email: user.email,
              firstName: user.firstName,
              lastName: user.lastName
            },
            redirectTo: loginAfterPayment ? "/dashboard" : "/dashboard"
          });
        });
      });

    } catch (error) {
      console.error("Login error:", error);
      res.status(500).json({ message: "Login failed. Please try again." });
    }
  });

  // Direct signup route (bypass Replit auth)
  app.post('/api/auth/signup', async (req, res) => {
    try {
      let { fullName, firstName, lastName, email, phone, password, website, inviteToken } = req.body;

      // Support both fullName and firstName/lastName formats
      const nameToUse = fullName || (firstName && lastName ? `${firstName} ${lastName}` : '');

      // ── Invitation token flow ──────────────────────────────────────────────
      // When an invite token is present, skip email verification entirely and
      // immediately bind the new account to the inviting organization.
      if (inviteToken) {
        // Validate required fields (website is not needed for invited users)
        if (!email || !password) {
          return res.status(400).json({ message: "Email and password are required" });
        }
        if (!directAuthService.validateEmail(email)) {
          return res.status(400).json({ message: "Please enter a valid email address" });
        }
        if (!directAuthService.validatePassword(password)) {
          return res.status(400).json({ message: "Password must be at least 8 characters and include at least one uppercase letter and one number" });
        }

        // Look up and validate the invitation
        const [invitation] = await db
          .select()
          .from(teamInvitations)
          .where(eq(teamInvitations.inviteToken, inviteToken as string))
          .limit(1);

        if (!invitation) {
          return res.status(400).json({ success: false, message: "Invalid or expired invitation link" });
        }
        if (invitation.status !== 'pending') {
          return res.status(400).json({ success: false, message: invitation.status === 'accepted' ? "This invitation has already been used" : "This invitation is no longer valid" });
        }
        if (new Date() > new Date(invitation.expiresAt)) {
          return res.status(400).json({ success: false, message: "This invitation link has expired" });
        }
        if (email.toLowerCase() !== invitation.email.toLowerCase()) {
          return res.status(400).json({ success: false, message: `This invitation was sent to ${invitation.email}. Please use that email address.` });
        }

        // Check if account already exists for this email
        const existingUser = await storage.getUserByEmail(email).catch(() => null);
        if (existingUser) {
          return res.status(409).json({ success: false, message: "An account with this email already exists. Please log in instead.", code: "EMAIL_ALREADY_EXISTS" });
        }

        // Create the user account with email pre-verified
        const passwordHash = await directAuthService.hashPassword(password);
        const { randomUUID } = await import('crypto');
        const userId = randomUUID();
        await storage.upsertUser({
          id: userId,
          email,
          firstName: nameToUse?.split(' ')[0] || '',
          lastName: nameToUse?.split(' ').slice(1).join(' ') || '',
          profileImageUrl: '',
          passwordHash,
          emailVerified: true,
        } as any);

        // Log the new user in immediately (Passport session)
        const sessionUser = {
          claims: { sub: userId, email, first_name: nameToUse?.split(' ')[0] || '', last_name: nameToUse?.split(' ').slice(1).join(' ') || '', profile_image_url: '' },
          access_token: userId,
          expires_at: Math.floor(Date.now() / 1000) + 7 * 24 * 60 * 60,
        };
        await new Promise<void>((resolve, reject) => {
          (req as any).login(sessionUser, (err: any) => {
            if (err) reject(err);
            else (req as any).session.save((saveErr: any) => saveErr ? reject(saveErr) : resolve());
          });
        });

        // Check if the user is already a member (idempotency)
        const [existingMember] = await db
          .select()
          .from(teamMembers)
          .where(and(eq(teamMembers.userId, userId), eq(teamMembers.ownerId, invitation.ownerId)))
          .limit(1);

        if (!existingMember) {
          await db.insert(teamMembers).values({
            ownerId: invitation.ownerId,
            userId,
            role: invitation.role,
            permissions: invitation.permissions || null,
            assignedAgentIds: invitation.assignedAgentIds || null,
            status: 'active',
          });
        }

        // Mark invitation as accepted
        await db
          .update(teamInvitations)
          .set({ status: 'accepted', acceptedByUserId: userId, acceptedAt: new Date() } as any)
          .where(eq(teamInvitations.inviteToken, inviteToken as string));

        console.log(`✅ Invited user ${email} signed up and joined org of ${invitation.ownerId} as ${invitation.role}`);

        return res.json({
          success: true,
          inviteAccepted: true,
          ownerId: invitation.ownerId,
          message: "Account created and team joined successfully",
        });
      }
      // ── End invitation token flow ──────────────────────────────────────────

      // Normalize and validate website URL
      if (website) {
        website = website.trim();
        if (!website.startsWith('http://') && !website.startsWith('https://')) {
          website = `https://${website}`;
        }
        try {
          const parsed = new URL(website);
          // Only allow http(s) schemes to prevent javascript: or data: URIs
          if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
            return res.status(400).json({ message: "Please enter a valid website URL" });
          }
          website = parsed.toString();
        } catch {
          return res.status(400).json({ message: "Please enter a valid website URL" });
        }
      }

      // Validate required fields
      if (!email || !password) {
        return res.status(400).json({
          message: "Email and password are required"
        });
      }

      // Validate email format
      if (!directAuthService.validateEmail(email)) {
        return res.status(400).json({
          message: "Please enter a valid email address"
        });
      }

      // Validate phone format (only if provided)
      if (phone && !directAuthService.validatePhone(phone)) {
        return res.status(400).json({
          message: "Please enter a valid phone number"
        });
      }

      // Validate password
      if (!directAuthService.validatePassword(password)) {
        return res.status(400).json({
          message: "Password must be at least 8 characters and include at least one uppercase letter and one number"
        });
      }

      // Check if user already exists
      try {
        const existingUser = await storage.getUserByEmail(email);
        if (existingUser) {
          // User already exists - return error to prevent account creation
          return res.status(409).json({
            success: false,
            message: "An account with this email already exists. Please use a different email or try logging in instead.",
            code: "EMAIL_ALREADY_EXISTS"
          });
        }
      } catch (error) {
        // User doesn't exist, which is what we want for new signups
      }

      // Create user directly (emailVerified defaults to false)
      const { user } = await directAuthService.createUserDirectly({
        fullName: nameToUse,
        email,
        phone,
        password
      });

      // Store website URL in signup progress if provided
      if (website) {
        await storage.saveSignupProgress({
          userId: user.id,
          currentStep: 'account-created',
          stepData: {
            fullName: nameToUse,
            email,
            website, // Store website for later provisioning
          },
          completedSteps: ['account-created'],
          isCompleted: false,
        });
      }

      // Generate verification token
      const { createVerificationToken, sendVerificationEmail } = await import('./services/emailVerificationService');
      const token = await createVerificationToken(user.id);

      // Get base URL for verification link
      const protocol = req.get('x-forwarded-proto') || req.protocol;
      const host = req.get('host');
      const baseUrl = `${protocol}://${host}`;
      const verificationUrl = `${baseUrl}/verify-email?token=${token}`;

      // Send verification email
      const emailSent = await sendVerificationEmail({
        recipientEmail: email,
        recipientName: nameToUse || undefined,
        verificationUrl,
      });

      if (!emailSent) {
        console.error('Failed to send verification email');
        return res.status(500).json({
          success: false,
          message: "Account created but failed to send verification email. Please contact support.",
        });
      }

      console.log(`✅ Signup successful for ${email}, verification email sent`);

      res.json({
        success: true,
        message: "Verification email sent! Please check your inbox.",
        emailSent: true,
      });

    } catch (error) {
      console.error('Direct signup error:', error);
      res.status(500).json({
        message: "Failed to create account. Please try again."
      });
    }
  });

  // Email verification endpoint
  app.post('/api/auth/verify-email', async (req, res) => {
    try {
      const { token } = req.body;

      if (!token) {
        return res.status(400).json({
          success: false,
          error: 'Verification token is required'
        });
      }

      // Verify the token
      const { verifyToken } = await import('./services/emailVerificationService');
      const result = await verifyToken(token);

      if (!result.success) {
        return res.status(400).json(result);
      }

      // Get user details from database to create session
      const user = await storage.getUser(result.userId!);
      if (!user) {
        return res.status(400).json({
          success: false,
          error: 'User not found'
        });
      }

      // Log the user in via Passport (same mechanism as /api/auth/login)
      // Using req.login() is required — manually setting req.session.user is ignored by
      // isAuthenticated because Passport reads from req.session.passport.user, not session.user.
      const sessionUser = {
        claims: {
          sub: user.id,
          email: user.email,
          first_name: user.firstName,
          last_name: user.lastName,
          profile_image_url: user.profileImageUrl
        },
        access_token: user.id,
        expires_at: Math.floor(Date.now() / 1000) + (7 * 24 * 60 * 60) // 7 days
      };

      await new Promise<void>((resolve, reject) => {
        (req as any).login(sessionUser, (err: any) => {
          if (err) {
            console.error('Session login error after email verification:', err);
            reject(err);
          } else {
            (req as any).session.save((saveErr: any) => {
              if (saveErr) {
                console.error('Session save error:', saveErr);
                reject(saveErr);
              } else {
                console.log('✅ Session created for user:', user.email);
                resolve();
              }
            });
          }
        });
      });

      // Get user and website from signup progress
      const signupProgress = await storage.getSignupProgress(result.userId!);
      const website = signupProgress?.stepData?.website;

      // Start async provisioning if website provided
      if (website && result.userId) {
        // Import provisioning service
        const { analyzeBusinessWebsite } = await import('./services/websiteAnalysisService');
        const { SubscriptionProvisioningService } = await import('./services/SubscriptionProvisioningService');

        // Trigger provisioning in background (don't await)
        (async () => {
          try {
            console.log(`🚀 Starting automatic provisioning for user ${result.userId}`);

            // Create a temporary trial subscription for provisioning
            const subscriptionId = `email-signup-${result.userId}`;

            // Check if subscription already exists
            const existingSubscription = await storage.getUserSubscription(result.userId!);

            if (!existingSubscription) {
              const planId = await ensureTrialPlanExists();

              // Create trial subscription record for provisioning
              const trialEnd = new Date();
              trialEnd.setDate(trialEnd.getDate() + 14); // 14 days trial

              await storage.createUserSubscription({
                id: subscriptionId,
                userId: result.userId!,
                stripeCustomerId: `temp_${result.userId}`, // Temporary Stripe customer ID
                stripeSubscriptionId: subscriptionId, // Use same ID
                stripePriceId: `trial_price`, // Temporary price ID
                planId: planId,
                status: 'trialing',
                currentPeriodStart: new Date(),
                currentPeriodEnd: trialEnd,
                trialEnd: trialEnd,
                provisioningStatus: null, // Will be set to 'in_progress' by provisioning service
              });

              console.log(`✅ Created trial subscription for provisioning: ${subscriptionId}`);
            }

            // Analyze website — use fallback info if analysis fails so provisioning still proceeds
            const analysis = await analyzeBusinessWebsite(website);
            let businessInfoText: string;
            if (analysis.success) {
              businessInfoText = [
                `Business Name: ${analysis.businessName}`,
                `Industry: ${analysis.industry}`,
                `Description: ${analysis.description}`,
                `Website: ${website}`,
                analysis.phoneNumber ? `Phone: ${analysis.phoneNumber}` : '',
                analysis.address ? `Address: ${analysis.address}` : '',
              ].filter(Boolean).join('\n');
            } else {
              console.warn(`⚠️ Website analysis failed, using fallback info for provisioning: ${analysis.error}`);
              businessInfoText = `Website: ${website}`;
            }

            // Create provisioning service
            const provisioningService = new SubscriptionProvisioningService();

            await provisioningService.provisionSubscription(
              result.userId!,
              subscriptionId,
              businessInfoText
            );

            console.log(`✅ Automatic provisioning completed for user ${result.userId}`);
          } catch (error) {
            console.error('Automatic provisioning failed:', error);
          }
        })();
      }

      res.json({
        success: true,
        userId: result.userId,
        paymentToken: result.paymentToken, // One-time token for post-payment login
        message: 'Email verified successfully'
      });

    } catch (error: any) {
      console.error('Email verification error:', error);
      res.status(500).json({
        success: false,
        error: 'Verification failed'
      });
    }
  });

  // Resend verification email endpoint
  app.post('/api/auth/resend-verification', async (req, res) => {
    try {
      const { email } = req.body;

      if (!email) {
        return res.status(400).json({
          success: false,
          error: 'Email is required'
        });
      }

      // Get base URL
      const protocol = req.get('x-forwarded-proto') || req.protocol;
      const host = req.get('host');
      const baseUrl = `${protocol}://${host}`;

      // Resend verification email
      const { resendVerificationEmail } = await import('./services/emailVerificationService');
      const result = await resendVerificationEmail(email, baseUrl);

      if (!result.success) {
        return res.status(400).json(result);
      }

      res.json({
        success: true,
        message: 'Verification email sent'
      });

    } catch (error: any) {
      console.error('Resend verification error:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to resend verification email'
      });
    }
  });

  // Google setup endpoint (for Google OAuth users to submit website)
  app.post('/api/auth/google-setup', async (req, res) => {
    try {
      let { website } = req.body;

      // Get authenticated user from session
      const sessionUser = (req as any).session?.passport?.user;
      if (!sessionUser) {
        return res.status(401).json({
          success: false,
          message: 'Not authenticated'
        });
      }

      const userId = sessionUser.claims?.sub || sessionUser.id;

      if (!userId) {
        return res.status(401).json({
          success: false,
          message: 'User ID not found'
        });
      }

      if (!website) {
        return res.status(400).json({
          success: false,
          message: 'Website is required'
        });
      }

      // Normalize website URL - add https:// if not present
      website = website.trim();
      if (!website.startsWith('http://') && !website.startsWith('https://')) {
        website = `https://${website}`;
      }

      // Session already established by Google OAuth callback - no need to regenerate
      // Just ensure it's saved before proceeding
      await new Promise<void>((resolve, reject) => {
        req.session.save((saveErr) => {
          if (saveErr) {
            console.error('Session save error:', saveErr);
            reject(saveErr);
          } else {
            console.log('✅ Using existing session for Google OAuth user:', sessionUser.email || sessionUser.claims?.email);
            resolve();
          }
        });
      });

      // Get user details (FIXED: use storage.getUser instead of storage.getUserById)
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({
          success: false,
          message: 'User not found'
        });
      }

      // Save website to signup progress
      await storage.saveSignupProgress({
        userId,
        currentStep: 'google-setup',
        stepData: {
          fullName: user.fullName,
          email: user.email,
          website,
        },
        completedSteps: ['account-created', 'google-setup'],
        isCompleted: false,
      });

      // Start async provisioning if website provided (matching email verification flow)
      // NOTE: The provisioning service creates the agent — no pre-emptive agent creation here
      // to avoid orphaned duplicate agents.
      if (website && userId) {
        const { analyzeBusinessWebsite } = await import('./services/websiteAnalysisService');
        const { SubscriptionProvisioningService } = await import('./services/SubscriptionProvisioningService');

        (async () => {
          try {
            console.log(`🚀 Starting automatic provisioning for Google OAuth user ${userId}`);

            // Create a temporary trial subscription for provisioning
            const subscriptionId = `email-signup-${userId}`;

            // Check if subscription already exists
            const existingSubscription = await storage.getUserSubscription(userId);

            console.log(`🔍 Subscription check for user ${userId}:`, {
              exists: !!existingSubscription,
              subscriptionId: existingSubscription?.id,
              provisioningStatus: existingSubscription?.provisioningStatus
            });

            if (!existingSubscription) {
              const planId = await ensureTrialPlanExists();

              // Create trial subscription record for provisioning
              const trialEnd = new Date();
              trialEnd.setDate(trialEnd.getDate() + 14); // 14 days trial

              await storage.createUserSubscription({
                id: subscriptionId,
                userId: userId,
                stripeCustomerId: `temp_${userId}`, // Temporary Stripe customer ID
                stripeSubscriptionId: subscriptionId, // Use same ID
                stripePriceId: `trial_price`, // Temporary price ID
                planId: planId,
                status: 'trialing',
                currentPeriodStart: new Date(),
                currentPeriodEnd: trialEnd,
                trialEnd: trialEnd,
                provisioningStatus: null, // Will be set to 'in_progress' by provisioning service
              });

              console.log(`✅ Created NEW trial subscription for provisioning: ${subscriptionId} for user ${userId}`);
            } else {
              console.log(`♻️ Using EXISTING subscription ${existingSubscription.id} for user ${userId} with status: ${existingSubscription.provisioningStatus}`);
            }

            // Analyze website
            const analysis = await analyzeBusinessWebsite(website);

            if (!analysis.success) {
              console.error('Website analysis failed:', analysis.error);
              return;
            }

            // Create provisioning service
            const provisioningService = new SubscriptionProvisioningService();

            // Format business info text for provisioning
            const businessInfoText = `
Business Name: ${analysis.businessName}
Industry: ${analysis.industry}
Description: ${analysis.description}
Website: ${website}
${analysis.phoneNumber ? `Phone: ${analysis.phoneNumber}` : ''}
${analysis.address ? `Address: ${analysis.address}` : ''}
            `.trim();

            await provisioningService.provisionSubscription(
              userId,
              subscriptionId, // Use the subscription ID we created
              businessInfoText
            );

            console.log(`✅ Automatic provisioning completed for Google OAuth user ${userId}`);
          } catch (error) {
            console.error('Google OAuth automatic provisioning failed:', error);
          }
        })();
      }

      res.json({
        success: true,
        userId: userId,
        message: 'Google setup completed successfully'
      });

    } catch (error: any) {
      console.error('Google setup error:', error);
      res.status(500).json({
        success: false,
        message: 'Failed to start setup'
      });
    }
  });

  // Create session endpoint (for auto-login after email verification)
  app.post('/api/auth/session/create', async (req, res) => {
    try {
      const { userId } = req.body;

      if (!userId) {
        return res.status(400).json({
          success: false,
          error: 'User ID is required'
        });
      }

      // Get user from database
      const user = await storage.getUser(userId);

      if (!user) {
        return res.status(404).json({
          success: false,
          error: 'User not found'
        });
      }

      // Verify email is confirmed
      if (!user.emailVerified) {
        return res.status(400).json({
          success: false,
          error: 'Email not verified'
        });
      }

      // Create session
      (req.session as any).user = {
        id: user.id,
        email: user.email,
        fullName: user.fullName,
        emailVerified: user.emailVerified,
        claims: {
          sub: user.id,
          email: user.email,
          name: user.fullName,
          email_verified: user.emailVerified
        }
      };

      // Save session
      await new Promise<void>((resolve, reject) => {
        req.session.save((err) => {
          if (err) reject(err);
          else resolve();
        });
      });

      res.json({
        success: true,
        message: 'Session created successfully',
        user: {
          id: user.id,
          email: user.email,
          fullName: user.fullName
        }
      });

    } catch (error: any) {
      console.error('Session creation error:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to create session'
      });
    }
  });

  // Start provisioning in background (called from VerifyEmailSent page)
  app.post('/api/auth/start-provisioning', isAuthenticated, async (req, res) => {
    try {
      // Use the authenticated session identity — do NOT accept a user ID or email
      // from the request body, which would allow any authenticated user to trigger
      // provisioning on behalf of another account (IDOR).
      const sessionUserId = (req.user as any)?.claims?.sub;
      if (!sessionUserId) {
        return res.status(401).json({ success: false, error: 'Unauthorized' });
      }

      const user = await storage.getUser(sessionUserId);

      if (!user) {
        return res.status(404).json({
          success: false,
          error: 'User not found'
        });
      }

      // Check if provisioning is already complete
      const existingAgents = await storage.getUserVoiceAgents(user.id);
      if (existingAgents && existingAgents.length > 0) {
        console.log(`✅ User ${user.email} already has agents, skipping provisioning`);
        return res.json({
          success: true,
          message: 'Provisioning already complete'
        });
      }

      // Get signup progress to retrieve website
      const signupProgress = await storage.getSignupProgress(user.id);
      
      if (!signupProgress || !signupProgress.stepData?.website) {
        console.log(`⚠️ No website found in signup progress for user ${user.email}`);
        return res.json({
          success: true,
          message: 'No website to provision from'
        });
      }

      const website = signupProgress.stepData.website;

      // Start async provisioning in background (don't await)
      const { analyzeBusinessWebsite } = await import('./services/websiteAnalysisService');
      const { SubscriptionProvisioningService } = await import('./services/SubscriptionProvisioningService');

      (async () => {
        try {
          console.log(`🚀 Starting automatic provisioning for email signup user ${user.email}`);

          // Create a temporary trial subscription for provisioning
          const subscriptionId = `email-signup-${user.id}`;

          // Check if subscription already exists
          const existingSubscription = await storage.getUserSubscription(user.id);

          if (!existingSubscription) {
            const planId = await ensureTrialPlanExists();

            // Create trial subscription record for provisioning
            const trialEnd = new Date();
            trialEnd.setDate(trialEnd.getDate() + 14); // 14 days trial

            await storage.createUserSubscription({
              id: subscriptionId,
              userId: user.id,
              stripeCustomerId: `temp_${user.id}`, // Temporary Stripe customer ID
              stripeSubscriptionId: subscriptionId, // Use same ID
              stripePriceId: `trial_price`, // Temporary price ID
              planId: planId,
              status: 'trialing',
              currentPeriodStart: new Date(),
              currentPeriodEnd: trialEnd,
              trialEnd: trialEnd,
              provisioningStatus: null, // Will be set to 'in_progress' by provisioning service
            });

            console.log(`✅ Created trial subscription for provisioning: ${subscriptionId}`);
          }

          // Analyze website — use fallback info if analysis fails so provisioning still proceeds
          const analysis = await analyzeBusinessWebsite(website);
          let businessInfoText: string;
          if (analysis.success) {
            businessInfoText = [
              `Business Name: ${analysis.businessName}`,
              `Industry: ${analysis.industry}`,
              `Description: ${analysis.description}`,
              `Website: ${website}`,
              analysis.phoneNumber ? `Phone: ${analysis.phoneNumber}` : '',
              analysis.address ? `Address: ${analysis.address}` : '',
            ].filter(Boolean).join('\n');
          } else {
            console.warn(`⚠️ Website analysis failed, using fallback info for provisioning: ${analysis.error}`);
            businessInfoText = `Website: ${website}`;
          }

          // Create provisioning service
          const provisioningService = new SubscriptionProvisioningService();

          await provisioningService.provisionSubscription(
            user.id,
            subscriptionId,
            businessInfoText
          );

          console.log(`✅ Automatic provisioning completed for email signup user ${user.email}`);
        } catch (error) {
          console.error('Email signup automatic provisioning failed:', error);
        }
      })();

      res.json({
        success: true,
        message: 'Provisioning started in background'
      });

    } catch (error: any) {
      console.error('Start provisioning error:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to start provisioning'
      });
    }
  });

  // Reprovision endpoint — allows users to retry phone provisioning and rebuild their conversation flow
  app.post('/api/provisioning/reprovision', isAuthenticated, async (req, res) => {
    try {
      const sessionUserId = (req.user as any)?.claims?.sub;
      if (!sessionUserId) {
        return res.status(401).json({ success: false, error: 'Unauthorized' });
      }

      const subscription = await storage.getUserSubscription(sessionUserId);
      if (!subscription) {
        return res.status(404).json({ success: false, error: 'No subscription found' });
      }

      // Check if phone is already provisioned
      const existingPhones = await storage.getUserPhoneNumbers(sessionUserId);
      if (existingPhones && existingPhones.length > 0 && existingPhones[0].phoneNumber) {
        return res.json({ success: true, message: 'Phone already provisioned', phoneNumber: existingPhones[0].phoneNumber });
      }

      // Reset provisioning status so the lock can be reacquired
      await storage.updateUserSubscription(subscription.id, { provisioningStatus: null } as any);

      // Get stored business info from signup progress
      const signupProgress = await storage.getSignupProgress(sessionUserId);
      const website = signupProgress?.stepData?.website;

      res.json({ success: true, message: 'Reprovisioning started in background' });

      // Run reprovisioning asynchronously
      (async () => {
        try {
          console.log(`🔄 Starting reprovision for user ${sessionUserId}, subscription ${subscription.id}`);
          const { analyzeBusinessWebsite } = await import('./services/websiteAnalysisService');
          const { SubscriptionProvisioningService } = await import('./services/SubscriptionProvisioningService');

          let businessInfoText = '';
          if (website) {
            const analysis = await analyzeBusinessWebsite(website);
            if (analysis.success) {
              businessInfoText = [
                analysis.businessName ? `Business Name: ${analysis.businessName}` : '',
                analysis.industry ? `Industry: ${analysis.industry}` : '',
                analysis.description ? `Description: ${analysis.description}` : '',
                `Website: ${website}`,
                analysis.phoneNumber ? `Phone: ${analysis.phoneNumber}` : '',
                analysis.address ? `Address: ${analysis.address}` : '',
              ].filter(Boolean).join('\n');
            } else {
              businessInfoText = `Website: ${website}`;
            }
          }

          const provisioningService = new SubscriptionProvisioningService();
          const result = await provisioningService.provisionSubscription(
            sessionUserId,
            subscription.id,
            businessInfoText
          );
          console.log(`✅ Reprovision complete for user ${sessionUserId}:`, result.success ? 'success' : result.error);
        } catch (err: any) {
          console.error(`❌ Reprovision failed for user ${sessionUserId}:`, err.message);
        }
      })();
    } catch (error: any) {
      console.error('Reprovision endpoint error:', error);
      res.status(500).json({ success: false, error: 'Failed to start reprovisioning' });
    }
  });

  // Provisioning status endpoint
  app.get('/api/provisioning/status/:userId', async (req, res) => {
    try {
      const { userId } = req.params;

      // Disable caching for this endpoint
      res.set('Cache-Control', 'no-store, no-cache, must-revalidate, private');
      res.set('Pragma', 'no-cache');
      res.set('Expires', '0');

      // Get both agents and subscription to check complete status
      const agents = await storage.getUserVoiceAgents(userId);
      const subscription = await storage.getUserSubscription(userId);

      console.log(`📊 Provisioning status check for user ${userId}:`, {
        hasAgents: agents && agents.length > 0,
        agentCount: agents?.length || 0,
        subscriptionFound: !!subscription,
        subscriptionId: subscription?.id || 'none',
        provisioningStatus: subscription?.provisioningStatus || 'no subscription'
      });

      // CRITICAL: Only mark as completed if BOTH agents exist AND provisioning status is 'completed'
      // This ensures ALL workflows (KB creation, agent creation, phone provisioning, business settings) are done
      if (agents && agents.length > 0 && subscription?.provisioningStatus === 'completed') {
        console.log(`✅ Provisioning complete for user ${userId}, returning completed status`);

        // Parse gap analysis from setupNotification if present (set by SubscriptionProvisioningService)
        let gapAnalysis = null;
        if (subscription.setupNotification) {
          try {
            const parsed = JSON.parse(subscription.setupNotification as string);
            if (parsed?.type === 'gap_analysis') {
              gapAnalysis = parsed;
            }
          } catch {
            // Plain text notification — not a gap analysis payload
          }
        }

        return res.json({
          success: true,
          data: {
            status: 'completed',
            agentId: agents[0].id,
            phoneNumber: subscription.twilioPhoneNumber || null,
            message: 'Setup complete',
            gapAnalysis, // null if extraction was complete; object if MVO modal should open
          }
        });
      }

      // If no subscription yet, still in progress (email just verified, provisioning not started)
      if (!subscription) {
        console.log(`⏳ No subscription yet for user ${userId}`);
        return res.json({
          success: true,
          data: {
            status: 'in_progress',
            message: 'Starting setup...'
          }
        });
      }

      // Check subscription provisioning status
      const status = subscription.provisioningStatus;

      if (status === 'in_progress') {
        console.log(`⏳ Provisioning in progress for user ${userId}`);
        return res.json({
          success: true,
          data: {
            status: 'in_progress',
            message: 'Setting up your AI agent...'
          }
        });
      } else if (status === 'failed') {
        console.log(`❌ Provisioning failed for user ${userId}`);
        return res.json({
          success: true,
          data: {
            status: 'failed',
            message: 'Setup failed. Please try manual setup.',
            error: 'Provisioning failed'
          }
        });
      } else {
        // Status is null or pending
        console.log(`⏳ Provisioning status is ${status} for user ${userId}`);
        return res.json({
          success: true,
          data: {
            status: 'in_progress',
            message: 'Preparing your setup...'
          }
        });
      }

    } catch (error: any) {
      console.error('Provisioning status error:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to check status'
      });
    }
  });


