      const firstName = dbUser?.firstName || user.claims.first_name || '';
      const lastName = dbUser?.lastName || user.claims.last_name || '';
      const email = dbUser?.email || user.claims.email || '';

      // Construct full name from firstName and lastName
      const name = firstName && lastName
        ? `${firstName} ${lastName}`.trim()
        : firstName || lastName || '';

