  // Email verification link handler
  app.get('/verify-email', async (req, res) => {
    try {
      const { token } = req.query;

      if (!token || typeof token !== 'string') {
        return res.status(400).send(`
          <html>
            <head><title>Invalid Verification Link</title></head>
            <body style="font-family: Arial, sans-serif; text-align: center; padding: 50px;">
              <h2 style="color: #ef4444;">Invalid Verification Link</h2>
              <p>The verification link is invalid or missing.</p>
              <a href="/" style="color: #0891b2;">Return to Home</a>
            </body>
          </html>
        `);
      }

      // Find user with this verification token
      const user = await storage.getUserByVerificationToken(token);

      if (!user) {
        return res.status(400).send(`
          <html>
            <head><title>Invalid Verification Link</title></head>
            <body style="font-family: Arial, sans-serif; text-align: center; padding: 50px;">
              <h2 style="color: #ef4444;">Invalid Verification Link</h2>
              <p>This verification link is invalid or has already been used.</p>
              <a href="/" style="color: #0891b2;">Return to Home</a>
            </body>
          </html>
        `);
      }

      // Check if token has expired
      if (user.emailVerificationExpires && new Date() > new Date(user.emailVerificationExpires)) {
        return res.status(400).send(`
          <html>
            <head><title>Expired Verification Link</title></head>
            <body style="font-family: Arial, sans-serif; text-align: center; padding: 50px;">
              <h2 style="color: #ef4444;">Expired Verification Link</h2>
              <p>This verification link has expired. Please request a new one.</p>
              <a href="/dashboard" style="color: #0891b2;">Go to Dashboard</a>
            </body>
          </html>
        `);
      }

      // Mark email as verified
      await storage.upsertUser({
        id: user.id,
        email: user.email,
        emailVerified: true,
        emailVerificationToken: null,
        emailVerificationExpires: null
      });

      console.log('Email verified for user:', user.email);

      // Create session for the user
      (req.session as any).user = {
        id: user.id,
        email: user.email,
        fullName: user.fullName,
        emailVerified: true,
        claims: {
          sub: user.id,
          email: user.email,
          name: user.fullName,
          email_verified: true
        }
      };

      // Save session
      await new Promise<void>((resolve, reject) => {
        req.session.save((err) => {
          if (err) {
            console.error('Session save error:', err);
            reject(err);
          } else {
            console.log('✅ Session created for user:', user.email);
            resolve();
          }
        });
      });

      // Start provisioning in background — this is the actual path users take when
      // clicking their email verification link. Must be triggered here, not just from
      // VerifyEmailSent or the POST handler, since GET is what the email link hits.
      const signupProgressForProvisioning = await storage.getSignupProgress(user.id);
      const websiteForProvisioning = signupProgressForProvisioning?.stepData?.website;
      if (websiteForProvisioning) {
        const userIdForProvisioning = user.id;
        const emailForProvisioning = user.email;
        (async () => {
          try {
            const { analyzeBusinessWebsite } = await import('./services/websiteAnalysisService');
            const { SubscriptionProvisioningService } = await import('./services/SubscriptionProvisioningService');
            const subscriptionId = `email-signup-${userIdForProvisioning}`;

            const existingSubscription = await storage.getUserSubscription(userIdForProvisioning);
            if (!existingSubscription) {
              const planId = await ensureTrialPlanExists();
              const trialEnd = new Date();
              trialEnd.setDate(trialEnd.getDate() + 14);
              await storage.createUserSubscription({
                id: subscriptionId,
                userId: userIdForProvisioning,
                stripeCustomerId: `temp_${userIdForProvisioning}`,
                stripeSubscriptionId: subscriptionId,
                stripePriceId: 'trial_price',
                planId,
                status: 'trialing',
                currentPeriodStart: new Date(),
                currentPeriodEnd: trialEnd,
                trialEnd,
                provisioningStatus: null,
              });
              console.log(`✅ Created trial subscription for GET /verify-email provisioning: ${subscriptionId}`);
            }

            const analysis = await analyzeBusinessWebsite(websiteForProvisioning);
            let businessInfoText: string;
            if (analysis.success) {
              businessInfoText = [
                `Business Name: ${analysis.businessName}`,
                `Industry: ${analysis.industry}`,
                `Description: ${analysis.description}`,
                `Website: ${websiteForProvisioning}`,
                analysis.phoneNumber ? `Phone: ${analysis.phoneNumber}` : '',
                analysis.address ? `Address: ${analysis.address}` : '',
              ].filter(Boolean).join('\n');
            } else {
              // Website analysis failed — use minimal info so provisioning still proceeds
              console.warn(`⚠️ Website analysis failed for GET /verify-email, using fallback info`);
              businessInfoText = `Website: ${websiteForProvisioning}`;
            }

            const provisioningService = new SubscriptionProvisioningService();
            await provisioningService.provisionSubscription(userIdForProvisioning, subscriptionId, businessInfoText);
            console.log(`✅ GET /verify-email automatic provisioning completed for user ${emailForProvisioning}`);
          } catch (error) {
            console.error('GET /verify-email auto-provisioning failed:', error);
          }
        })();
      }

      // Redirect to loading dashboard page
      res.redirect(`/loading-dashboard?userId=${user.id}`);

    } catch (error) {
      console.error('Email verification error:', error);
      res.status(500).send(`
        <html>
          <head><title>Verification Error</title></head>
          <body style="font-family: Arial, sans-serif; text-align: center; padding: 50px;">
            <h2 style="color: #ef4444;">Verification Error</h2>
            <p>An error occurred while verifying your email. Please try again.</p>
            <a href="/" style="color: #0891b2;">Return to Home</a>
          </body>
        </html>
      `);
    }
  });

  // Change email endpoint
  app.post('/api/auth/change-email', async (req, res) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Unauthorized" });
    }

    const user = req.user as any;
    if (!user || !user.claims) {
      return res.status(401).json({ message: "Unauthorized" });
    }

    try {
      const userId = user.claims.sub;
      const { newEmail, password } = req.body;

      if (!newEmail || !password) {
        return res.status(400).json({ message: 'New email and password are required' });
      }

      // Validate email format
      if (!directAuthService.validateEmail(newEmail)) {
        return res.status(400).json({ message: 'Please enter a valid email address' });
      }

      // Check if email is already taken
      const existingUser = await storage.getUserByEmail(newEmail);
      if (existingUser && existingUser.id !== userId) {
        return res.status(409).json({ message: 'Email is already in use by another account' });
      }

      // In a real implementation, you'd verify the password here
      // For demo purposes, we'll skip password verification

      // Update user email
      await storage.upsertUser({
        id: userId,
        email: newEmail,
      });

      res.json({ success: true, message: 'Email updated successfully' });
    } catch (error) {
      console.error('Change email error:', error);
      res.status(500).json({ message: 'Failed to update email' });
    }
  });

