  // **NEW: User Profile Management Endpoints**
  
  // Zod schemas for validation
  const updateProfileSchema = z.object({
    name: z.string().min(1, "Name cannot be empty").optional(),
    email: z.string().email("Please enter a valid email address").optional(),
    phoneNumber: z.string().min(1, "Phone number cannot be empty").optional(),
    enableCallTransfer: z.boolean().optional(),
    enableSMS: z.boolean().optional(),
  }).refine((data) => data.name || data.email || data.phoneNumber || data.enableCallTransfer !== undefined || data.enableSMS !== undefined, {
    message: "At least one field is required"
  });

  const updatePasswordSchema = z.object({
    currentPassword: z.string().min(1, "Current password is required"),
    newPassword: z.string().min(8, "New password must be at least 8 characters long"),
    confirmPassword: z.string().min(1, "Password confirmation is required"),
  }).refine((data) => data.newPassword === data.confirmPassword, {
    message: "New passwords do not match",
    path: ["confirmPassword"]
  });

  // Update user profile (name or email)
  app.patch('/api/user/profile', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      
      // Validate request body with Zod
      const validation = updateProfileSchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ 
          error: validation.error.errors[0].message,
          details: validation.error.errors
        });
      }

      const { name, email, phoneNumber, enableCallTransfer, enableSMS } = validation.data;
      const updateData: any = { id: userId };
      
      // Handle name update
      if (name !== undefined) {
        const nameParts = name.trim().split(' ');
        updateData.firstName = nameParts[0];
        updateData.lastName = nameParts.slice(1).join(' ');
      }

      // Handle email update
      if (email !== undefined) {
        // Check if email is already taken by another user
        const existingUser = await storage.getUserByEmail(email);
        if (existingUser && existingUser.id !== userId) {
          return res.status(409).json({ 
            error: "Email is already in use by another account" 
          });
        }
        
        updateData.email = email;
      }

      // Handle phone number update
      if (phoneNumber !== undefined) {
        // Format phone number to E.164 format for consistency
        try {
          // Basic phone number formatting to E.164
          let formattedPhone = phoneNumber.replace(/[^\d+]/g, '');

          // If already has + prefix and is valid length, use as-is
          if (formattedPhone.startsWith('+') && formattedPhone.length >= 11) {
            updateData.phoneNumber = formattedPhone;
          }
          // If it's a 10-digit US number, add +1 prefix
          else if (formattedPhone.length === 10) {
            updateData.phoneNumber = `+1${formattedPhone}`;
          }
          // If it's an 11-digit number starting with 1, add + prefix
          else if (formattedPhone.length === 11 && formattedPhone.startsWith('1')) {
            updateData.phoneNumber = `+${formattedPhone}`;
          }
          // Otherwise use as-is and let Twilio validate it
          else {
            updateData.phoneNumber = formattedPhone.startsWith('+') ? formattedPhone : `+${formattedPhone}`;
          }

          console.log(`📱 Formatted phone number: ${phoneNumber} → ${updateData.phoneNumber}`);
        } catch (error) {
          console.error('Error formatting phone number:', error);
          // Fall back to using the original phone number
          updateData.phoneNumber = phoneNumber;
        }
      }

      // Handle call transfer setting
      if (enableCallTransfer !== undefined) {
        updateData.enableCallTransfer = enableCallTransfer;
      }

      // Handle SMS alerts setting
      if (enableSMS !== undefined) {
        updateData.enableSMS = enableSMS;
      }

      // Update user in database
      const updatedUser = await storage.upsertUser(updateData);
      
      console.log(`✅ User profile updated for: ${userId}`, { name, email, phoneNumber });
      
      res.json({
        success: true,
        message: "Profile updated successfully",
        user: {
          id: updatedUser.id,
          email: updatedUser.email,
          phoneNumber: updatedUser.phoneNumber,
          enableCallTransfer: updatedUser.enableCallTransfer,
          enableSMS: updatedUser.enableSMS,
          name: updatedUser.firstName && updatedUser.lastName 
            ? `${updatedUser.firstName} ${updatedUser.lastName}`.trim()
            : updatedUser.firstName || updatedUser.lastName || ''
        }
      });

    } catch (error) {
      console.error('❌ Error updating user profile:', error);
      res.status(500).json({ 
        error: "Failed to update profile",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

