  // Change password (requires current password)
  app.post('/api/user/change-password', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims?.sub || req.user.id;
      const { currentPassword, newPassword } = req.body;

      if (!currentPassword || !newPassword) {
        return res.status(400).json({ error: "Current password and new password are required" });
      }

      if (newPassword.length < 8) {
        return res.status(400).json({ error: "New password must be at least 8 characters long" });
      }

      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      // Check if user has a password (direct auth user)
      if (!user.passwordHash) {
        return res.status(400).json({
          error: "Password management not available for this account type. Please use your OAuth provider (Google/Replit) to change your password."
        });
      }

      // Verify current password
      const isPasswordValid = await directAuthService.verifyPassword(currentPassword, user.passwordHash);
      if (!isPasswordValid) {
        return res.status(401).json({ error: "Current password is incorrect" });
      }

      // Hash and update the new password
      const newPasswordHash = await directAuthService.hashPassword(newPassword);
      await storage.upsertUser({
        id: userId,
        passwordHash: newPasswordHash
      });

      console.log('✅ Password changed successfully for user:', userId);

      res.json({
        success: true,
        message: "Password changed successfully"
      });

    } catch (error: any) {
      console.error('❌ Error processing password change:', error);
      res.status(500).json({
        error: "Failed to process password change",
        message: error.message
      });
    }
  });

