  // Google OAuth routes
  app.get('/api/auth/google', (req, res) => {
    const { signup, inviteToken, website } = req.query;
    const authUrl = googleAuthService.getAuthUrl();

    // Store signup flag in session to redirect appropriately after callback
    if (signup === 'true') {
      (req as any).session.isSignup = true;
    }

    // Store invite token in session to handle invitation acceptance after OAuth
    if (inviteToken) {
      (req as any).session.inviteToken = inviteToken;
    }

    // Store website in session so it can be pre-filled after OAuth callback
    if (website) {
      (req as any).session.pendingWebsite = website;
    }

    res.redirect(authUrl);
  });

  // Google OAuth callback route
  app.get('/api/auth/google/callback', async (req, res) => {
    try {
      const { code } = req.query;

      if (!code) {
        return res.redirect('/signup?error=oauth_failed');
      }

      const { user, sessionUser, isNewUser } = await googleAuthService.handleCallback(code as string);

      // Set up session manually
      (req as any).session.passport = { user: sessionUser };

      // Check if there's an invitation to accept
      const inviteToken = (req as any).session.inviteToken;

      // Capture and clean up session flags
      const pendingWebsite = (req as any).session.pendingWebsite;
      delete (req as any).session.isSignup;
      delete (req as any).session.inviteToken;
      delete (req as any).session.pendingWebsite;

      // Ensure session is saved before proceeding
      (req as any).session.save(async (err: any) => {
        if (err) {
          console.error('Session save error:', err);
          return res.redirect('/signup?error=session_failed');
        }

        // If there's an invitation token, try to accept it
        if (inviteToken) {
          try {
            // Find the invitation
            const [invitation] = await db
              .select()
              .from(teamInvitations)
              .where(eq(teamInvitations.inviteToken, inviteToken))
              .limit(1);

            if (invitation && invitation.status === 'pending' && new Date() <= new Date(invitation.expiresAt)) {
              // Check if user's email matches invitation email
              if (user.email.toLowerCase() === invitation.email.toLowerCase()) {
                // Check if not already a team member
                const [existingMember] = await db
                  .select()
                  .from(teamMembers)
                  .where(and(
                    eq(teamMembers.userId, user.id),
                    eq(teamMembers.ownerId, invitation.ownerId)
                  ))
                  .limit(1);

                if (!existingMember) {
                  // Add user to team
                  await db.insert(teamMembers).values({
                    ownerId: invitation.ownerId,
                    userId: user.id,
                    role: invitation.role,
                    assignedAgentIds: invitation.assignedAgentIds || null,
                    status: 'active'
                  });

                  // Mark invitation as accepted
                  await db
                    .update(teamInvitations)
                    .set({
                      status: 'accepted',
                      acceptedAt: new Date(),
                      acceptedByUserId: user.id,
                      updatedAt: new Date()
                    })
                    .where(eq(teamInvitations.inviteToken, inviteToken));

                  console.log(`✅ User ${user.id} accepted team invitation via Google OAuth`);

                  // Redirect to dashboard with owner context
                  return res.redirect(`/dashboard?inviteAccepted=true&ownerId=${invitation.ownerId}`);
                }
              }
            }
          } catch (inviteError) {
            console.error('Error accepting invitation after OAuth:', inviteError);
            // Continue to normal flow even if invitation fails
          }
        }

        // Normal flow without invitation
        if (isNewUser) {
          // New Google OAuth user - redirect to signup page for website input
          const setupUrl = pendingWebsite
            ? `/signup?google_setup=true&website=${encodeURIComponent(String(pendingWebsite))}`
            : '/signup?google_setup=true';
          res.redirect(setupUrl);
        } else {
          // Redirect to dashboard for all existing users
          res.redirect('/dashboard');
        }
      });

    } catch (error) {
      console.error('Google OAuth callback error:', error);
      res.redirect('/signup?error=oauth_failed');
    }
  });

