  // User credentials management endpoints (for secure API key storage)
  // Save encrypted user credentials
  app.post('/api/user/credentials', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { integrationType, credentialName, value, isActive } = req.body;

      // Validate input
      if (!integrationType || !credentialName || !value) {
        return res.status(400).json({ error: "Missing required fields" });
      }

      // Validate integration type (restrict to known types)
      const validIntegrationTypes = ['square_pos', 'google_calendar', 'retell_ai'];
      if (!validIntegrationTypes.includes(integrationType)) {
        return res.status(400).json({ error: "Invalid integration type" });
      }

      // Encrypt the plaintext value server-side
      const encryptionResult = EncryptionService.encrypt(value);

      const credentialsData = {
        userId,
        integrationType,
        credentialName,
        encryptedData: encryptionResult.encryptedData,
        encryptionIv: encryptionResult.iv,
        encryptionTag: encryptionResult.tag,
        encryptionAlgorithm: encryptionResult.algorithm,
        encryptionVersion: encryptionResult.version,
        isActive: isActive ?? true
      };

      const credentials = await storage.upsertUserCredentials(credentialsData);
      
      // Never return encrypted values - only metadata
      res.json({
        success: true,
        credentials: {
          id: credentials.id,
          integrationType: credentials.integrationType,
          credentialName: credentials.credentialName,
          isActive: credentials.isActive,
          createdAt: credentials.createdAt,
          updatedAt: credentials.updatedAt
        }
      });
    } catch (error) {
      console.error("Error saving user credentials:", error);
      res.status(500).json({ error: "Failed to save credentials" });
    }
  });

