  // **NEW: Webhook Proxy Endpoints for n8n Integration**
  // These endpoints act as a proxy between Retell AI and n8n, injecting decrypted credentials
  
  app.post('/api/webhook/n8n/:action', async (req: any, res) => {
    try {
      const { action } = req.params;
      const payload = req.body;

      console.log(`🔗 Webhook proxy call for action: ${action}`);

      // Extract call context from the payload or headers
      const callContext = {
        phone_number: payload.phone_number || req.headers['x-phone-number'],
        agent_id: payload.agent_id || req.headers['x-agent-id'], 
        call_sid: payload.call_sid || req.headers['x-call-sid'],
        user_id: payload.user_id || req.headers['x-user-id']
      };

      // Determine the actual n8n webhook URL based on action
      const webhookUrl = process.env.N8N_WEBHOOK_URL || '';

      // Use the webhook middleware to inject credentials and forward to n8n
      const { webhookMiddlewareService } = await import('./services/webhookMiddlewareService');
      const response = await webhookMiddlewareService.callWebhookWithCredentials(
        webhookUrl, 
        {
          action,
          data: payload,
          call_context: callContext
        },
        callContext
      );

      // Forward n8n's response back to Retell AI
      const responseBody = await response.text();
      res.status(response.status).send(responseBody);
      
      console.log(`✅ Webhook proxy completed for action: ${action}, status: ${response.status}`);
    } catch (error) {
      console.error('❌ Webhook proxy error:', error);
      res.status(500).json({ 
        error: "Webhook proxy failed",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

