  // Retell AI webhook for incoming orders
  app.post('/api/retell/webhook/order', async (req: any, res) => {
    try {
      console.log('📦 Retell AI order webhook received:', JSON.stringify(req.body, null, 2));

      const orderData = req.body;

      // Handle different webhook payload structures from Retell AI
      const callData = orderData.call || orderData;
      const callId = callData.call_id || orderData.call_id || callData.retell_call_id || callData.call_id_twilio;
      const agentId = callData.agent_id || orderData.agent_id;
      const fromNumber = callData.from_number || orderData.from_number || orderData.customer_phone;
      const toNumber = callData.to_number || orderData.to_number || orderData.phone_number;

      console.log('🔍 Looking for user with:', { callId, agentId, fromNumber, toNumber });

      // Find the user by phone number or agent ID
      let userId: string | null = null;

      // Try to find by agent ID first
      if (agentId) {
        console.log('🔍 Searching by agent_id:', agentId);
        const allAgents = await db.select().from(voiceAgents).where(eq(voiceAgents.retellAgentId, agentId));
        console.log(`📋 Found ${allAgents.length} agents with agent_id ${agentId}`);
        if (allAgents.length > 0) {
          userId = allAgents[0].userId;
          console.log('✅ Found user by agent_id:', userId);
        }
      }

      // Try to find by phone number if not found
      if (!userId && toNumber) {
        console.log('🔍 Searching by phone number:', toNumber);
        const phoneAssignment = await storage.getPhoneNumberAssignmentByNumber(toNumber);
        if (phoneAssignment) {
          userId = phoneAssignment.userId;
          console.log('✅ Found user by phone number:', userId);
        } else {
          console.log('❌ No phone assignment found for:', toNumber);
        }
      }

      if (!userId) {
        console.error('❌ Could not find user for order webhook. Searched with:', { agentId, toNumber });

        return res.status(404).json({
          status: 'error',
          message: 'User not found',
          call_id: callId,
          debug: { agentId, toNumber, fromNumber }
        });
      }

      console.log('✅ Processing order for user:', userId);

      // Get business settings with Square integration
      const businessSettings = await storage.getBusinessSettings(userId);
      if (!businessSettings || !businessSettings.customIntegrations) {
        console.error('❌ No business settings found for user:', userId);
        return res.status(404).json({
          status: 'error',
          message: 'Business settings not configured',
          call_id: callId
        });
      }

      // Find Square POS integration
      const squareIntegration = businessSettings.customIntegrations.find(
        (integration: any) => integration.name === 'Square POS' || integration.type === 'POS'
      );

      if (!squareIntegration) {
        console.error('❌ No Square POS integration found for user:', userId);
        return res.status(404).json({
          status: 'error',
          message: 'Square POS not configured',
          call_id: callId
        });
      }

      console.log('✅ Found Square integration:', {
        locationId: squareIntegration.locationId,
        sandboxMode: squareIntegration.sandboxMode
      });

      // Prepare order data for Square
      // Extract items from various possible locations in the payload
      const orderDetails = orderData.order_details || orderData.args || orderData;
      const items = orderDetails.items || orderData.items || orderData.order_items || [];

      console.log('📦 Extracted order items:', items);

      const lineItems = items.map((item: any) => {
        // Square requires price in cents (integer)
        const priceInCents = Math.round((item.price || 0) * 100);

        // Build note with modifiers and special instructions
        const modifiersText = item.modifiers && item.modifiers.length > 0
          ? `Modifiers: ${item.modifiers.join(', ')}`
          : '';
        const instructionsText = item.specialInstructions || item.notes || '';
        const noteText = [modifiersText, instructionsText].filter(Boolean).join(' | ');

        return {
          name: item.name,
          quantity: String(item.quantity || 1),
          base_price_money: {
            amount: priceInCents,
            currency: 'USD'
          },
          note: noteText
        };
      });

      const squareOrderPayload = {
        idempotency_key: `retell-${callId}-${Date.now()}`,
        location_id: squareIntegration.locationId,
        order: {
          location_id: squareIntegration.locationId,
          line_items: lineItems,
          metadata: {
            source: 'retell_ai',
            call_id: callId,
            customer_phone: fromNumber,
            order_type: orderData.order_type || orderData.orderType || 'takeout'
          }
        }
      };

      // Determine Square API URL
      const squareApiUrl = squareIntegration.sandboxMode
        ? 'https://connect.squareupsandbox.com/v2/orders'
        : 'https://connect.squareup.com/v2/orders';

      console.log('🔄 Sending order to Square API:', squareApiUrl);
      console.log('📦 Square order payload:', JSON.stringify(squareOrderPayload, null, 2));

      // Send order to Square
      const squareResponse = await fetch(squareApiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${squareIntegration.apiKey}`,
          'Square-Version': '2023-10-18'
        },
        body: JSON.stringify(squareOrderPayload)
      });

      const squareData = await squareResponse.json();

      if (!squareResponse.ok) {
        console.error('❌ Square API error:', squareData);
        return res.status(500).json({
          status: 'error',
          message: 'Failed to create order in Square POS',
          error: squareData.errors?.[0]?.detail || 'Unknown error',
          call_id: callId
        });
      }

      console.log('✅ Order created in Square:', squareData.order?.id);

      // Increment order count
      await storage.updateBusinessSettings(userId, {
        orderCount: (businessSettings.orderCount || 0) + 1
      });

      // Return success to Retell AI
      res.json({
        status: 'success',
        message: `Great! I've placed your order. Your order number is ${squareData.order?.id}.`,
        confirmation_id: squareData.order?.id,
        call_id: callId,
        data: squareData.order
      });

    } catch (error) {
      console.error('❌ Retell AI order webhook error:', error);
      res.status(500).json({
        status: 'error',
        message: 'Failed to process order',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

