  // Helper function to send responses back to Retell AI
  async function sendRetellAIResponse(callId: string, responseData: any) {
    const retellApiKey = process.env.RETELL_API_KEY;
    if (!retellApiKey) {
      throw new Error('RETELL_API_KEY not configured');
    }

    const response = await fetch(`https://api.retellai.com/update-call`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${retellApiKey}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        call_id: callId,
        response: {
          status: responseData.status,
          message: responseData.message
        }
      })
    });

    if (!response.ok) {
      throw new Error(`Retell AI API error: ${response.status} ${response.statusText}`);
    }

    return await response.json();
  }

