  // Save or update business settings for the authenticated user
  app.post('/api/business-settings', isAuthenticated, async (req: any, res) => {
    try {
      const userId = await getActiveUserId(req);
      const settingsData = req.body;
      
      console.log(`💾 Saving business settings for user: ${userId}`);
      console.log('📋 Settings data:', JSON.stringify(settingsData, null, 2));

      // Validate required fields
      if (typeof settingsData.acceptOrders !== 'boolean' || 
          typeof settingsData.acceptReservations !== 'boolean') {
        return res.status(400).json({ 
          error: "Invalid business settings data",
          message: "acceptOrders and acceptReservations must be boolean values"
        });
      }
      
      // Validate owner fallback settings if provided
      if (settingsData.enableOwnerFallback && !settingsData.ownerPhoneNumber) {
        return res.status(400).json({
          error: "Owner phone number required",
          message: "When owner fallback is enabled, owner phone number must be provided"
        });
      }

      const settings = await storage.upsertBusinessSettings({
        userId,
        acceptOrders: settingsData.acceptOrders,
        acceptReservations: settingsData.acceptReservations,
        acceptAfterHours: settingsData.acceptAfterHours ?? false,
        businessHours: settingsData.businessHours,
        timezone: settingsData.timezone || 'America/New_York',
        orderCutoffTime: settingsData.orderCutoffTime || '21:30',
        reservationLeadTime: settingsData.reservationLeadTime || 60,
        enableOwnerFallback: settingsData.enableOwnerFallback ?? false,
        ownerPhoneNumber: settingsData.ownerPhoneNumber || null,
        isActive: true
      });

      console.log('✅ Business settings saved successfully:', settings);
      res.json(settings);
    } catch (error) {
      console.error('❌ Error saving business settings:', error);
      res.status(500).json({
        error: "Failed to save business settings",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

