  // **Middleware to handle viewAsUserId for team members**
  const getActiveUserId = async (req: any): Promise<string> => {
    const loggedInUserId = req.user.claims.sub;
    const viewAsUserId = req.query.viewAsUserId;

    // If no viewAsUserId, return the logged-in user's ID
    if (!viewAsUserId) {
      return loggedInUserId;
    }

    // Verify that the logged-in user is a team member of the viewAsUserId
    const membership = await storage.getTeamMembershipByUserId(loggedInUserId);
    
    if (membership && membership.ownerId === viewAsUserId && membership.status === 'active') {
      // User is a valid team member, allow them to view as the owner
      return viewAsUserId;
    }

    // User is not authorized to view as this user, return their own ID
    return loggedInUserId;
  };

  // **Team/Member Management Endpoints**

  // Get team membership for current user (returns owner ID if user is a team member)
  app.get('/api/team/my-membership', isAuthenticated, async (req: any, res) => {
    try {
      // IMPORTANT: Always check the ACTUAL logged-in user's membership, not viewingOwnerId
      const userId = req.user.claims.sub;

      // Check if current user is a team member of anyone
      const membership = await storage.getTeamMembershipByUserId(userId);

      if (membership) {
        // User is a team member, return owner info with permissions
        const { getDefaultPermissions, mergePermissions } = await import('./rolePermissions');
        const effectivePermissions = membership.permissions || getDefaultPermissions(membership.role);

        return res.json({
          success: true,
          isTeamMember: true,
          ownerId: membership.ownerId,
          role: membership.role,
          permissions: effectivePermissions,
          status: membership.status
        });
      }

      // User is not a team member
      res.json({
        success: true,
        isTeamMember: false,
        ownerId: null
      });
    } catch (error: any) {
      console.error("Error checking team membership:", error);
      res.status(500).json({
        success: false,
        message: "Failed to check team membership"
      });
    }
  });

  // Get active user ID (for team members viewing owner's dashboard)
  app.get('/api/team/active-user-id', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { ownerId } = req.query;

      // If no ownerId specified, return current user
      if (!ownerId) {
        return res.json({
          success: true,
          activeUserId: userId,
          isTeamMember: false
        });
      }

      // Check if current user is a team member of the specified owner
      const [membership] = await db
        .select()
        .from(teamMembers)
        .where(and(
          eq(teamMembers.userId, userId),
          eq(teamMembers.ownerId, ownerId),
          eq(teamMembers.status, 'active')
        ))
        .limit(1);

      if (membership) {
        // User is a valid team member, allow them to view owner's dashboard
        return res.json({
          success: true,
          activeUserId: ownerId,
          isTeamMember: true,
          memberRole: membership.role
        });
      }

      // User is not a team member, return their own ID
      res.json({
        success: true,
        activeUserId: userId,
        isTeamMember: false
      });
    } catch (error: any) {
      console.error("Error getting active user ID:", error);
      res.status(500).json({
        success: false,
        message: "Failed to determine active user"
      });
    }
  });

  // Get team members for the authenticated user
  app.get('/api/team/members', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;

      // Get team members where the current user is the owner with user details joined
      const teamMembersFromDb = await db
        .select({
          id: teamMembers.userId,
          role: teamMembers.role,
          permissions: teamMembers.permissions,
          assignedAgentIds: teamMembers.assignedAgentIds,
          status: teamMembers.status,
          joinedAt: teamMembers.joinedAt,
          lastActive: teamMembers.lastActive,
          firstName: users.firstName,
          lastName: users.lastName,
          email: users.email
        })
        .from(teamMembers)
        .innerJoin(users, eq(teamMembers.userId, users.id))
        .where(eq(teamMembers.ownerId, userId));

      // Import role permissions helper
      const { getDefaultPermissions } = await import('./rolePermissions');

      // Format team members
      const membersWithDetails = teamMembersFromDb.map((member) => ({
        id: member.id,
        name: member.firstName && member.lastName
          ? `${member.firstName} ${member.lastName}`
          : member.firstName || member.email || 'No Name',
        email: member.email || '',
        role: member.role,
        permissions: member.permissions || getDefaultPermissions(member.role),
        assignedAgentIds: member.assignedAgentIds || null,
        status: member.status,
        joinedAt: member.joinedAt?.toISOString() || new Date().toISOString(),
        lastActive: member.lastActive?.toISOString() || member.joinedAt?.toISOString() || new Date().toISOString()
      }));

      // Get owner details from the users table
      const ownerData = await db
        .select({
          firstName: users.firstName,
          lastName: users.lastName,
          email: users.email
        })
        .from(users)
        .where(eq(users.id, userId))
        .limit(1);

      const ownerUser = ownerData[0];
      const owner = {
        id: userId,
        name: ownerUser?.firstName && ownerUser?.lastName
          ? `${ownerUser.firstName} ${ownerUser.lastName}`
          : ownerUser?.firstName || req.user.name || req.user.email || 'Owner',
        email: ownerUser?.email || req.user.email,
        role: 'owner',
        permissions: getDefaultPermissions('owner'), // Owner gets full permissions
        assignedAgentIds: null,
        status: 'active',
        joinedAt: new Date().toISOString(),
        lastActive: new Date().toISOString(),
        isOwner: true,
        isCurrentUser: true
      };

      // Get pending invitations
      const pendingInvitations = await db
        .select()
        .from(teamInvitations)
        .where(and(
          eq(teamInvitations.ownerId, userId),
          eq(teamInvitations.status, 'pending')
        ));

      // Format pending invitations as table members
      const invitationsAsMembers = pendingInvitations.map((inv) => ({
        id: inv.id,
        name: inv.email,
        email: inv.email,
        role: inv.role,
        permissions: inv.permissions || getDefaultPermissions(inv.role),
        assignedAgentIds: inv.assignedAgentIds || null,
        status: 'invited' as const,
        joinedAt: inv.createdAt?.toISOString() || new Date().toISOString(),
        lastActive: null,
        isPending: true,
        invitationId: inv.id,
        expiresAt: inv.expiresAt?.toISOString()
      }));

      const members = [owner, ...membersWithDetails, ...invitationsAsMembers];

      res.json({ members });
    } catch (error) {
      console.error("Error fetching team members:", error);
      res.status(500).json({ message: "Failed to fetch team members" });
    }
  });

  // Accept invitation (after signup/login)
  app.post('/api/team/accept-invite', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { token } = req.body;

      if (!token) {
        return res.status(400).json({
          success: false,
          message: "Invitation token is required"
        });
      }

      // Find the invitation
      const [invitation] = await db
        .select()
        .from(teamInvitations)
        .where(eq(teamInvitations.inviteToken, token))
        .limit(1);

      if (!invitation) {
        return res.status(404).json({
          success: false,
          message: "Invitation not found"
        });
      }

      // Check if invitation is expired
      if (new Date() > new Date(invitation.expiresAt)) {
        return res.status(400).json({
          success: false,
          message: "Invitation has expired"
        });
      }

      // Check if already accepted
      if (invitation.status === 'accepted') {
        return res.status(400).json({
          success: false,
          message: "Invitation has already been accepted"
        });
      }

      // Check if revoked
      if (invitation.status === 'revoked') {
        return res.status(400).json({
          success: false,
          message: "Invitation has been revoked"
        });
      }

      // Check if the user's email matches the invitation email
      const user = await storage.getUser(userId);
      if (user?.email !== invitation.email) {
        return res.status(403).json({
          success: false,
          message: "This invitation was sent to a different email address"
        });
      }

      // Check if user is already a team member of this owner
      const [existingMember] = await db
        .select()
        .from(teamMembers)
        .where(and(
          eq(teamMembers.userId, userId),
          eq(teamMembers.ownerId, invitation.ownerId)
        ))
        .limit(1);

      if (existingMember) {
        return res.status(400).json({
          success: false,
          message: "You are already a member of this team"
        });
      }

      // Add user to team
      await db.insert(teamMembers).values({
        ownerId: invitation.ownerId,
        userId: userId,
        role: invitation.role,
        permissions: invitation.permissions || null, // Save custom permissions from invitation
        assignedAgentIds: invitation.assignedAgentIds || null, // Save assigned agent IDs from invitation
        status: 'active'
      });

      // Mark invitation as accepted
      await db
        .update(teamInvitations)
        .set({
          status: 'accepted',
          acceptedAt: new Date(),
          acceptedByUserId: userId,
          updatedAt: new Date()
        })
        .where(eq(teamInvitations.inviteToken, token));

      console.log(`✅ User ${userId} accepted team invitation from ${invitation.ownerId} with role ${invitation.role}`);

      res.json({
        success: true,
        message: "Invitation accepted successfully",
        ownerId: invitation.ownerId,
        role: invitation.role,
        businessName: invitation.businessName
      });
    } catch (error: any) {
      console.error("Error accepting invitation:", error);
      res.status(500).json({
        success: false,
        message: "Failed to accept invitation"
      });
    }
  });

  // Verify invitation token
  app.get('/api/team/verify-invite', async (req, res) => {
    try {
      const { token } = req.query;

      if (!token || typeof token !== 'string') {
        return res.status(400).json({
          success: false,
          message: "Invalid invitation token"
        });
      }

      // Find the invitation
      const [invitation] = await db
        .select()
        .from(teamInvitations)
        .where(eq(teamInvitations.inviteToken, token))
        .limit(1);

      if (!invitation) {
        return res.status(404).json({
          success: false,
          message: "Invitation not found"
        });
      }

      // Check if invitation is expired
      if (new Date() > new Date(invitation.expiresAt)) {
        return res.status(400).json({
          success: false,
          message: "Invitation has expired"
        });
      }

      // Check if invitation was already accepted
      if (invitation.status === 'accepted') {
        return res.status(400).json({
          success: false,
          message: "Invitation has already been accepted"
        });
      }

      // Check if invitation was revoked
      if (invitation.status === 'revoked') {
        return res.status(400).json({
          success: false,
          message: "Invitation has been revoked"
        });
      }

      // Get inviter's email
      const inviter = await storage.getUser(invitation.ownerId);
      const inviterEmail = inviter?.email || '';

      res.json({
        success: true,
        invitation: {
          email: invitation.email,
          role: invitation.role,
          inviterName: invitation.inviterName,
          inviterEmail: inviterEmail,
          businessName: invitation.businessName,
          expiresAt: invitation.expiresAt
        }
      });
    } catch (error: any) {
      console.error("Error verifying invitation:", error);
      res.status(500).json({
        success: false,
        message: "Failed to verify invitation"
      });
    }
  });

  // Invite a new team member
  app.post('/api/team/invite', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { email, role, permissions, assignedAgentIds } = req.body;

      if (!email || !role) {
        return res.status(400).json({ message: "Email and role are required" });
      }

      // Validate email format
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        return res.status(400).json({ message: "Invalid email format" });
      }

      // Validate role
      const validRoles = ['owner', 'manager', 'employee', 'custom'];
      if (!validRoles.includes(role.toLowerCase())) {
        return res.status(400).json({ message: "Invalid role" });
      }

      // Validate custom permissions if role is 'custom'
      if (role.toLowerCase() === 'custom' && !permissions) {
        return res.status(400).json({ message: "Custom permissions are required for custom role" });
      }

      // Get inviter's role/permissions to check if they can add this role
      const inviterUserId = req.actualUserId || req.user.claims.sub;
      const [inviterMembership] = await db
        .select()
        .from(teamMembers)
        .where(and(
          eq(teamMembers.userId, inviterUserId),
          eq(teamMembers.ownerId, userId)
        ))
        .limit(1);

      const inviterRole = inviterMembership?.role || (inviterUserId === userId ? 'owner' : null);

      // Check permissions based on inviter role
      if (inviterRole === 'employee') {
        return res.status(403).json({ message: "Employees cannot invite team members" });
      }

      if (inviterRole === 'custom') {
        // Custom roles can only invite if explicitly granted permission
        // For now, we'll restrict custom roles from inviting
        return res.status(403).json({ message: "You don't have permission to invite team members" });
      }

      if (inviterRole === 'manager' && role.toLowerCase() === 'owner') {
        return res.status(403).json({ message: "Managers cannot add Owner roles" });
      }

      // Get inviter's information
      const inviter = await storage.getUser(userId);
      const businessInfo = await storage.getBusinessInfo(userId);
      const inviterName = inviter?.firstName && inviter?.lastName
        ? `${inviter.firstName} ${inviter.lastName}`
        : inviter?.firstName || '';
      const inviterEmail = inviter?.email || '';
      const inviterDisplay = inviterName || inviterEmail || 'Someone';
      const businessName = businessInfo?.businessName || inviterName || 'the team';

      // Generate invitation token
      const inviteToken = `invite_${Date.now()}_${Math.random().toString(36).substr(2, 16)}`;
      const inviteUrl = `${resolveBaseUrl(req)}/signup?token=${inviteToken}`;

      // Store invitation in database
      const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days from now
      await db.insert(teamInvitations).values({
        ownerId: userId,
        inviteToken,
        email,
        role: role.toLowerCase(),
        permissions: permissions || null, // Save custom permissions if provided
        assignedAgentIds: assignedAgentIds || null, // Save assigned agent IDs
        inviterName,
        businessName,
        expiresAt,
        status: 'pending'
      });

      // Send invitation email using Resend connector
      const roleDescriptions: Record<string, string> = {
        owner: 'Full access to all features and settings',
        manager: 'Manage team, conversation flows, integrations; view analytics',
        employee: 'View & edit customer records; view analytics; access call history',
        custom: 'Custom permissions assigned by Owner/Manager'
      };

      try {
        const { getUncachableResendClient } = await import('./services/resendService');
        const { client: resend } = await getUncachableResendClient();

        const { data, error } = await resend.emails.send({
          from: 'VoiceBot Invites <invites@voicebot.one>',
          to: [email],
          subject: `You've been invited to join ${businessName}`,
          html: `
            <!DOCTYPE html>
            <html>
            <head>
              <style>
                body {
                  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
                  line-height: 1.6;
                  margin: 0;
                  padding: 0;
                  background-color: #0D0D0D;
                }
                .container {
                  max-width: 600px;
                  margin: 40px auto;
                  background-color: #0D0D0D;
                }
                .logo-header {
                  text-align: center;
                  padding: 30px 20px 20px;
                  background-color: #0D0D0D;
                }
                .logo-container {
                  display: inline-flex;
                  align-items: center;
                  gap: 12px;
                  margin-bottom: 10px;
                }
                .logo {
                  width: 40px;
                  height: 40px;
                }
                .brand-name {
                  font-size: 28px;
                  font-weight: bold;
                  color: #ffffff;
                  margin: 0;
                }
                .brand-accent {
                  background: linear-gradient(to right, #60A5FA, #2563EB);
                  -webkit-background-clip: text;
                  -webkit-text-fill-color: transparent;
                  background-clip: text;
                }
                .card {
                  background: rgba(17, 24, 39, 0.6);
                  border: 1px solid rgba(75, 85, 99, 0.3);
                  border-radius: 24px;
                  padding: 40px 30px;
                  margin: 20px;
                  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.3), 0 10px 10px -5px rgba(0, 0, 0, 0.2);
                }
                .card-title {
                  font-size: 24px;
                  font-weight: bold;
                  color: #ffffff;
                  margin: 0 0 20px 0;
                  text-align: center;
                }
                .card-content {
                  color: #D1D5DB;
                  font-size: 15px;
                }
                .card-content p {
                  margin: 0 0 16px 0;
                }
                .highlight {
                  color: #ffffff;
                  font-weight: 600;
                }
                .role-badge {
                  display: inline-block;
                  padding: 8px 16px;
                  background: linear-gradient(135deg, rgba(59, 130, 246, 0.2) 0%, rgba(37, 99, 235, 0.2) 100%);
                  border: 1px solid rgba(59, 130, 246, 0.3);
                  color: #60A5FA;
                  border-radius: 20px;
                  font-weight: bold;
                  font-size: 14px;
                }
                .role-description {
                  color: #9CA3AF;
                  font-size: 14px;
                  margin-top: 10px;
                }
                .button {
                  display: inline-block;
                  padding: 16px 40px;
                  background: linear-gradient(to right, #60A5FA, #2563EB);
                  color: white;
                  text-decoration: none;
                  border-radius: 12px;
                  margin: 30px 0 20px;
                  font-weight: 600;
                  font-size: 16px;
                  box-shadow: 0 10px 15px -3px rgba(37, 99, 235, 0.3);
                }
                .button:hover {
                  background: linear-gradient(to right, #3B82F6, #1D4ED8);
                }
                .button-container {
                  text-align: center;
                }
                .note {
                  color: #9CA3AF;
                  font-size: 13px;
                  margin-top: 30px;
                  padding-top: 20px;
                  border-top: 1px solid rgba(75, 85, 99, 0.3);
                }
                .link {
                  color: #60A5FA;
                  text-decoration: none;
                  word-break: break-all;
                }
                .footer {
                  text-align: center;
                  color: #6B7280;
                  font-size: 12px;
                  margin-top: 30px;
                  padding: 20px;
                }
              </style>
            </head>
            <body>
              <div class="container">
                <div class="logo-header">
                  <div class="logo-container" style="display: inline-flex; align-items: center; gap: 12px;">
                    <img src="https://i.imgur.com/YourLogoHere.png" alt="VoiceBot" style="width: 40px; height: 40px; display: inline-block; vertical-align: middle;" />
                    <h1 class="brand-name" style="display: inline-block; font-size: 28px; font-weight: bold; color: #ffffff; margin: 0; vertical-align: middle;">Voice<span class="brand-accent" style="background: linear-gradient(to right, #60A5FA, #2563EB); -webkit-background-clip: text; -webkit-text-fill-color: transparent;">Bot</span></h1>
                  </div>
                </div>

                <div class="card">
                  <h2 class="card-title">You're Invited!</h2>

                  <div class="card-content">
                    <p>Hello!</p>

                    <p><span class="highlight">${inviterDisplay}</span> has invited you to join their dashboard.</p>

                    <p style="text-align: center; margin: 25px 0;">
                      <span class="role-badge">${role.charAt(0).toUpperCase() + role.slice(1)}</span>
                    </p>

                    <p class="role-description" style="text-align: center;">
                      ${roleDescriptions[role.toLowerCase()] || 'Access to team features'}
                    </p>

                    <div class="button-container">
                      <a href="${inviteUrl}" class="button">Accept Invitation</a>
                    </div>

                    <div class="note">
                      <p style="margin-bottom: 16px;">
                        If you didn't expect this invitation, you can safely ignore this email.
                      </p>

                      <p style="margin-bottom: 16px; font-size: 12px;">
                        Or copy and paste this link into your browser:<br>
                        <a href="${inviteUrl}" class="link">${inviteUrl}</a>
                      </p>

                      <p style="margin: 0; font-size: 12px; color: #6B7280;">
                        This invitation will expire in 7 days.
                      </p>
                    </div>
                  </div>
                </div>

                <div class="footer">
                  <p>© 2025 VoiceBot. All rights reserved.</p>
                </div>
              </div>
            </body>
            </html>
          `,
        });

        if (error) {
          console.error('❌ Failed to send team invitation via Resend:', error);
          return res.status(500).json({
            message: "Failed to send invitation email",
            error: error.message
          });
        }

        console.log(`✅ Team invitation email sent to ${email} with role ${role} via Resend:`, data);
      } catch (emailError: any) {
        console.error('❌ Failed to send team invitation email:', emailError);
        return res.status(500).json({
          message: "Failed to send invitation email",
          error: emailError.message
        });
      }

      // Log audit event
      const performedById = inviterUserId;
      const { logMemberInvited } = await import('./services/memberAuditService');
      await logMemberInvited(
        userId,
        performedById,
        email,
        role.toLowerCase(),
        permissions || null,
        assignedAgentIds || []
      );

      res.json({
        success: true,
        message: `Invitation sent to ${email}`,
        inviteId: inviteToken
      });
    } catch (error: any) {
      console.error("Error sending team invitation:", error);
      res.status(500).json({
        message: "Failed to send invitation",
        error: error.message
      });
    }
  });

  // Remove a team member
  app.delete('/api/team/members/:memberId', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const performedById = req.actualUserId || req.user.claims.sub;
      const { memberId } = req.params;

      // Prevent self-removal
      if (memberId === userId) {
        return res.status(400).json({ message: "Cannot remove yourself from the team" });
      }

      // Get member details before deletion for audit log
      const [memberToDelete] = await db
        .select({
          userId: teamMembers.userId,
          email: users.email
        })
        .from(teamMembers)
        .innerJoin(users, eq(teamMembers.userId, users.id))
        .where(and(
          eq(teamMembers.ownerId, userId),
          eq(teamMembers.userId, memberId)
        ))
        .limit(1);

      if (!memberToDelete) {
        return res.status(404).json({ message: "Team member not found" });
      }

      // Remove the member from the team
      const deleted = await db
        .delete(teamMembers)
        .where(and(
          eq(teamMembers.ownerId, userId),
          eq(teamMembers.userId, memberId)
        ))
        .returning();

      if (!deleted || deleted.length === 0) {
        return res.status(404).json({ message: "Team member not found" });
      }

      // Log audit event
      const { logMemberRemoved } = await import('./services/memberAuditService');
      await logMemberRemoved(
        userId,
        performedById,
        memberId,
        memberToDelete.email || ''
      );

      console.log(`👥 User ${userId} removed member ${memberId} from team`);

      res.json({
        success: true,
        message: "Member removed from team"
      });
    } catch (error) {
      console.error("Error removing team member:", error);
      res.status(500).json({ message: "Failed to remove team member" });
    }
  });

  // Update team member role
  app.patch('/api/team/members/:memberId', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const performedById = req.actualUserId || req.user.claims.sub;
      const { memberId } = req.params;
      const { role, permissions } = req.body;

      console.log(`🔧 PATCH /api/team/members/${memberId} - Request received:`, { userId, performedById, role, permissions });

      if (!role) {
        console.log('❌ Role is missing in request body');
        return res.status(400).json({ message: "Role is required" });
      }

      // Validate role
      const validRoles = ['owner', 'manager', 'employee', 'custom'];
      if (!validRoles.includes(role.toLowerCase())) {
        return res.status(400).json({ message: "Invalid role" });
      }

      // Validate custom permissions if role is 'custom'
      if (role.toLowerCase() === 'custom' && !permissions) {
        return res.status(400).json({ message: "Custom permissions are required for custom role" });
      }

      // Get updater's role to check permissions
      const updaterUserId = req.actualUserId || req.user.claims.sub;
      const [updaterMembership] = await db
        .select()
        .from(teamMembers)
        .where(and(
          eq(teamMembers.userId, updaterUserId),
          eq(teamMembers.ownerId, userId)
        ))
        .limit(1);

      const updaterRole = updaterMembership?.role || (updaterUserId === userId ? 'owner' : null);

      // Prevent changing own role
      if (memberId === updaterUserId) {
        return res.status(400).json({ message: "Cannot change your own role" });
      }

      // Check permissions based on updater role
      if (updaterRole === 'employee' || updaterRole === 'custom') {
        return res.status(403).json({ message: "You don't have permission to change member roles" });
      }

      if (updaterRole === 'manager' && role.toLowerCase() === 'owner') {
        return res.status(403).json({ message: "Managers cannot assign Owner role" });
      }

      // Get the target member to check if they're the original owner and store previous values
      const [targetMember] = await db
        .select()
        .from(teamMembers)
        .where(and(
          eq(teamMembers.userId, memberId),
          eq(teamMembers.ownerId, userId)
        ))
        .limit(1);

      if (!targetMember) {
        return res.status(404).json({ message: "Team member not found" });
      }

      // If target is the original owner (userId), prevent role change
      if (memberId === userId) {
        return res.status(403).json({ message: "Cannot change the original Owner's role" });
      }

      // Store previous values for audit log
      const previousRole = targetMember.role;
      const previousPermissions = targetMember.permissions;

      // Update the member's role and permissions
      const updated = await db
        .update(teamMembers)
        .set({
          role: role.toLowerCase(),
          permissions: permissions || null, // Save custom permissions if provided
          updatedAt: new Date()
        })
        .where(and(
          eq(teamMembers.ownerId, userId),
          eq(teamMembers.userId, memberId)
        ))
        .returning();

      if (!updated || updated.length === 0) {
        return res.status(404).json({ message: "Team member not found" });
      }

      // Log audit event
      const { logRoleChange } = await import('./services/memberAuditService');
      await logRoleChange(
        userId,
        performedById,
        memberId,
        previousRole,
        role.toLowerCase(),
        previousPermissions,
        permissions || null
      );

      console.log(`👥 User ${userId} updated member ${memberId} role to ${role}`);

      res.json({
        success: true,
        message: "Member role updated",
        updatedRole: role
      });
    } catch (error) {
      console.error("Error updating team member:", error);
      res.status(500).json({ message: "Failed to update team member" });
    }
  });

