  // Resend invitation email
  app.post('/api/team/invitations/:id/resend', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const performedById = req.actualUserId || req.user.claims.sub;
      const { id } = req.params;

      // Find the invitation
      const [invitation] = await db
        .select()
        .from(teamInvitations)
        .where(and(
          eq(teamInvitations.id, id),
          eq(teamInvitations.ownerId, userId)
        ))
        .limit(1);

      if (!invitation) {
        return res.status(404).json({ message: "Invitation not found" });
      }

      if (invitation.status !== 'pending') {
        return res.status(400).json({ message: "Can only resend pending invitations" });
      }

      // Update expiration date (extend by 7 days)
      const newExpiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
      await db
        .update(teamInvitations)
        .set({ expiresAt: newExpiresAt })
        .where(eq(teamInvitations.id, id));

      // Get inviter information
      const inviter = await storage.getUser(userId);
      const businessInfo = await storage.getBusinessInfo(userId);
      const inviterName = inviter?.firstName && inviter?.lastName
        ? `${inviter.firstName} ${inviter.lastName}`
        : inviter?.firstName || '';
      const businessName = businessInfo?.businessName || inviterName || 'the team';

      // Resend invitation email
      const inviteUrl = `${resolveBaseUrl(req)}/accept-invite?token=${invitation.inviteToken}`;

      try {
        const { getUncachableResendClient } = await import('./services/resendService');
        const { client: resend } = await getUncachableResendClient();

        await resend.emails.send({
          from: 'VoiceBot Invites <invites@voicebot.one>',
          to: [invitation.email],
          subject: `Reminder: Join ${businessName}`,
          html: `
            <p>This is a reminder of your invitation to join <strong>${businessName}</strong>.</p>
            <p>Click the link below to accept:</p>
            <a href="${inviteUrl}">${inviteUrl}</a>
          `
        });

        // Log audit event
        const { logInvitationResent } = await import('./services/memberAuditService');
        await logInvitationResent(userId, performedById, invitation.email);

        res.json({
          success: true,
          message: "Invitation resent successfully"
        });
      } catch (emailError) {
        console.error("Error resending invitation email:", emailError);
        res.status(500).json({ message: "Failed to send invitation email" });
      }
    } catch (error) {
      console.error("Error resending invitation:", error);
      res.status(500).json({ message: "Failed to resend invitation" });
    }
  });

