  // Helper functions for Retell AI integration
  async function getUserRetellAgentId(userId: string): Promise<string | null> {
    try {
      // Get user's phone number assignments to find associated Retell agent
      const phoneNumbers = await storage.getUserPhoneNumbers(userId);
      const activeAssignment = phoneNumbers.find(assignment => assignment.retellAgentId);
      
      if (activeAssignment && activeAssignment.retellAgentId) {
        return activeAssignment.retellAgentId;
      }
      
      // Fallback: Look for user's voice agents
      const voiceAgents = await storage.getUserVoiceAgents(userId);
      if (voiceAgents.length > 0 && voiceAgents[0].retellAgentId) {
        return voiceAgents[0].retellAgentId;
      }
      
      return null;
    } catch (error) {
      console.error('❌ Error getting user Retell agent ID:', error);
      return null;
    }
  }

