  async function updateRetellAgentKnowledgeBase(retellProvider: any, agentId: string, knowledgeBaseId: string): Promise<void> {
    try {
      console.log(`📚 Updating Retell agent ${agentId} with knowledge base ${knowledgeBaseId}`);
      
      const retellApiKey = process.env.RETELL_API_KEY;
      if (!retellApiKey) {
        throw new Error('RETELL_API_KEY not configured');
      }

      // Update agent with new knowledge base
      const updatePayload = {
        knowledge_base_ids: [knowledgeBaseId]
      };

      const response = await fetch(`https://api.retellai.com/update-agent/${agentId}`, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${retellApiKey}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(updatePayload)
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(`Retell API error: ${errorData.error_message || response.statusText}`);
      }

      console.log('✅ Agent knowledge base updated successfully');
      
    } catch (error) {
      console.error('❌ Error updating agent knowledge base:', error);
      throw error;
    }
  }

  // Save business info settings (knowledge base updates)
  app.post('/api/business-settings/info', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const businessData = req.body;
      
      console.log(`🏢 Saving business info for user: ${userId}`);
      
      // Save business information to storage
      await storage.updateBusinessInfo(userId, businessData);
      
      // Update knowledge base with new business information
      try {
        const { RetellProvider } = await import('./services/RetellProvider');
        const retellProvider = new RetellProvider(storage);
        
        // Get user's phone number assignments to find existing knowledge base ID
        const phoneNumbers = await storage.getUserPhoneNumbers(userId);
        const activeAssignment = phoneNumbers.find(assignment => assignment.retellKnowledgeBaseId);
        
        if (activeAssignment?.retellKnowledgeBaseId) {
          console.log(`📚 Found existing knowledge base: ${activeAssignment.retellKnowledgeBaseId}`);
          
          // Update existing knowledge base with new business information
          await retellProvider.updateKnowledgeBase(activeAssignment.retellKnowledgeBaseId, businessData);
          
          console.log('✅ Knowledge base updated successfully with new business information');
        } else {
          console.log('⚠️ No existing knowledge base found for user, creating new one');
          
          // Get user's active Retell agent ID
          const agentId = await getUserRetellAgentId(userId);
          
          if (agentId) {
            // Create new knowledge base with business information
            const knowledgeBase = await retellProvider.createKnowledgeBase(businessData);

            if (!knowledgeBase || !knowledgeBase.id) {
              throw new Error('Knowledge base creation failed - provider returned null or invalid response');
            }

            // Update the agent to use the new knowledge base
            await updateRetellAgentKnowledgeBase(retellProvider, agentId, knowledgeBase.id);
            
            // Save the knowledge base ID to the phone assignment
            if (activeAssignment) {
              await storage.updatePhoneNumberAssignment(activeAssignment.id, {
                retellKnowledgeBaseId: knowledgeBase.id
              });
            }
            
            console.log('✅ New knowledge base created and linked to agent');
          } else {
            console.log('⚠️ No Retell agent found for user, skipping knowledge base update');
          }
        }
      } catch (error) {
        console.error('❌ Failed to update knowledge base:', error);
        // Don't fail the entire operation if knowledge base update fails
      }
      
      res.json({ 
        success: true, 
        message: 'Business information saved and knowledge base updated',
        businessData 
      });
    } catch (error) {
      console.error('❌ Error saving business info:', error);
      res.status(500).json({ 
        error: "Failed to save business information",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

