  // Save custom integrations from the UI (agent-specific)
  app.post('/api/integrations/custom', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId, integrations } = req.body; // agentId and array of integration objects

      if (!agentId) {
        return res.status(400).json({
          error: "agentId is required",
          message: "Please provide an agentId to save integrations"
        });
      }

      console.log(`🔗 Saving custom integrations for user: ${userId}, agent: ${agentId}`, integrations);

      // Validate that integrations is an array
      if (!Array.isArray(integrations)) {
        return res.status(400).json({
          error: "Invalid integrations data",
          message: "Integrations must be an array"
        });
      }

      // Verify user owns this agent
      const agent = await storage.getVoiceAgent(agentId);
      if (!agent || agent.userId !== userId) {
        return res.status(403).json({
          error: "Not authorized",
          message: "You don't have permission to modify this agent's integrations"
        });
      }

      // IMPORTANT: Only create new integrations - NEVER delete existing ones
      // Existing integrations should only be deleted via the DELETE endpoint
      const savedIntegrations = [];
      for (const integration of integrations) {
        // Exclude timestamp fields from the spread operator since they're auto-generated
        const { createdAt, updatedAt, id, ...integrationData } = integration;

        const saved = await storage.createAgentIntegration({
          userId,
          agentId,
          ...integrationData
        });
        savedIntegrations.push(saved);
      }

      res.json({
        success: true,
        message: 'Custom integrations saved successfully',
        integrations: savedIntegrations
      });
    } catch (error) {
      console.error('❌ Error saving custom integrations:', error);
      res.status(500).json({
        error: "Failed to save custom integrations",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

  // Update existing custom integration (PATCH for partial updates)
  app.patch('/api/integrations/custom/:id', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { id } = req.params;
      const updateData = req.body;

      console.log(`🔧 Updating integration ${id} for user: ${userId}`);

      // Verify the integration exists
      const [integration] = await db
        .select()
        .from(agentIntegrations)
        .where(eq(agentIntegrations.id, id));

      if (!integration) {
        console.log(`❌ Integration ${id} not found`);
        return res.status(404).json({
          error: "Integration not found",
          message: "The specified integration does not exist"
        });
      }

      // Verify user owns this integration via agent ownership
      if (integration.agentId) {
        const agent = await storage.getVoiceAgent(integration.agentId);
        if (!agent || agent.userId !== userId) {
          console.log(`❌ User ${userId} does not own agent ${integration.agentId}`);
          return res.status(403).json({
            error: "Not authorized",
            message: "You don't have permission to modify this integration"
          });
        }
      } else if (integration.userId !== userId) {
        console.log(`❌ User ${userId} does not own integration ${id}`);
        return res.status(403).json({
          error: "Not authorized",
          message: "You don't have permission to modify this integration"
        });
      }

      // Remove fields that shouldn't be updated
      const { id: _id, createdAt, updatedAt, userId: _userId, ...cleanUpdateData } = updateData;

      // Update the integration
      const updatedIntegration = await storage.updateAgentIntegration(id, cleanUpdateData);

      console.log(`✅ Integration ${id} updated successfully`);
      res.json({
        success: true,
        message: 'Integration updated successfully',
        integration: updatedIntegration
      });
    } catch (error) {
      console.error('❌ Error updating integration:', error);
      res.status(500).json({
        error: "Failed to update integration",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

