  // Delete restaurant-level integration (Google Calendar, POS, Delivery)
  app.delete('/api/business-settings/integrations/:integrationType', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { integrationType } = req.params;

      // Validate integrationType
      const validTypes = ['googleCalendar', 'posSystem', 'deliverySystem'];
      if (!validTypes.includes(integrationType)) {
        return res.status(400).json({
          error: "Invalid integration type",
          message: `Integration type must be one of: ${validTypes.join(', ')}`
        });
      }

      console.log(`🗑️ Deleting ${integrationType} integration for user: ${userId}`);

      // Special handling for Google Calendar - stored in userCredentials table
      if (integrationType === 'googleCalendar') {
        console.log('📋 Deleting Google Calendar credentials from userCredentials table');

        // Get existing credentials to verify they exist
        const googleCalendarCreds = await storage.getUserCredentialsByIntegration(userId, 'google_calendar');

        if (!googleCalendarCreds || googleCalendarCreds.length === 0) {
          console.log(`⚠️ No Google Calendar credentials found for user ${userId}`);
          return res.status(404).json({
            error: "Integration not found",
            message: "The specified integration does not exist"
          });
        }

        // Delete all Google Calendar credentials (access_token, refresh_token, calendar_id)
        for (const cred of googleCalendarCreds) {
          await storage.deleteUserCredentials(userId, 'google_calendar', cred.credentialName);
        }

        console.log(`✅ Deleted Google Calendar credentials for user ${userId}`);
        return res.json({
          success: true,
          message: 'Google Calendar integration deleted successfully'
        });
      }

      // Handle other integrations stored in restaurantAutomationConfigs
      const config = await storage.getRestaurantAutomationConfig(userId);

      console.log(`📋 Config found:`, !!config);
      if (config) {
        console.log(`   - googleCalendar:`, !!config.googleCalendar);
        console.log(`   - posSystem:`, !!config.posSystem);
        console.log(`   - deliverySystem:`, !!config.deliverySystem);
      }

      if (!config) {
        console.log(`❌ No restaurant automation config found for user ${userId}`);
        return res.status(404).json({
          error: "Integration not found",
          message: "The specified integration does not exist"
        });
      }

      // Verify the integration actually exists before attempting deletion
      const integrationKey = integrationType as 'posSystem' | 'deliverySystem';

      // Check if the specific integration exists
      const integrationExists =
        (integrationKey === 'posSystem' && config.posSystem) ||
        (integrationKey === 'deliverySystem' && config.deliverySystem);

      console.log(`🔍 Integration exists (${integrationType}):`, integrationExists);

      if (!integrationExists) {
        console.log(`⚠️ ${integrationType} integration not found in config for user ${userId}`);
        return res.status(404).json({
          error: "Integration not found",
          message: `The ${integrationType} integration does not exist for this user`
        });
      }

      console.log(`✅ Found ${integrationType} integration, proceeding with deletion`);

      // Delete the integration
      await storage.deleteRestaurantIntegration(userId, integrationKey);

      res.json({
        success: true,
        message: `${integrationType} integration deleted successfully`
      });
    } catch (error) {
      console.error('❌ Error deleting integration:', error);
      res.status(500).json({
        error: "Failed to delete integration",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

