  // Get custom functions configured in Retell AI for an agent
  app.get('/api/integrations/retell-functions', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId } = req.query;

      if (!agentId) {
        return res.status(400).json({
          error: "agentId is required",
          message: "Please provide an agentId to fetch Retell AI functions"
        });
      }

      console.log(`🔍 Fetching Retell AI custom functions for agent: ${agentId}`);

      // Verify user owns this agent
      const agent = await storage.getVoiceAgent(agentId as string);
      if (!agent || agent.userId !== userId) {
        return res.status(403).json({
          error: "Not authorized",
          message: "You don't have permission to view this agent's functions"
        });
      }

      // Check if agent has a Retell AI agent ID
      if (!agent.retellAgentId) {
        return res.json([]);
      }

      // Get the voice provider instance
      const voiceProvider = getActiveVoiceProvider(storage) as RetellProvider;

      // Fetch custom functions from Retell AI
      const customFunctions = await voiceProvider.getAgentCustomFunctions(agent.retellAgentId);

      // Filter out deprecated SMS functions (send_sms_confirmation, sms_alert)
      // These have been replaced with auto-send SMS in appointment actions
      const filteredFunctions = customFunctions.filter((func: any) => {
        const funcName = func.name || '';
        return funcName !== 'send_sms_confirmation' && funcName !== 'sms_alert';
      });

      // Enrich each function with the saved category, displayTitle, and verboseDescription from agentFunctionSettings
      // so the frontend can categorize correctly and display titles with spaces preserved
      const savedSettings = await db.query.agentFunctionSettings.findMany({
        where: eq(agentFunctionSettings.agentId, agentId as string)
      });
      const categoryByName: Record<string, string> = {};
      const displayTitleByName: Record<string, string> = {};
      const verboseDescriptionByName: Record<string, string> = {};
      for (const s of savedSettings) {
        if (s.functionName && s.category) {
          categoryByName[s.functionName] = s.category;
        }
        if (s.functionName && s.displayTitle) {
          displayTitleByName[s.functionName] = s.displayTitle;
        }
        if (s.functionName && s.verboseDescription) {
          verboseDescriptionByName[s.functionName] = s.verboseDescription;
        }
      }
      const enrichedFunctions = filteredFunctions.map((func: any) => ({
        ...func,
        savedCategory: categoryByName[func.name] || null,
        savedDisplayTitle: displayTitleByName[func.name] || null,
        savedVerboseDescription: verboseDescriptionByName[func.name] || null
      }));

      res.json(enrichedFunctions);
    } catch (error) {
      console.error('❌ Error fetching Retell AI custom functions:', error);
      res.status(500).json({
        error: "Failed to fetch custom functions",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

