  // Integration bridge endpoint - forwards Retell AI tool calls to external integrations
  app.post('/api/integrations/bridge/:integrationId', async (req: any, res) => {
    try {
      const { integrationId } = req.params;
      const toolCallData = req.body;

      console.log(`🌉 Bridge: Received tool call for integration ${integrationId}:`, toolCallData);

      // Extract user ID from the call data or authorization
      // For now, we'll need to find the user from the call_id or another identifier
      // This is a simplified version - in production you'd want more robust authentication

      // Get all users' integrations and find the matching one
      // Since we don't have the userId directly, we'll need to implement a way to map
      // integration IDs to users. For now, let's use a simplified approach:

      const userId = toolCallData.metadata?.userId || req.query.userId;

      if (!userId) {
        console.error('❌ No user ID provided in bridge request');
        return res.status(400).json({ error: 'User ID required' });
      }

      const integrationSettings = await storage.getIntegrationSettings(userId);
      const customIntegrations = integrationSettings?.customIntegrations || [];

      const integration = customIntegrations.find((int: any) => int.id === integrationId);

      if (!integration) {
        console.error(`❌ Integration ${integrationId} not found for user ${userId}`);
        return res.status(404).json({ error: 'Integration not found' });
      }

      console.log(`🔗 Forwarding to external integration: ${integration.name}`);

      // Build the request to the external integration
      const headers: Record<string, string> = {
        'Content-Type': integration.contentType || 'application/json',
      };

      // Add authorization header
      if (integration.authorization) {
        // Replace template variables in authorization header
        let authHeader = integration.authorization;
        authHeader = authHeader.replace('{{api_key}}', integration.apiKey);
        authHeader = authHeader.replace('{{application_id}}', integration.applicationId);
        headers['Authorization'] = authHeader;
      }

      // Add custom headers
      if (integration.customHeaders && Array.isArray(integration.customHeaders)) {
        integration.customHeaders.forEach((header: any) => {
          if (header.key && header.value) {
            headers[header.key] = header.value;
          }
        });
      }

      // Build the payload
      let payload = toolCallData.parameters || toolCallData;

      // If there's a JSON payload schema, use it as a template
      if (integration.jsonPayloadSchema) {
        try {
          const schemaTemplate = JSON.parse(integration.jsonPayloadSchema);
          // Merge tool call data into the schema template
          payload = { ...schemaTemplate, ...payload };
        } catch (e) {
          console.warn('⚠️ Could not parse JSON payload schema, using raw data');
        }
      }

      // Build the URL with query parameters
      let url = integration.apiEndpointUrl;

      // Add query parameters
      const queryParams = new URLSearchParams();
      if (integration.locationId) {
        queryParams.append('location_id', integration.locationId);
      }
      if (integration.timeZone) {
        queryParams.append('timezone', integration.timeZone);
      }
      if (integration.customQueryParams && Array.isArray(integration.customQueryParams)) {
        integration.customQueryParams.forEach((param: any) => {
          if (param.key && param.value) {
            queryParams.append(param.key, param.value);
          }
        });
      }

      const queryString = queryParams.toString();
      if (queryString) {
        url += (url.includes('?') ? '&' : '?') + queryString;
      }

      console.log(`📡 Making ${integration.method} request to ${url}`);

      // Make the request to the external integration
      const response = await fetch(url, {
        method: integration.method || 'POST',
        headers,
        body: integration.method !== 'GET' ? JSON.stringify(payload) : undefined,
        signal: AbortSignal.timeout(integration.timeout || 30000)
      });

      const responseData = await response.json().catch(() => ({}));

      console.log(`✅ Integration ${integration.name} responded with status ${response.status}`);

      // Return the response from the external integration back to Retell AI
      res.status(response.status).json({
        success: response.ok,
        data: responseData,
        integration: integration.name
      });

    } catch (error: any) {
      console.error('❌ Error in integration bridge:', error);
      res.status(500).json({
        error: "Integration bridge failed",
        message: error.message || 'Unknown error',
        success: false
      });
    }
  });

