  // Enhanced webhook testing endpoint with multiple webhook types
  app.post('/api/webhook/test-all', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const phoneNumbers = await storage.getUserPhoneNumbers(userId);
      const primaryPhone = phoneNumbers?.[0];

      if (!primaryPhone) {
        return res.status(400).json({
          error: "No phone number found",
          message: "You need a phone number to test webhooks"
        });
      }

      const testResults = [];
      const baseUrl = process.env.PRODUCTION_URL || `${req.protocol}://${req.hostname}`;

      // Test different webhook endpoints
      const webhookTests = [
        {
          name: 'Voice Webhook',
          endpoint: `${baseUrl}/api/twilio/voice-webhook`,
          method: 'POST',
          payload: {
            CallSid: 'CA' + Math.random().toString(36).substring(2, 15),
            From: '+15551234567',
            To: primaryPhone.phoneNumber,
            CallStatus: 'ringing',
            Direction: 'inbound'
          }
        },
        {
          name: 'Call Status Webhook',
          endpoint: `${baseUrl}/api/twilio/call-status`,
          method: 'POST',
          payload: {
            CallSid: 'CA' + Math.random().toString(36).substring(2, 15),
            CallStatus: 'completed',
            CallDuration: '45',
            From: '+15551234567',
            To: primaryPhone.phoneNumber
          }
        },
        {
          name: 'SMS Webhook',
          endpoint: `${baseUrl}/api/twilio/sms-webhook`,
          method: 'POST',
          payload: {
            MessageSid: 'SM' + Math.random().toString(36).substring(2, 15),
            From: '+15551234567',
            To: primaryPhone.phoneNumber,
            Body: 'Test SMS message',
            MessageStatus: 'received'
          }
        }
      ];

      // Test each webhook
      for (const test of webhookTests) {
        try {
          const startTime = Date.now();

          const response = await fetch(test.endpoint, {
            method: test.method,
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded',
              'User-Agent': 'TwilioProxy/1.1'
            },
            body: new URLSearchParams(test.payload).toString()
          });

          const duration = Date.now() - startTime;
          const responseText = await response.text();

          testResults.push({
            name: test.name,
            endpoint: test.endpoint,
            success: response.ok,
            status: response.status,
            statusText: response.statusText,
            duration: `${duration}ms`,
            response: responseText.slice(0, 500), // Limit response size
            timestamp: new Date().toISOString()
          });

        } catch (error) {
          testResults.push({
            name: test.name,
            endpoint: test.endpoint,
            success: false,
            error: error instanceof Error ? error.message : 'Unknown error',
            timestamp: new Date().toISOString()
          });
        }
      }

      res.json({
        success: true,
        message: 'Webhook tests completed',
        phoneNumber: primaryPhone.phoneNumber,
        testResults,
        summary: {
          total: testResults.length,
          passed: testResults.filter(r => r.success).length,
          failed: testResults.filter(r => !r.success).length
        }
      });

    } catch (error) {
      console.error('❌ Webhook test error:', error);
      res.status(500).json({
        error: "Webhook test failed",
        message: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

