  // Get user's AI receptionists and subscription data for dashboard
  app.get('/api/receptionists', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      
      // Get user's phone numbers (which represent their AI receptionists)
      const phoneNumbers = await storage.getUserPhoneNumbers(userId);
      
      // Get user's subscription information
      const activeSubscription = await storage.getUserSubscription(userId);

      // Also check for standalone trial (UserTrial table)
      const userTrial = await storage.getUserTrial(userId);
      
      // Get business data for each phone number from restaurantData or signup progress
      const receptionistsWithBusinessData = await Promise.all(
        phoneNumbers.map(async (phoneNumber) => {
          let businessData = null;
          
          // Try to get business data from linked restaurantData first
          if (phoneNumber.restaurantId) {
            try {
              businessData = await storage.getRestaurantData(phoneNumber.restaurantId);
            } catch (error) {
              console.log(`Could not find restaurant data for restaurantId: ${phoneNumber.restaurantId}`);
            }
          }
          
          // If no restaurantData found, try to get from signup progress
          if (!businessData) {
            try {
              const signupProgress = await storage.getSignupProgress(userId);
              if (signupProgress?.stepData?.businessOnboarding) {
                const businessInfo = signupProgress.stepData.businessOnboarding;
                businessData = {
                  businessName: businessInfo.businessName,
                  address: businessInfo.address,
                  phone: phoneNumber.phoneNumber,
                  website: businessInfo.website || '',
                  hours: null,
                  menuItems: null,
                  services: null,
                  reservationInfo: null,
                  googleMapsData: signupProgress.stepData.phoneProvisioningData?.businessProfile || null
                };
                console.log(`📍 Retrieved business data from signup progress: ${businessData.businessName}`);
              }
            } catch (error) {
              console.log(`Could not retrieve business data from signup progress: ${error}`);
            }
          }
          
          return { phoneNumber, businessData };
        })
      );
      
      // Build receptionist data from phone numbers and business data
      const receptionists = receptionistsWithBusinessData.map(({ phoneNumber, businessData }, index) => ({
        id: phoneNumber.id,
        business_name: businessData?.businessName || `Business ${index + 1}`,
        phone_number: phoneNumber.phoneNumber,
        status: phoneNumber.status,
        monthly_cost: phoneNumber.monthlyCost || 1.15,
        performance: {
          average_call_duration: 120, // Default values - these could come from call logs
          average_rating: 4.8,
          total_calls: 0
        },
        businessData: businessData, // Include full business data object
        created_at: phoneNumber.createdAt,
        updated_at: phoneNumber.updatedAt
      }));

      // Build subscription data for dashboard
      // Check if user has a standalone trial (UserTrial table) that overrides subscription
      const isOnStandaloneTrial = userTrial && userTrial.status === 'active' && new Date(userTrial.expiresAt) > new Date();

      const user_subscription = activeSubscription || isOnStandaloneTrial ? {
        id: activeSubscription?.id || userTrial?.id || 'trial',
        plan: isOnStandaloneTrial ? 'Free Trial' : (activeSubscription?.plan?.planName || 'Professional'),
        status: isOnStandaloneTrial ? 'trialing' : (activeSubscription?.status || 'active'),
        calls_used: 0, // This could come from call logs
        call_limit: isOnStandaloneTrial ? 100 : (activeSubscription?.plan?.maxCallMinutes || 500),
        minutes_used: isOnStandaloneTrial ? (userTrial?.minutesUsed || 0) : ((activeSubscription as any)?.minutes_used || 0),
        minute_limit: isOnStandaloneTrial ? 100 : (activeSubscription?.plan?.maxCallMinutes || 500),
        monthly_price: isOnStandaloneTrial ? 0 : (activeSubscription?.plan?.monthlyPrice || 9900),
        price_display: isOnStandaloneTrial ? 'Free' : `$${((activeSubscription?.plan?.monthlyPrice || 9900) / 100).toFixed(0)}`,
        current_period_start: activeSubscription?.currentPeriodStart || null,
        current_period_end: activeSubscription?.currentPeriodEnd || null,
        trialEnd: isOnStandaloneTrial ? userTrial?.expiresAt : activeSubscription?.trialEnd, // Use userTrial expiry if on standalone trial
        created_at: activeSubscription?.createdAt || userTrial?.createdAt || null,
        active: isOnStandaloneTrial ? true : (activeSubscription?.status === 'active')
      } : null;

      res.json({
        receptionists,
        user_subscription,
        total_receptionists: receptionists.length
      });
      
    } catch (error) {
      console.error("Error fetching receptionists:", error);
      res.status(500).json({ message: "Failed to fetch receptionists" });
    }
  });

  // Get conversation history for dashboard analytics  
  app.get('/api/conversations', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { limit = 1000, offset = 0, receptionistId, agentId } = req.query;

      // Get user's phone numbers to filter conversations
      let phoneNumbers = await storage.getUserPhoneNumbers(userId);

      // Filter by agentId if provided
      if (agentId) {
        // Get the agent's retellAgentId
        const agent = await storage.getVoiceAgent(agentId as string);
        if (agent && agent.retellAgentId) {
          // Filter phone numbers to only those assigned to this agent
          phoneNumbers = phoneNumbers.filter(pn => pn.retellAgentId === agent.retellAgentId);
        }
      }

      if (phoneNumbers.length === 0) {
        return res.json({ conversations: [], total: 0 });
      }

      // Get call logs which serve as conversation data
      const phoneNumberList = phoneNumbers.map(pn => pn.phoneNumber);
      const { callHistoryService } = await import('./services/callHistoryService');
      
      const filters = {
        limit: parseInt(limit as string),
        offset: parseInt(offset as string)
      };
      
      // Get enhanced call history which includes conversation data
      const callLogs = await callHistoryService.getEnhancedCallHistory(
        userId,
        phoneNumberList,
        filters
      );
      
      // Transform call logs into conversation format expected by dashboard
      const conversations = callLogs.map((call: any) => ({
        id: call.id,
        twilioCallSid: call.twilioCallSid,
        retellCallId: call.retellCallId,

        // Caller Information — all aliases used by various frontend components
        customerName: call.callerName,
        callerName: call.callerName,
        caller_name: call.callerName,
        customer_name: call.callerName,

        fromNumber: call.callerPhone,
        callerPhone: call.callerPhone,
        caller_phone: call.callerPhone,
        from_number: call.callerPhone,
        phone_number: call.callerPhone,
        normalizedPhone: call.callerPhone,

        // Call Metadata — all aliases used by frontend
        startTime: call.timestamp,
        timestamp: call.timestamp,
        started_at: call.timestamp,
        created_at: call.timestamp,
        ended_at: call.timestamp ? new Date(new Date(call.timestamp).getTime() + (call.duration * 1000)) : undefined,
        duration: call.duration,
        direction: call.direction,
        call_type: call.direction,
        status: call.status,

        // Call Type & Intent
        callType: call.callType,
        interactionType: call.interactionType || call.callType,
        intent: call.intent,
        purpose: call.intent,

        // Conversation Data
        transcriptionText: call.fullTranscript,
        fullTranscript: call.fullTranscript,
        transcript: call.fullTranscript,
        summary: call.callSummary || call.call_summary || call.conversationSummary,
        conversationSummary: call.conversationSummary,
        call_summary: call.callSummary || call.call_summary,
        callSummary: call.callSummary || call.call_summary,

        // Post-Call Analysis
        serviceType: call.serviceType || call.service_type,
        service_type: call.service_type || call.serviceType,
        // callOutcome: use Retell value when available, else derive from outcome/status
        callOutcome: call.callOutcome || call.call_outcome ||
          (call.outcome === 'successful' ? 'Completed' :
           call.outcome === 'escalated' ? 'Escalated' :
           call.outcome === 'incomplete' ? 'Incomplete' : 'Completed'),
        call_outcome: call.call_outcome || call.callOutcome ||
          (call.outcome === 'successful' ? 'Completed' :
           call.outcome === 'escalated' ? 'Escalated' :
           call.outcome === 'incomplete' ? 'Incomplete' : 'Completed'),
        actionTaken: call.callOutcome || call.call_outcome,
        // interactionType: use Retell value when available, else use inferred callType
        interactionType: call.interactionType ||
          (call.callType === 'reservation' ? 'Reservation' :
           call.callType === 'order' ? 'Order' :
           call.callType === 'catering' ? 'Catering' :
           call.callType === 'faq_info' ? 'General Inquiry' :
           call.callType || null),

        // Outcome / Status
        outcome: call.outcome,
        callStatus: call.outcome,
        call_status: call.outcome,
        call_successful: call.callSuccessful ?? call.call_successful,

        // Order / Revenue
        order_amount: call.orderAmount ?? undefined,

        // Flag & meta
        flagged: call.flagged || false,
        vip: false,

        // Recording
        recordingUrl: call.recordingUrl,
        recording_url: call.recordingUrl,

        // Sentiment & analytics
        sentiment: call.sentiment || 'neutral',
        sentiment_score: call.sentimentScore || 0.5,
        confidence: call.confidence || 0.8,
        tags: call.tags || [],

        // Agent Info
        agent_id: call.retellCallId,
        retell_agent_id: call.retellCallId,

        // Legacy
        receptionist_id: phoneNumbers[0]?.phoneNumber,
        ai_response: call.conversationSummary,
        updated_at: call.timestamp
      }));
      
      res.json({
        conversations,
        total: conversations.length,
        limit: parseInt(limit as string),
        offset: parseInt(offset as string)
      });
      
    } catch (error) {
      console.error('Error fetching conversations:', error);
      res.status(500).json({ message: 'Failed to fetch conversations' });
    }
  });

  // Helper function to map call status to conversation outcome
  function mapCallStatusToOutcome(status: string, actionTaken?: string): string {
    if (!status) return 'unknown';
    
    switch (status.toLowerCase()) {
      case 'completed':
        return actionTaken === 'transfer' ? 'escalated' : 'successful';
      case 'busy':
      case 'no-answer':
        return 'missed';
      case 'failed':
        return 'incomplete';
      case 'in-progress':
        return 'in_progress';
      default:
        return status.toLowerCase();
    }
  }

  // Helper function to map AI action to call type
  function mapActionToCallType(actionTaken?: string): string {
    if (!actionTaken) return 'general_question';
    
    switch (actionTaken.toLowerCase()) {
      case 'reservation':
        return 'reservation';
      case 'order':
        return 'order_status';
      case 'menu':
        return 'menu_inquiry';
      case 'hours':
        return 'hours_location';
      case 'transfer':
      case 'escalate':
        return 'escalation';
      default:
        return 'general_question';
    }
  }

