  // Secure Stripe Checkout Session Creation
  app.post('/api/checkout/create-session', isAuthenticated, async (req: any, res) => {
    try {
      const stripe = getStripe();
      const { planSlug, successUrl, cancelUrl } = req.body;
      
      // Get authenticated user ID
      const userId = req.viewingOwnerId || req.user.claims.sub;
      
      if (!userId) {
        return res.status(401).json({ message: 'Authentication required for checkout' });
      }

      if (!planSlug || !SUBSCRIPTION_PLANS[planSlug as keyof typeof SUBSCRIPTION_PLANS]) {
        return res.status(400).json({ message: 'Valid plan slug is required' });
      }

      const selectedPlan = SUBSCRIPTION_PLANS[planSlug as keyof typeof SUBSCRIPTION_PLANS];
      console.log(`🎯 Creating checkout session for ${selectedPlan.name} plan: $${(selectedPlan.amount/100).toFixed(2)}/month`);
      console.log(`👤 User ID: ${userId}`);

      // Look up user for email and existing Stripe customer ID
      const dbUser = await storage.getUser(userId);
      const userEmail = dbUser?.email || undefined;

      const baseUrl = `${req.protocol}://${req.get('host')}`;

      // ── Seamless plan switch: existing subscriber → update subscription with proration ──
      const existingSub = await storage.getUserSubscription(userId);
      const existingStripeId = existingSub?.stripeSubscriptionId;

      console.log('🔍 Debug - Existing subscription check:', {
        hasExistingSub: !!existingSub,
        existingStripeId,
        startsWithSub: existingStripeId?.startsWith('sub_'),
        hasStripeCustomerId: !!dbUser?.stripeCustomerId,
        existingSubStatus: existingSub?.status
      });

      // ── Handle existing subscription updates ──
      if (existingSub && existingStripeId && existingStripeId.startsWith('sub_') && dbUser?.stripeCustomerId) {
        console.log(`🔄 Plan switch: user ${userId} switching to ${planSlug}`);

        try {
          // Retrieve the existing Stripe subscription
          const currentStripeSub = await stripe.subscriptions.retrieve(existingStripeId);

        if (currentStripeSub && currentStripeSub.items.data.length > 0) {
          // Find the matching plan in our DB
          const allPlans = await storage.getSubscriptionPlans(false);
          const matchingPlan = allPlans.find(p =>
            p.planName.toLowerCase() === selectedPlan.name.toLowerCase()
          );

          // Create a Stripe Price for the new plan (need to create product first)
          console.log(`Creating Stripe product and price for ${selectedPlan.name} plan...`);

          // First, try to find or create a product for this plan
          const products = await stripe.products.list({ limit: 100 });
          let product = products.data.find(p => p.name === `VoiceBot ${selectedPlan.name} Plan`);

          if (!product) {
            product = await stripe.products.create({
              name: `VoiceBot ${selectedPlan.name} Plan`,
              description: `AI Voice Receptionist - ${selectedPlan.name} subscription`
            });
            console.log(`✅ Created new product: ${product.id}`);
          } else {
            console.log(`✅ Found existing product: ${product.id}`);
          }

          // Create a new price for this product
          const newPrice = await stripe.prices.create({
            product: product.id,
            currency: 'usd',
            unit_amount: selectedPlan.amount,
            recurring: { interval: selectedPlan.interval as 'month' | 'year' },
            metadata: { planSlug, planName: selectedPlan.name }
          });
          console.log(`✅ Created new price: ${newPrice.id}`);

          // Update the subscription with the new price (Stripe handles proration automatically)
          const updatedStripeSub = await stripe.subscriptions.update(existingStripeId, {
            items: [{
              id: currentStripeSub.items.data[0].id,
              price: newPrice.id
            }],
            proration_behavior: 'always_invoice', // Create invoice for prorated amount immediately
            metadata: { planSlug, planName: selectedPlan.name, userId }
          });

          // Update our database with the new subscription details
          await storage.updateUserSubscription(existingSub.id, {
            status: updatedStripeSub.status,
            currentPeriodStart: new Date(updatedStripeSub.current_period_start * 1000),
            currentPeriodEnd: new Date(updatedStripeSub.current_period_end * 1000),
            cancelAtPeriodEnd: false,
            ...(matchingPlan ? { planId: matchingPlan.id } : {})
          });

          console.log(`✅ Plan switched to ${selectedPlan.name} for user ${userId} (updated sub: ${updatedStripeSub.id})`);
          const redirectUrl = successUrl || `${baseUrl}/dashboard?tab=billing&checkout=success&session_id=plan_switched`;
          return res.json({ planSwitched: true, planName: selectedPlan.name });
        }
        } catch (error) {
          console.error('Error updating existing subscription, falling through to checkout:', error);
          // Fall through to checkout session creation
        }
      }

      // Check if customer already has active subscriptions in Stripe
      if (dbUser?.stripeCustomerId) {
        try {
          const activeSubscriptions = await stripe.subscriptions.list({
            customer: dbUser.stripeCustomerId,
            status: 'active',
            limit: 1
          });

          if (activeSubscriptions.data.length > 0) {
            console.log('⚠️ Customer has active subscription in Stripe but our DB is out of sync');
            const stripeSub = activeSubscriptions.data[0];

            // Try to update the existing Stripe subscription instead
            const products = await stripe.products.list({ limit: 100 });
            let product = products.data.find(p => p.name === `VoiceBot ${selectedPlan.name} Plan`);

            if (!product) {
              product = await stripe.products.create({
                name: `VoiceBot ${selectedPlan.name} Plan`,
                description: `AI Voice Receptionist - ${selectedPlan.name} subscription`
              });
            }

            const newPrice = await stripe.prices.create({
              product: product.id,
              currency: 'usd',
              unit_amount: selectedPlan.amount,
              recurring: { interval: selectedPlan.interval as 'month' | 'year' },
              metadata: { planSlug, planName: selectedPlan.name }
            });

            const updatedSub = await stripe.subscriptions.update(stripeSub.id, {
              items: [{
                id: stripeSub.items.data[0].id,
                price: newPrice.id
              }],
              proration_behavior: 'always_invoice',
              metadata: { planSlug, planName: selectedPlan.name, userId }
            });

            console.log(`✅ Updated out-of-sync subscription for user ${userId}`);
            return res.json({ planSwitched: true, planName: selectedPlan.name });
          }
        } catch (error) {
          console.error('Error checking for existing Stripe subscriptions:', error);
          // Continue to checkout creation
        }
      }

      // Build checkout session params
      const checkoutParams: any = {
        mode: 'subscription',
        payment_method_types: ['card'],
        line_items: [{
          price_data: {
            currency: 'usd',
            product_data: {
              name: `VoiceBot ${selectedPlan.name} Plan`,
              description: `AI Voice Receptionist - ${selectedPlan.name} subscription includes dedicated phone number and 24/7 call handling`
            },
            unit_amount: selectedPlan.amount,
            recurring: {
              interval: selectedPlan.interval
            }
          },
          quantity: 1,
        }],
        client_reference_id: userId,
        success_url: successUrl || `${baseUrl}/dashboard?tab=billing&checkout=success&session_id={CHECKOUT_SESSION_ID}`,
        cancel_url: cancelUrl || `${baseUrl}/dashboard?tab=billing`,
        allow_promotion_codes: true,
        billing_address_collection: 'required',
        metadata: {
          planSlug,
          planName: selectedPlan.name,
          includesPhoneNumber: 'true',
          userId
        },
        subscription_data: {
          metadata: {
            planSlug,
            planName: selectedPlan.name,
            includesPhoneNumber: 'true',
            userId
          }
        }
      };

      // Prefer linking existing Stripe customer over pre-filling email
      if (dbUser?.stripeCustomerId) {
        checkoutParams.customer = dbUser.stripeCustomerId;
      } else if (userEmail) {
        checkoutParams.customer_email = userEmail;
      }

      // Create Stripe checkout session for subscription
      const checkoutSession = await stripe.checkout.sessions.create(checkoutParams);

      // Debug log the checkout session
      console.log('🔍 Checkout session details:');
      console.log('  - Session ID:', checkoutSession.id);
      console.log('  - Redirect URL:', checkoutSession.url);
      console.log('  - URL is null/undefined:', !checkoutSession.url);
      console.log('  - Mode:', checkoutSession.mode);
      console.log('  - Status:', checkoutSession.status);

      res.json({
        sessionId: checkoutSession.id,
        url: checkoutSession.url,
        planName: selectedPlan.name,
        amount: selectedPlan.amount
      });
    } catch (error) {
      console.error('Error creating checkout session:', error);
      res.status(500).json({ 
        message: 'Failed to create checkout session',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

