  // Get subscription provisioning status (for post-payment polling)
  app.get('/api/subscription/provisioning-status', async (req: any, res) => {
    try {
      // Get user email from query params or authenticated session
      const userId = req.isAuthenticated() ? req.user.claims.sub : null;
      const email = req.query.email as string;
      
      if (!userId && !email) {
        return res.status(400).json({ 
          completed: false,
          status: 'error',
          error: 'User ID or email required' 
        });
      }

      // Get user by email if not authenticated
      let user = userId ? await storage.getUser(userId) : null;
      if (!user && email) {
        user = await storage.getUserByEmail(email);
      }

      if (!user) {
        return res.status(404).json({ 
          completed: false,
          status: 'error',
          error: 'User not found' 
        });
      }

      // Get user's subscription
      const subscription = await storage.getUserSubscription(user.id);
      if (!subscription) {
        return res.status(404).json({ 
          completed: false,
          status: 'error',
          error: 'No subscription found' 
        });
      }

      console.log(`🔍 Checking provisioning status for subscription ${subscription.id}: ${subscription.provisioningStatus || 'null/undefined'}`);

      // Normalize provisioning status - handle null, undefined, and unexpected values
      const provisioningStatus = subscription.provisioningStatus?.toLowerCase().trim() || 'pending';

      console.log(`📊 Normalized provisioning status: ${provisioningStatus}`);

      // Check provisioning status with explicit handling for all cases
      if (provisioningStatus === 'completed') {
        // Get full provisioning results
        const results = await storage.getProvisioningResults(subscription.id);

        return res.json({
          completed: true,
          status: 'completed',
          agentId: results?.retellAgentId,
          phoneNumber: results?.twilioPhoneNumber,
          knowledgeBaseId: results?.knowledgeBaseId
        });
      } else if (provisioningStatus === 'failed') {
        return res.json({
          completed: false,
          status: 'failed',
          error: 'Provisioning failed. Please contact support.'
        });
      } else if (provisioningStatus === 'in_progress') {
        // Get partial results to show progress
        const results = await storage.getProvisioningResults(subscription.id);

        return res.json({
          completed: false,
          status: 'in_progress',
          agentId: results?.retellAgentId,
          phoneNumber: results?.twilioPhoneNumber,
          knowledgeBaseId: results?.knowledgeBaseId
        });
      } else if (provisioningStatus === 'pending') {
        // Status is pending - get any partial results that might exist
        const results = await storage.getProvisioningResults(subscription.id);

        console.log(`📊 Results for pending subscription:`, {
          retellAgentId: results?.retellAgentId,
          twilioPhoneNumber: results?.twilioPhoneNumber,
          knowledgeBaseId: results?.knowledgeBaseId
        });

        // If we have both agent and phone number, provisioning is actually complete
        // even if status wasn't updated properly
        if (results?.retellAgentId && results?.twilioPhoneNumber) {
          console.log('✅ Found both agent and phone number - treating as completed!');
          return res.json({
            completed: true,
            status: 'completed',
            agentId: results.retellAgentId,
            phoneNumber: results.twilioPhoneNumber,
            knowledgeBaseId: results.knowledgeBaseId
          });
        }

        return res.json({
          completed: false,
          status: 'pending',
          agentId: results?.retellAgentId,
          phoneNumber: results?.twilioPhoneNumber,
          knowledgeBaseId: results?.knowledgeBaseId
        });
      } else {
        // Unexpected status value - log it and treat as pending
        console.warn(`⚠️ Unexpected provisioning status: "${subscription.provisioningStatus}" for subscription ${subscription.id}`);
        const results = await storage.getProvisioningResults(subscription.id);

        console.log(`📊 Results for unexpected status:`, {
          retellAgentId: results?.retellAgentId,
          twilioPhoneNumber: results?.twilioPhoneNumber,
          knowledgeBaseId: results?.knowledgeBaseId
        });

        // If we have both agent and phone number, provisioning is actually complete
        if (results?.retellAgentId && results?.twilioPhoneNumber) {
          console.log('✅ Found both agent and phone number - treating as completed!');
          return res.json({
            completed: true,
            status: 'completed',
            agentId: results.retellAgentId,
            phoneNumber: results.twilioPhoneNumber,
            knowledgeBaseId: results.knowledgeBaseId
          });
        }

        return res.json({
          completed: false,
          status: 'pending',
          agentId: results?.retellAgentId,
          phoneNumber: results?.twilioPhoneNumber,
          knowledgeBaseId: results?.knowledgeBaseId,
          warning: 'Unexpected provisioning status'
        });
      }
    } catch (error) {
      console.error('Error checking provisioning status:', error);
      res.status(500).json({ 
        completed: false,
        status: 'error',
        error: error instanceof Error ? error.message : 'Failed to check provisioning status' 
      });
    }
  });

  // Create or retrieve Stripe subscription
  app.post('/api/subscription/create', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { planId } = req.body;

      if (!planId) {
        return res.status(400).json({ message: 'Plan ID is required' });
      }

      // Get the subscription plan
      const plan = await storage.getSubscriptionPlan(planId);
      if (!plan) {
        return res.status(404).json({ message: 'Subscription plan not found' });
      }

      // Get user info
      const user = await storage.getUser(userId);
      if (!user || !user.email) {
        return res.status(400).json({ message: 'User email is required for subscription' });
      }

      // Check if user already has a subscription
      const existingSubscription = await storage.getUserSubscription(userId);
      if (existingSubscription && (existingSubscription.status === 'active' || existingSubscription.status === 'trialing')) {
        return res.json({ 
          clientSecret: null,
          message: 'User already has an active subscription',
          subscription: existingSubscription
        });
      }

      // Create or retrieve Stripe customer
      let stripeCustomerId = user.stripeCustomerId;
      if (!stripeCustomerId) {
        const customer = await stripe.customers.create({
          email: user.email,
          name: `${user.firstName} ${user.lastName}`.trim(),
          metadata: { userId }
        });
        
        stripeCustomerId = customer.id;
        await storage.updateUserStripeCustomerId(userId, stripeCustomerId);
      }

      // Create Stripe subscription with $1.15 discount for phone number and 14-day free trial
      const subscription = await stripe.subscriptions.create({
        customer: stripeCustomerId,
        items: [{
          price: plan.stripePriceId,
        }],
        discounts: [{
          coupon: await createPhoneNumberDiscountCoupon(stripe)
        }],
        trial_period_days: 14, // 14-day free trial
        payment_behavior: 'default_incomplete',
        payment_settings: {
          save_default_payment_method: 'on_subscription'
        },
        expand: ['latest_invoice.payment_intent'],
      });

      // Store subscription in database
      const userSubscription = await storage.createUserSubscription({
        userId,
        stripeCustomerId,
        stripeSubscriptionId: subscription.id,
        stripePriceId: plan.stripePriceId,
        planId,
        status: subscription.status,
        currentPeriodStart: new Date((subscription as any).current_period_start * 1000),
        currentPeriodEnd: new Date((subscription as any).current_period_end * 1000),
        trialEnd: (subscription as any).trial_end ? new Date((subscription as any).trial_end * 1000) : undefined,
      });

      const latestInvoice = subscription.latest_invoice as any;
      const paymentIntent = latestInvoice?.payment_intent;

      res.json({
        subscriptionId: subscription.id,
        clientSecret: paymentIntent?.client_secret,
        status: subscription.status,
        subscription: userSubscription
      });

    } catch (error) {
      console.error('Error creating subscription:', error);
      res.status(500).json({ 
        message: 'Failed to create subscription',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

  // Cancel subscription
  app.post('/api/subscription/cancel', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { cancelAtPeriodEnd = true } = req.body;

      const userSubscription = await storage.getUserSubscription(userId);
      if (!userSubscription) {
        return res.status(404).json({ message: 'No active subscription found' });
      }

      // Cancel subscription in Stripe
      const stripeSubscription = await stripe.subscriptions.update(userSubscription.stripeSubscriptionId, {
        cancel_at_period_end: cancelAtPeriodEnd
      });

      // Update subscription in database
      const updatedSubscription = await storage.updateUserSubscription(userSubscription.id, {
        status: stripeSubscription.status,
        cancelAtPeriodEnd
      });

      res.json({ 
        success: true,
        subscription: updatedSubscription,
        message: cancelAtPeriodEnd 
          ? 'Subscription will be cancelled at the end of the current period'
          : 'Subscription cancelled immediately'
      });

    } catch (error) {
      console.error('Error cancelling subscription:', error);
      res.status(500).json({ message: 'Failed to cancel subscription' });
    }
  });

