  // Demo session endpoints for 1-minute per user audio demo cap
  app.post('/api/demo/sessions/start', async (req, res) => {
    try {
      const { sessionId, userId, ipAddress } = req.body;

      if (!sessionId) {
        return res.status(400).json({
          success: false,
          error: 'sessionId is required'
        });
      }

      // Check if user/session/IP has recent demo session (within 60 minutes)
      const hasRecentDemo = await storage.hasRecentDemoSession(
        userId, 
        sessionId, 
        ipAddress, 
        60 // 60 minutes
      );

      if (hasRecentDemo) {
        return res.status(429).json({
          success: false,
          error: 'Demo limit reached',
          message: 'You can only use the audio demo once per hour. Please try again later.',
          waitTime: '1 hour'
        });
      }

      // Create new demo session
      const demoSession = await storage.createDemoSession({
        userId: userId || null,
        sessionId,
        ipAddress: ipAddress || null,
        status: 'active',
        retellCallId: null,
        endedAt: null,
        duration: null
      });

      res.json({
        success: true,
        demoSession,
        message: 'Demo session started successfully'
      });

    } catch (error: any) {
      console.error('❌ Error starting demo session:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to start demo session',
        message: error.message
      });
    }
  });

  app.post('/api/demo/sessions/update', async (req, res) => {
    try {
      const { sessionId, retellCallId, status, duration, endedAt } = req.body;

      if (!sessionId) {
        return res.status(400).json({
          success: false,
          error: 'sessionId is required'
        });
      }

      // Get the existing demo session
      const existingSession = await storage.getDemoSession(sessionId);
      if (!existingSession) {
        return res.status(404).json({
          success: false,
          error: 'Demo session not found'
        });
      }

      // Update the demo session
      const updates: any = {};
      if (retellCallId) updates.retellCallId = retellCallId;
      if (status) updates.status = status;
      if (duration !== undefined) updates.duration = duration;
      if (endedAt) updates.endedAt = new Date(endedAt);

      const updatedSession = await storage.updateDemoSession(existingSession.id, updates);

      res.json({
        success: true,
        demoSession: updatedSession,
        message: 'Demo session updated successfully'
      });

    } catch (error: any) {
      console.error('❌ Error updating demo session:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to update demo session',
        message: error.message
      });
    }
  });

