  // Helper function to find business website using web search
  async function findBusinessWebsite(businessName: string, address: string): Promise<string | null> {
    try {
      // Create search query
      const searchQuery = `${businessName} ${address} official website`;
      console.log(`🔍 Searching for website: ${searchQuery}`);
      
      // Use web search to find the business website
      // Note: In a production environment, you would use a real web search API
      // For this implementation, we'll use Google search or similar API
      
      // For now, try to construct likely website URLs and test them
      const businessSlug = businessName.toLowerCase()
        .replace(/[^a-z0-9\s]/g, '')
        .replace(/\s+/g, '');
      
      const possibleUrls = [
        `https://www.${businessSlug}.com`,
        `https://${businessSlug}.com`,
        `https://www.${businessSlug}.net`,
        `https://${businessSlug}.net`
      ];
      
      // Try each possible URL
      for (const url of possibleUrls) {
        try {
          const response = await fetch(url, { 
            method: 'HEAD',
            timeout: 5000,
            headers: {
              'User-Agent': 'Mozilla/5.0 (compatible; VoiceCrafter-BusinessBot/1.0)'
            }
          });
          
          if (response.ok) {
            console.log(`✅ Found working website: ${url}`);
            return url;
          }
        } catch (error) {
          // Continue to next URL
        }
      }
      
      console.log(`⚠️ No website found for ${businessName}`);
      return null;
      
    } catch (error) {
      console.error(`❌ Error finding website for ${businessName}:`, error);
      return null;
    }
  }

