  // Google Places autocomplete endpoint
  app.get('/api/places/autocomplete', async (req, res) => {
    try {
      const { input } = req.query;
      
      if (!input || typeof input !== 'string') {
        return res.status(400).json({ message: "Search input is required" });
      }

      if (!process.env.GOOGLE_MAPS_API_KEY) {
        return res.status(500).json({ 
          success: false, 
          message: "Google Maps API key not configured" 
        });
      }

      // Call Google Places Autocomplete API (removed restrictive types filter)
      const response = await fetch(
        `https://maps.googleapis.com/maps/api/place/autocomplete/json?input=${encodeURIComponent(input)}&key=${process.env.GOOGLE_MAPS_API_KEY}`
      );

      const data = await response.json();
      
      // Log for debugging
      console.log(`📍 Places API response status: ${data.status}`);
      if (data.error_message) {
        console.error(`❌ Places API error: ${data.error_message}`);
      }

      if (data.status === 'OK' && data.predictions) {
        console.log(`✅ Found ${data.predictions.length} location suggestions`);
        res.json({ 
          success: true, 
          suggestions: data.predictions.map((prediction: any) => ({
            description: prediction.description,
            place_id: prediction.place_id,
            structured_formatting: prediction.structured_formatting,
            types: prediction.types
          }))
        });
      } else {
        console.log(`⚠️ No predictions found. Status: ${data.status}`);
        res.json({ 
          success: true, 
          suggestions: [] 
        });
      }
    } catch (error) {
      console.error('Places autocomplete error:', error);
      res.status(500).json({ 
        success: false, 
        message: "Failed to fetch suggestions", 
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

