      if (!canCreate.allowed) {
        return res.status(403).json({ 
          message: canCreate.reason,
          upgradeRequired: true 
        });
      }

      const validation = insertVoiceAgentSchema.extend({
        persona: z.string().optional(),
        sampleScript: z.string().optional(),
        audioUrl: z.string().optional(),
      }).safeParse(req.body);

      if (!validation.success) {
        return res.status(400).json({ message: "Invalid agent data", errors: validation.error.errors });
      }

      // Ensure agent name fits within 30 character limit
      let agentData = { ...validation.data, userId };
      if (agentData.name && agentData.name.length > 30) {
        agentData.name = agentData.name.substring(0, 27) + '...';
      }

      const agent = await storage.createVoiceAgent(agentData);

