  // Ensure knowledge base is connected to agent
  app.post('/api/agents/:id/ensure-knowledge-base', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { id } = req.params;

      // Verify ownership
      const agent = await storage.getVoiceAgent(id);
      if (!agent || agent.userId !== userId) {
        return res.status(403).json({ message: "Not authorized to modify this agent" });
      }

      // Check if agent has retellLlmId
      if (!agent.retellLlmId) {
        return res.status(400).json({ message: "Agent does not have an LLM configured" });
      }

      const voiceProvider = getActiveVoiceProvider(storage);

      // Get LLM details to check for existing knowledge base
      const llmDetails = await voiceProvider.getLlmDetails(agent.retellLlmId);
      if (!llmDetails) {
        return res.status(500).json({ message: "Failed to retrieve LLM details" });
      }

      const knowledgeBaseIds = llmDetails.knowledge_base_ids || [];

      // If knowledge base already exists, return success
      if (knowledgeBaseIds.length > 0) {
        return res.json({
          success: true,
          knowledgeBaseId: knowledgeBaseIds[0],
          alreadyConnected: true
        });
      }

      // Create an empty knowledge base (no pre-filled business info — user will add their own sources)
      console.log(`📚 Creating empty knowledge base for agent ${id}...`);
      const kbName = ((agent as any).businessName || (agent as any).name || 'Knowledge Base')
        .normalize('NFKD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^\w\s-]/g, '')
        .trim()
        .substring(0, 40) || 'Knowledge Base';

      const FormDataLib = (await import('form-data')).default;
      const kbFormData = new FormDataLib();
      kbFormData.append('knowledge_base_name', kbName);

      const kbCreateResp = await axios.post(
        'https://api.retellai.com/create-knowledge-base',
        kbFormData,
        {
          headers: {
            'Authorization': `Bearer ${process.env.RETELL_API_KEY}`,
            ...kbFormData.getHeaders()
          }
        }
      );

      const knowledgeBase = {
        id: kbCreateResp.data.knowledge_base_id as string,
        name: kbCreateResp.data.knowledge_base_name as string
      };

      if (!knowledgeBase.id) {
        return res.status(500).json({ message: "Failed to create knowledge base" });
      }

      // Connect knowledge base to LLM
      console.log(`🔗 Connecting knowledge base ${knowledgeBase.id} to LLM ${agent.retellLlmId}...`);
      const updateResponse = await axios.patch(
        `https://api.retellai.com/update-retell-llm/${agent.retellLlmId}`,
        { knowledge_base_ids: [knowledgeBase.id] },
        {
          headers: {
            'Authorization': `Bearer ${process.env.RETELL_API_KEY}`,
            'Content-Type': 'application/json'
          }
        }
      );

      console.log(`✅ Successfully connected knowledge base to agent ${id}`);

      res.json({
        success: true,
        knowledgeBaseId: knowledgeBase.id,
        alreadyConnected: false
      });
    } catch (error: any) {
      console.error("Error ensuring knowledge base:", error);
      res.status(500).json({
        message: error.message || "Failed to ensure knowledge base connection"
      });
    }
  });

