  // Fix missing LLM IDs for existing agents
  app.post('/api/agents/fix-missing-llm-ids', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;

      console.log(`🔧 Fixing missing LLM IDs for user ${userId}`);

      // Get all voice agents for this user
      const agents = await storage.getVoiceAgents(userId);

      if (!agents || agents.length === 0) {
        return res.status(404).json({
          message: "No voice agents found for this user"
        });
      }

      // Import RetellProvider
      const { RetellProvider } = await import('./services/RetellProvider');
      const retellProvider = new RetellProvider();

      const results = [];

      // Check each agent for missing LLM ID
      for (const agent of agents) {
        if (agent.retellAgentId && !agent.retellLlmId) {
          try {
            console.log(`🔍 Agent ${agent.name} (${agent.id}) is missing LLM ID. Fetching from Retell AI...`);

            const llmId = await retellProvider.getAgentLlmId(agent.retellAgentId);

            if (llmId) {
              // Save the LLM ID to the database
              await storage.updateVoiceAgent(agent.id, { retellLlmId: llmId });

              results.push({
                agentId: agent.id,
                agentName: agent.name,
                retellAgentId: agent.retellAgentId,
                llmId: llmId,
                status: 'success',
                message: `LLM ID ${llmId} saved successfully`
              });
              console.log(`✅ Saved LLM ID ${llmId} for agent ${agent.name}`);
            } else {
              results.push({
                agentId: agent.id,
                agentName: agent.name,
                retellAgentId: agent.retellAgentId,
                status: 'error',
                message: 'No LLM ID found in Retell AI'
              });
              console.log(`⚠️ No LLM ID found for agent ${agent.name}`);
            }
          } catch (error: any) {
            results.push({
              agentId: agent.id,
              agentName: agent.name,
              retellAgentId: agent.retellAgentId,
              status: 'error',
              message: error.message
            });
            console.error(`❌ Failed to fix LLM ID for agent ${agent.name}:`, error.message);
          }
        } else if (agent.retellLlmId) {
          results.push({
            agentId: agent.id,
            agentName: agent.name,
            retellAgentId: agent.retellAgentId,
            llmId: agent.retellLlmId,
            status: 'skipped',
            message: 'LLM ID already exists'
          });
        } else {
          results.push({
            agentId: agent.id,
            agentName: agent.name,
            status: 'skipped',
            message: 'No Retell agent ID found'
          });
        }
      }

      const successCount = results.filter(r => r.status === 'success').length;
      const errorCount = results.filter(r => r.status === 'error').length;
      const skippedCount = results.filter(r => r.status === 'skipped').length;

      res.json({
        message: `Fixed ${successCount} agent(s) missing LLM IDs`,
        total: agents.length,
        success: successCount,
        errors: errorCount,
        skipped: skippedCount,
        results: results
      });

    } catch (error) {
      console.error("Error fixing missing LLM IDs:", error);
      res.status(500).json({
        message: "Failed to fix missing LLM IDs",
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

