  // ── PATCH a single conversation flow node instruction ─────────────────────
  app.patch('/api/agent/conversation-flow-nodes', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId, conversationFlowId, nodeId, instruction } = req.body;

      if (!agentId || !conversationFlowId || !nodeId) {
        return res.status(400).json({ message: 'agentId, conversationFlowId, and nodeId are required' });
      }

      const voiceAgent = await storage.getVoiceAgent(agentId);
      if (!voiceAgent || voiceAgent.userId !== userId) {
        return res.status(403).json({ message: 'Unauthorized' });
      }

      const retellApiKey = process.env.RETELL_API_KEY;
      if (!retellApiKey) throw new Error('RETELL_API_KEY not configured');

      // Fetch the full flow first
      const flowResp = await fetch(`https://api.retellai.com/get-conversation-flow/${conversationFlowId}`, {
        headers: { 'Authorization': `Bearer ${retellApiKey}` }
      });
      if (!flowResp.ok) throw new Error('Failed to fetch conversation flow');
      const flowData = await flowResp.json();

      // Patch the target node
      const updatedNodes = (flowData.nodes || []).map((node: any) => {
        if (node.id !== nodeId) return node;
        if (node.type === 'conversation') {
          return { ...node, instruction: { type: 'prompt', text: instruction } };
        }
        return node;
      });

      // Push updated flow back to Retell
      const updateResp = await fetch(`https://api.retellai.com/update-conversation-flow/${conversationFlowId}`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${retellApiKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ nodes: updatedNodes }),
      });

      if (!updateResp.ok) {
        const err = await updateResp.json().catch(() => ({}));
        throw new Error(err.error_message || updateResp.statusText);
      }

      res.json({ success: true });
    } catch (err: any) {
      console.error('Error updating conversation flow node:', err);
      res.status(500).json({ message: 'Failed to update node' });
    }
  });

