  // Get integration status for all functions of an agent — used to show warning badges
  app.get('/api/agents/:agentId/integration-status', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId } = req.params;

      const voiceAgent = await storage.getVoiceAgent(agentId);
      if (!voiceAgent || voiceAgent.userId !== userId) {
        return res.status(403).json({ message: 'Unauthorized' });
      }

      // Which integration types are actually connected for this agent
      const agentIntegrations = await storage.getAgentIntegrations(agentId);
      const hasCalendar = agentIntegrations.some((i: any) => i.type === 'Calendar');
      const hasPOS = agentIntegrations.some((i: any) => i.type === 'POS');
      const hasCRM = agentIntegrations.some((i: any) => i.type === 'CRM' || i.type === 'contact_memory');
      const hasMessaging = agentIntegrations.some((i: any) => i.type === 'sms_messaging' || i.type === 'Messaging');

      // Function name sets that require each integration type
      const NEEDS_CALENDAR = new Set([
        'book_appointment', 'cancel_appointment', 'reschedule_appointment', 'modify_appointment',
        'check_calendar_availability', 'check_availability', 'create_reservation', 'book_service',
        'modify_appointment_details', 'book_daycare', 'book_training', 'book_showing',
        'book_class', 'cancel_session', 'schedule_class', 'book_calendar_event'
      ]);
      const NEEDS_POS = new Set([
        'place_order', 'update_service_status', 'request_estimate', 'update_treatment_request',
        'update_job_status', 'request_prescription_refill', 'submit_maintenance_request'
      ]);
      const NEEDS_CRM = new Set([
        'get_customer_memory', 'update_customer_memory', 'customer_memory',
        'get_customer_profile', 'update_customer_profile'
      ]);

      // Build per-function warning map
      const warnings: Record<string, { missing: string; message: string }> = {};

      // Get function settings from DB to check explicit integration links
      const allSettings = await db.query.agentFunctionSettings.findMany({
        where: eq(agentFunctionSettings.agentId, agentId)
      });

      // URL path patterns that indicate which integration is needed
      const CALENDAR_URL_PATTERNS = [
        'book_appointment', 'cancel_appointment', 'reschedule_appointment',
        'modify_appointment', 'check_calendar_availability', 'check_availability',
        'create_reservation', 'book_service', 'modify_appointment_details'
      ];
      const POS_URL_PATTERNS = ['place_order', 'update_service_status', 'request_estimate'];
      const CRM_URL_PATTERNS = ['get_customer_memory', 'update_customer_memory', 'customer_memory', 'get_customer_profile', 'update_customer_profile'];

      // Fetch current tools from Retell AI (includes name + url)
      let tools: any[] = [];
      try {
        const provider = getActiveVoiceProvider(storage);
        tools = await provider.getAgentCustomFunctions(voiceAgent.retellAgentId!);
      } catch {
        // Fall back to DB settings if Retell fetch fails — just use function names
        tools = allSettings.map((s: any) => ({ name: s.functionName, url: '' }));
      }

      for (const tool of tools) {
        const name = tool.name || '';
        const url = tool.url || '';
        const isCalendarByName = NEEDS_CALENDAR.has(name);
        const isCalendarByUrl = CALENDAR_URL_PATTERNS.some(p => url.includes(p));
        const isPOSByName = NEEDS_POS.has(name);
        const isPOSByUrl = POS_URL_PATTERNS.some(p => url.includes(p));

        const isCRMByName = NEEDS_CRM.has(name);
        const isCRMByUrl = CRM_URL_PATTERNS.some(p => url.includes(p));

        if ((isCalendarByName || isCalendarByUrl) && !hasCalendar) {
          warnings[name] = {
            missing: 'Calendar',
            message: 'Connect Google Calendar in the Integrations tab so bookings are recorded'
          };
        } else if ((isPOSByName || isPOSByUrl) && !hasPOS) {
          warnings[name] = {
            missing: 'POS',
            message: 'Connect a POS system in the Integrations tab so orders are processed'
          };
        } else if ((isCRMByName || isCRMByUrl) && !hasCRM) {
          warnings[name] = {
            missing: 'Contacts',
            message: 'Link the Contacts integration in the Integrations tab so customer memory is pulled from your contacts list'
          };
        }
      }

      return res.json({
        hasCalendar,
        hasPOS,
        hasCRM,
        hasMessaging,
        warnings  // { [functionName]: { missing, message } }
      });
    } catch (error: any) {
      console.error('Error fetching integration status:', error);
      return res.status(500).json({ message: 'Failed to fetch integration status' });
    }
  });

  // Sync webhook URLs for all tools on a conversation-flow agent
  // Ensures tools point to the correct public domain (fixes stale picard.replit.dev URLs)
  app.post('/api/agents/:agentId/sync-webhooks', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId } = req.params;

      const voiceAgent = await storage.getVoiceAgent(agentId);
      if (!voiceAgent || !voiceAgent.retellAgentId) {
        return res.status(404).json({ message: 'Agent not found' });
      }
      if (voiceAgent.userId !== userId) {
        return res.status(403).json({ message: 'Unauthorized' });
      }

      const provider = getActiveVoiceProvider(storage);
      const tools = await provider.getAgentCustomFunctions(voiceAgent.retellAgentId);
      const baseUrl = resolveBaseUrl(req);

      const knownEndpoints: Record<string, string> = {
        notify_team: '/api/retell/notify_team',
        sms_alert: '/api/retell/notify_team',
        transfer_call: '/api/retell/transfer_call',
        book_appointment: '/api/retell/book_appointment',
        cancel_appointment: '/api/retell/cancel_appointment',
        reschedule_appointment: '/api/retell/reschedule_appointment',
        modify_appointment_details: '/api/retell/modify_appointment',
        customer_memory: '/api/retell/customer_memory',
        update_customer_memory: '/api/retell/update_customer_memory',
        get_customer_memory: '/api/retell/customer_memory',
        send_sms_confirmation: '/api/retell/send_sms_confirmation',
        send_sms: '/api/retell/send_sms_confirmation',
        place_order: '/api/retell/place_order',
        create_reservation: '/api/retell/create_reservation',
        schedule_delivery: '/api/retell/schedule_delivery',
        end_call: '/api/retell/end_call',
      };

      let changed = 0;
      const fixedTools = tools.map((tool: any) => {
        const toolName = tool.name || '';
        // Always compute the expected URL from known endpoints or fallback to /api/retell/{name}
        const expectedPath = knownEndpoints[toolName] ?? `/api/retell/${toolName}`;
        const expectedUrl = `${baseUrl}${expectedPath}`;
        const currentUrl = tool.url || '';

        // Fix if URL is missing, stale (picard.replit.dev), or on wrong domain
        const needsFix = !currentUrl || currentUrl.includes('picard.replit.dev') || !currentUrl.startsWith(baseUrl);
        if (needsFix && toolName) {
          console.log(`🔧 Fixing URL for '${toolName}': ${currentUrl} → ${expectedUrl}`);
          changed++;
          return { ...tool, url: expectedUrl };
        }
        return tool;
      });

      if (changed > 0) {
        // Get the agent's response engine to find the flow ID
        const agentResp = await fetch(`https://api.retellai.com/get-agent/${voiceAgent.retellAgentId}`, {
          headers: { 'Authorization': `Bearer ${process.env.RETELL_API_KEY}`, 'Content-Type': 'application/json' }
        });
        const agentData = await agentResp.json() as any;
        const engine = agentData.response_engine || {};

        if (engine.type === 'conversation-flow' && engine.conversation_flow_id) {
          const patchResp = await fetch(
            `https://api.retellai.com/update-conversation-flow/${engine.conversation_flow_id}`,
            {
              method: 'PATCH',
              headers: { 'Authorization': `Bearer ${process.env.RETELL_API_KEY}`, 'Content-Type': 'application/json' },
              body: JSON.stringify({ tools: fixedTools })
            }
          );
          if (!patchResp.ok) {
            const err = await patchResp.text();
            throw new Error(`Retell API error: ${err}`);
          }
          console.log(`✅ Synced ${changed} webhook URL(s) for agent ${agentId} (flow ${engine.conversation_flow_id})`);
        } else if (engine.llm_id || agentData.llm_id) {
          const llmId = engine.llm_id || agentData.llm_id;
          const patchResp = await fetch(
            `https://api.retellai.com/update-retell-llm/${llmId}`,
            {
              method: 'PATCH',
              headers: { 'Authorization': `Bearer ${process.env.RETELL_API_KEY}`, 'Content-Type': 'application/json' },
              body: JSON.stringify({ general_tools: fixedTools })
            }
          );
          if (!patchResp.ok) {
            const err = await patchResp.text();
            throw new Error(`Retell API error: ${err}`);
          }
          console.log(`✅ Synced ${changed} webhook URL(s) for LLM agent ${agentId}`);
        }
      }

      return res.json({
        success: true,
        totalTools: tools.length,
        urlsFixed: changed,
        message: changed > 0 ? `Fixed ${changed} webhook URL(s)` : 'All webhook URLs are already correct'
      });
    } catch (error: any) {
      console.error('Error syncing webhook URLs:', error);
      return res.status(500).json({ message: error.message || 'Failed to sync webhook URLs' });
    }
  });

