  // Test a custom function by triggering its webhook with mock parameters
  app.post('/api/agents/:agentId/functions/:functionName/test', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId, functionName } = req.params;
      const { parameters } = req.body;

      const voiceAgent = await storage.getVoiceAgent(agentId);
      if (!voiceAgent || voiceAgent.userId !== userId) {
        return res.status(403).json({ message: 'Unauthorized or agent not found' });
      }

      // Fetch function settings
      const settings = await db.query.agentFunctionSettings.findFirst({
        where: and(
          eq(agentFunctionSettings.agentId, agentId),
          eq(agentFunctionSettings.functionName, functionName)
        )
      });

      const category = settings?.category || '';
      const recipientPhone = settings?.recipientPhone || '';
      const smsContent = settings?.smsContent || '';
      const smsMessageType = settings?.smsMessageType || 'prompt';

      // For messaging-type functions, send a real test SMS
      if (category === 'messaging' || recipientPhone) {
        if (!recipientPhone) {
          return res.json({
            success: false,
            message: 'No recipient phone number configured. Please save a phone number in the "To:" field first.'
          });
        }

        // Clean the phone number (strip HTML tags if stored as HTML)
        const cleanPhone = recipientPhone.replace(/<[^>]*>/g, '').trim();
        if (!cleanPhone) {
          return res.json({
            success: false,
            message: 'Recipient phone number is empty or contains only parameter tokens that cannot be resolved in test mode.'
          });
        }

        // Get the business phone number to send from
        const userPhoneNumbers = await storage.getUserPhoneNumbers(userId);
        const fromNumber = userPhoneNumbers?.[0]?.phoneNumber;

        if (!fromNumber) {
          return res.json({
            success: false,
            message: 'No business phone number configured to send from. Please provision a phone number first.'
          });
        }

        // Build the test message
        let testMessage = '';
        if (smsMessageType === 'static' && smsContent) {
          testMessage = `[TEST] ${smsContent}`;
        } else if (smsContent) {
          testMessage = `[TEST] This is a test of your messaging action "${functionName}". Message template: "${smsContent.substring(0, 100)}${smsContent.length > 100 ? '...' : ''}"`;
        } else {
          testMessage = `[TEST] Your messaging action "${functionName}" is working correctly.`;
        }

        // Apply parameter values if provided
        if (parameters && Object.keys(parameters).length > 0) {
          Object.entries(parameters).forEach(([key, value]) => {
            testMessage = testMessage.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), String(value));
            testMessage = testMessage.replace(new RegExp(`/${key}`, 'g'), String(value));
          });
        }

        try {
          const { twilioService } = await import('./services/twilioService');
          const smsResult = await twilioService.sendSMS(cleanPhone, testMessage);
          console.log(`✅ Test SMS sent to ${cleanPhone}: SID=${smsResult.sid}`);
          return res.json({
            success: true,
            message: `Test SMS sent successfully to ${cleanPhone}`,
            phone: cleanPhone,
            sms_sid: smsResult.sid
          });
        } catch (smsError: any) {
          console.error('❌ Test SMS failed:', smsError);
          return res.json({
            success: false,
            message: `Failed to send test SMS: ${smsError.message}`
          });
        }
      }

      // For non-messaging functions, return a simulated success
      return res.json({
        success: true,
        message: `Function "${functionName}" test simulated successfully. In a live call, Retell AI will call this function's webhook.`,
        functionName,
        parameters: parameters || {}
      });
    } catch (error: any) {
      console.error('❌ Error testing function:', error);
      res.status(500).json({ message: error.message || 'Failed to test function' });
    }
  });

