  // Real server-side call stats — computes counts and minutes across full history
  // POST /api/calls/analyze-revenue-batch
  // Uses Gemini to identify exactly which KB items were booked in each call transcript.
  // Results are cached in conversationData.aiRevenue so Gemini is only called once per call.
  app.post('/api/calls/analyze-revenue-batch', isAuthenticated, async (req: any, res) => {
    try {
      const { kbContent, calls } = req.body as {
        kbContent: string;
        calls: Array<{ callId: string; transcript: string; summary: string }>;
      };

      if (!kbContent || !Array.isArray(calls) || calls.length === 0) {
        return res.status(400).json({ message: 'kbContent and calls[] required' });
      }

      const results: Record<string, { items: Array<{ name: string; price: number }>; total: number }> = {};
      const needsAnalysis: Array<{ callId: string; transcript: string; summary: string }> = [];

      // Check DB cache first for each call
      for (const c of calls) {
        if (!c.callId) continue;
        const log = await storage.getTelephonyCallLog(c.callId);
        const cd = (log?.conversationData as any) || {};
        if (cd.aiRevenue != null) {
          results[c.callId] = cd.aiRevenue;
        } else {
          needsAnalysis.push(c);
        }
      }

      // Run Gemini for any calls not yet cached
      if (needsAnalysis.length > 0) {
        const { GoogleGenAI } = await import('@google/genai');
        const ai = new GoogleGenAI({ apiKey: process.env.GOOGLE_API_KEY || process.env.GEMINI_API_KEY || '' });

        const callsPayload = needsAnalysis.map(c => ({
          callId: c.callId,
          transcript: (c.transcript || '').slice(0, 2000),
          summary: (c.summary || '').slice(0, 500),
        }));

        const prompt = `You are a revenue analyst for a salon/spa business. Analyze each phone call transcript to identify which services the customer requested or had booked, and calculate the total value.

PRICE LIST (services with prices):
${kbContent.slice(0, 8000)}

CALLS TO ANALYZE:
${JSON.stringify(callsPayload)}

Rules:
1. COUNT a service as revenue if the customer clearly REQUESTED it — even if the booking could not be completed (e.g., calendar not connected, agent couldn't confirm). The customer expressed intent to purchase.
2. Do NOT count a service if the customer was just asking about pricing, availability in general, or called for a completely different reason.
3. Match service names flexibly: "shellac manicure" matches "Mani Shellac" or "Shellac Manicure". "pedicure classic" matches "Pedi Classic".
4. When a price is a RANGE (e.g., "$45 to $47", "$38-$42"), use the MIDPOINT as the price (e.g., $46, $40).
5. If a price has a single value in the price list, use that exact value.
6. Match ALL services mentioned (e.g., "Pedi Classic with Shellac add-on" = two line items).
7. If no service was identified at all (pure info call, wrong number, etc.), return items:[] and total:0.

Return ONLY valid JSON (no other text), where each key is a callId:
{
  "callId1": { "items": [{"name": "Mani Shellac", "price": 46.00}], "total": 46.00 },
  "callId2": { "items": [{"name": "Pedi Classic", "price": 38.00}, {"name": "Shellac Add-on", "price": 20.00}], "total": 58.00 },
  "callId3": { "items": [], "total": 0 }
}`;

        try {
          const response = await ai.models.generateContent({
            model: 'gemini-2.0-flash',
            contents: prompt,
          });
          const raw = (response.text || '').trim();
          const jsonMatch = raw.match(/\{[\s\S]*\}/);
          if (jsonMatch) {
            const aiResults = JSON.parse(jsonMatch[0]);

            // Store results and cache in DB
            for (const c of needsAnalysis) {
              const callResult = aiResults[c.callId] || { items: [], total: 0 };
              // Ensure total is a number
              if (typeof callResult.total === 'string') callResult.total = parseFloat(callResult.total) || 0;
              results[c.callId] = callResult;

              // Persist to DB only for positive results (zero-revenue calls
              // aren't cached so the improved prompt can re-analyze them next time)
              if (callResult.total > 0) {
                const log = await storage.getTelephonyCallLog(c.callId);
                if (log) {
                  const cd = (log.conversationData as any) || {};
                  await storage.updateTelephonyCallLog(c.callId, {
                    conversationData: { ...cd, aiRevenue: callResult },
                  });
                }
              }
            }
          }
        } catch (aiErr) {
          console.error('AI revenue analysis failed:', aiErr);
          for (const c of needsAnalysis) {
            results[c.callId] = { items: [], total: 0 };
          }
        }
      }

      res.json({ results });
    } catch (err) {
      console.error('Error in analyze-revenue-batch:', err);
      res.status(500).json({ message: 'Failed to analyze revenue' });
    }
  });

  app.get('/api/dashboard/call-stats', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId } = req.query;

      // Resolve phone numbers to query
      let phoneNumbers = await storage.getUserPhoneNumbers(userId);
      if (agentId) {
        const agent = await storage.getVoiceAgent(agentId as string);
        if (agent?.retellAgentId) {
          phoneNumbers = phoneNumbers.filter(pn => pn.retellAgentId === agent.retellAgentId);
        }
      }

      if (phoneNumbers.length === 0) {
        return res.json({
          callsToday: 0, callsThisWeek: 0, callsThisMonth: 0, callsLast3Months: 0, callsTotal: 0,
          minutesToday: 0, minutesThisWeek: 0, minutesThisMonth: 0, minutesLast3Months: 0, minutesTotal: 0,
          minutesBillingPeriod: 0,
        });
      }

      const phoneList = phoneNumbers.map(pn => pn.phoneNumber);
      const now = new Date();

      // Time boundaries (UTC)
      const startOfToday = new Date(now); startOfToday.setHours(0, 0, 0, 0);
      const startOfWeek = new Date(now); startOfWeek.setDate(now.getDate() - now.getDay()); startOfWeek.setHours(0, 0, 0, 0);
      const startOfMonth = new Date(now); startOfMonth.setDate(1); startOfMonth.setHours(0, 0, 0, 0);
      const startOf3Months = new Date(now); startOf3Months.setMonth(now.getMonth() - 3); startOf3Months.setHours(0, 0, 0, 0);

      // Get billing period start — prefer Stripe (authoritative), fall back to DB, then start of month
      let billingPeriodStart = startOfMonth;
      try {
        const userSub = await storage.getUserSubscription(userId);
        if (userSub?.stripeSubscriptionId && !userSub.stripeSubscriptionId.startsWith('email-signup')) {
          // Pull directly from Stripe for accuracy
          try {
            const stripe = getStripe();
            const stripeSub = await stripe.subscriptions.retrieve(userSub.stripeSubscriptionId);
            billingPeriodStart = new Date((stripeSub as any).current_period_start * 1000);
          } catch (_stripeErr) {
            // Stripe unavailable — fall back to what we have in DB
            if (userSub.currentPeriodStart) {
              billingPeriodStart = new Date(userSub.currentPeriodStart);
            }
          }
        } else if (userSub?.currentPeriodStart) {
          billingPeriodStart = new Date(userSub.currentPeriodStart);
        }
      } catch (_) { /* fallback to start of month */ }

      const placeholders = phoneList.map((_, i) => `$${i + 1}`).join(', ');
      const { pool } = await import('./db');

      // effective_duration: mirrors the same logic used by the Calls tab.
      // Priority 1 — (end_time - start_time): covers cases where Twilio's stored duration
      //   is just the SIP handoff (1-2 s) but end_time reflects the true call end.
      // Priority 2 — stored duration (> 2 s): fallback when end_time is not available
      //   but the Twilio/Retell webhook did record the real duration.
      const aggResult = await pool.query(`
        WITH calls_with_duration AS (
          SELECT
            start_time,
            CASE
              WHEN end_time IS NOT NULL AND end_time > start_time
                THEN GREATEST(
                  EXTRACT(EPOCH FROM (end_time - start_time))::integer,
                  CASE WHEN duration IS NOT NULL AND duration > 2 THEN duration ELSE 0 END
                )
              WHEN duration IS NOT NULL AND duration > 2 THEN duration
              ELSE 0
            END AS effective_duration
          FROM telephony_call_logs
          WHERE (to_number = ANY(ARRAY[${placeholders}]) OR from_number = ANY(ARRAY[${placeholders}]))
        )
        SELECT
          COUNT(*) FILTER (WHERE start_time >= $${phoneList.length + 1}) AS calls_today,
          COUNT(*) FILTER (WHERE start_time >= $${phoneList.length + 2}) AS calls_this_week,
          COUNT(*) FILTER (WHERE start_time >= $${phoneList.length + 3}) AS calls_this_month,
          COUNT(*) FILTER (WHERE start_time >= $${phoneList.length + 4}) AS calls_last_3_months,
          COUNT(*) AS calls_total,
          COUNT(*) FILTER (WHERE start_time >= $${phoneList.length + 5}) AS calls_billing_period,
          COALESCE(SUM(effective_duration) FILTER (WHERE start_time >= $${phoneList.length + 1}), 0) AS seconds_today,
          COALESCE(SUM(effective_duration) FILTER (WHERE start_time >= $${phoneList.length + 2}), 0) AS seconds_this_week,
          COALESCE(SUM(effective_duration) FILTER (WHERE start_time >= $${phoneList.length + 3}), 0) AS seconds_this_month,
          COALESCE(SUM(effective_duration) FILTER (WHERE start_time >= $${phoneList.length + 4}), 0) AS seconds_last_3_months,
          COALESCE(SUM(effective_duration), 0) AS seconds_total,
          COALESCE(SUM(effective_duration) FILTER (WHERE start_time >= $${phoneList.length + 5}), 0) AS seconds_billing_period
        FROM calls_with_duration
      `, [...phoneList, startOfToday, startOfWeek, startOfMonth, startOf3Months, billingPeriodStart]);

      const row = aggResult.rows[0];
      const toMin = (s: any) => Math.round(Number(s) / 60);

      res.json({
        callsToday: Number(row.calls_today),
        callsThisWeek: Number(row.calls_this_week),
        callsThisMonth: Number(row.calls_this_month),
        callsLast3Months: Number(row.calls_last_3_months),
        callsTotal: Number(row.calls_total),
        callsBillingPeriod: Number(row.calls_billing_period),
        minutesToday: toMin(row.seconds_today),
        minutesThisWeek: toMin(row.seconds_this_week),
        minutesThisMonth: toMin(row.seconds_this_month),
        minutesLast3Months: toMin(row.seconds_last_3_months),
        minutesTotal: toMin(row.seconds_total),
        minutesBillingPeriod: toMin(row.seconds_billing_period),
        billingPeriodStart: billingPeriodStart.toISOString(),
      });
    } catch (error) {
      console.error("Error fetching call stats:", error);
      res.status(500).json({ message: "Failed to fetch call stats" });
    }
  });

