  // Get knowledge base content from Retell AI for Memory subtab
  app.get('/api/restaurant/:agentId/knowledge-base-content', isAuthenticated, async (req: any, res) => {
    try {
      const { agentId } = req.params;
      const userId = req.viewingOwnerId || req.user.claims.sub;

      // Verify ownership
      const agent = await storage.getVoiceAgent(agentId);
      if (!agent || agent.userId !== userId) {
        return res.status(403).json({ message: "Not authorized" });
      }

      if (!agent.retellAgentId) {
        return res.json({ content: '', source: 'none' });
      }

      console.log(`📚 Fetching knowledge base content for agent ${agentId} from Retell AI...`);

      // Get LLM ID
      let llmId = agent.retellLlmId;

      if (!llmId) {
        // Fetch from Retell AI
        const retellAgentResponse = await fetch(`https://api.retellai.com/get-agent/${agent.retellAgentId}`, {
          headers: {
            'Authorization': `Bearer ${process.env.RETELL_API_KEY}`
          }
        });

        if (retellAgentResponse.ok) {
          const retellAgent = await retellAgentResponse.json();
          llmId = retellAgent.llm_id;
          
          if (llmId) {
            await storage.updateVoiceAgent(agentId, { retellLlmId: llmId });
          }
        }
      }

      // Determine knowledge base ID — path differs for conversation-flow vs retell-llm agents
      let knowledgeBaseId: string | undefined;

      // First check if we have it stored locally (fastest path)
      const localSources = await storage.getKnowledgeSources(agentId);
      if (localSources.length > 0 && localSources[0].knowledgeBaseId) {
        knowledgeBaseId = localSources[0].knowledgeBaseId;
        console.log(`📚 Found knowledge base ID from local DB: ${knowledgeBaseId}`);
      }

      if (!knowledgeBaseId) {
        // For conversation-flow agents: KB is attached to the flow, not an LLM
        const conversationFlowId = agent.conversationFlowId;
        if (conversationFlowId) {
          console.log(`🔍 Conversation-flow agent — fetching KB from flow ${conversationFlowId}`);
          const flowResponse = await fetch(`https://api.retellai.com/get-conversation-flow/${conversationFlowId}`, {
            headers: { 'Authorization': `Bearer ${process.env.RETELL_API_KEY}` }
          });
          if (flowResponse.ok) {
            const flowData = await flowResponse.json();
            const flowKbIds: string[] = flowData.knowledge_base_ids || [];
            knowledgeBaseId = flowKbIds[0];
            if (knowledgeBaseId) {
              console.log(`✅ Found knowledge base ID from conversation flow: ${knowledgeBaseId}`);
            }
          }
        }
      }

      if (!knowledgeBaseId && llmId) {
        // Fallback: LLM-based agent path
        const retellLlmResponse = await fetch(`https://api.retellai.com/get-retell-llm/${llmId}`, {
          headers: { 'Authorization': `Bearer ${process.env.RETELL_API_KEY}` }
        });
        if (retellLlmResponse.ok) {
          const retellLlm = await retellLlmResponse.json();
          const kbIds: string[] = retellLlm.knowledge_base_ids || [];
          knowledgeBaseId = kbIds[0];
          if (knowledgeBaseId) {
            console.log(`✅ Found knowledge base ID from LLM: ${knowledgeBaseId}`);
          }
        }
      }

      if (!knowledgeBaseId) {
        console.log(`⚠️ No knowledge base found for agent ${agentId}`);
        return res.json({ content: '', source: 'no_kb' });
      }

      // Fetch knowledge base details
      const kbResponse = await fetch(`https://api.retellai.com/get-knowledge-base/${knowledgeBaseId}`, {
        headers: {
          'Authorization': `Bearer ${process.env.RETELL_API_KEY}`
        }
      });

      if (!kbResponse.ok) {
        console.log(`⚠️ Failed to fetch knowledge base ${knowledgeBaseId}`);
        return res.json({ content: '', source: 'kb_fetch_failed' });
      }

      const kbData = await kbResponse.json();
      const sources = kbData.knowledge_base_sources || [];

      console.log(`📊 Knowledge base ${knowledgeBaseId} has ${sources.length} sources`);
      
      // Extract text content from sources
      let content = '';
      const textSources = sources.filter((s: any) => s.type === 'text');
      
      console.log(`📊 Found ${textSources.length} text sources`);
      
      if (textSources.length > 0) {
        // Get the most recent text source (last one)
        const textSource = textSources[textSources.length - 1];
        console.log(`🔍 Text source object keys:`, Object.keys(textSource));
        console.log(`🔍 Text source full object:`, JSON.stringify(textSource, null, 2));
        
        // Retell AI returns content via content_url, not directly in the object
        if (textSource.content_url) {
          console.log(`📥 Fetching content from URL: ${textSource.content_url}`);
          try {
            const contentResponse = await fetch(textSource.content_url);
            if (contentResponse.ok) {
              content = await contentResponse.text();
              console.log(`✅ Fetched text content from URL: ${content.substring(0, 100)}... (${content.length} chars total)`);
            } else {
              console.log(`⚠️ Failed to fetch content from URL: ${contentResponse.statusText}`);
            }
          } catch (fetchError) {
            console.error(`❌ Error fetching content from URL:`, fetchError);
          }
        } else {
          // Fallback: Try different possible field names for direct text content
          content = textSource.text || textSource.content || textSource.data || '';
          console.log(`✅ Extracted text content from direct field: ${content.substring(0, 100)}... (${content.length} chars total)`);
        }
      } else if (sources.length > 0) {
        console.log(`⚠️ No text sources found. Source types: ${sources.map((s: any) => s.type).join(', ')}`);
      }

      // If no content from Retell AI, fall back to database rawBusinessInfo
      let source = 'retell_ai';
      if (!content || content.trim().length === 0) {
        console.log(`⚠️ No content from Retell AI, checking database for rawBusinessInfo...`);
        const restaurantData = await storage.getRestaurantData(agentId);
        if (restaurantData?.rawBusinessInfo && restaurantData.rawBusinessInfo.trim()) {
          content = restaurantData.rawBusinessInfo;
          source = 'database';
          console.log(`✅ Using rawBusinessInfo from database (${content.length} chars)`);
        } else {
          console.log(`⚠️ No rawBusinessInfo found in database either`);
        }
      }
      
      console.log(`✅ Returning knowledge base content from ${source} (${content.length} chars)`);
      

      res.json({ 
        content, 
        source,
        knowledgeBaseId,
        llmId
      });
    } catch (error) {
      console.error("Error fetching knowledge base content:", error);
      res.status(500).json({ message: "Failed to fetch knowledge base content" });
    }
  });

  // Update restaurant data
  app.patch('/api/restaurant/:agentId', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId } = req.params;

      // Verify ownership
      const existingAgent = await storage.getVoiceAgent(agentId);
      if (!existingAgent || existingAgent.userId !== userId) {
        return res.status(403).json({ message: "Not authorized to update this restaurant" });
      }

      // Check if restaurant data exists, if not create it
      let existingRestaurantData = await storage.getRestaurantDataById(agentId);
      if (!existingRestaurantData) {
        console.log(`⚠️ No restaurant data found for agent ${agentId}, creating new row...`);
        existingRestaurantData = await storage.createRestaurantData({
          agentId,
          businessName: existingAgent.name || 'Business',
          businessType: existingAgent.industry || 'general',
          ...req.body
        });
      }

      const updatedData = await storage.updateRestaurantData(agentId, req.body);

      // If rawBusinessInfo was updated, also update the knowledge base
      if (req.body.rawBusinessInfo && existingAgent.retellAgentId) {
        try {
          console.log(`📚 Updating knowledge base for agent ${agentId} after Memory tab save...`);

          // Get the LLM ID from the database (knowledge bases are attached to LLMs, not agents)
          let llmId = existingAgent.retellLlmId;

          // If LLM ID is missing, fetch it from Retell AI and save it
          if (!llmId) {
            console.log(`⚠️ No LLM ID found in database for agent ${existingAgent.retellAgentId}. Fetching from Retell AI...`);

            try {
              // Fetch agent details from Retell AI to get the LLM ID
              const retellAgentResponse = await fetch(`https://api.retellai.com/get-agent/${existingAgent.retellAgentId}`, {
                headers: {
                  'Authorization': `Bearer ${process.env.RETELL_API_KEY}`
                }
              });

              if (retellAgentResponse.ok) {
                const retellAgent = await retellAgentResponse.json();

                // Check response engine type - only retell-llm type has knowledge base support
                const responseEngineType = retellAgent.response_engine?.type || retellAgent.response_engine_type;

                if (responseEngineType && responseEngineType !== 'retell-llm') {
                  console.log(`⚠️ Agent ${existingAgent.retellAgentId} uses ${responseEngineType} response engine. Knowledge base updates only work with retell-llm type.`);
                  return; // Skip KB update for non-LLM agents
                }

                llmId = retellAgent.llm_id;

                if (llmId) {
                  console.log(`✅ Found LLM ID ${llmId} from Retell AI. Saving to database...`);

                  // Save the LLM ID to the database for future use
                  await storage.updateVoiceAgent(agentId, { retellLlmId: llmId });
                  console.log(`✅ Saved LLM ID to database for agent ${agentId}`);
                } else {
                  console.log(`⚠️ Agent ${existingAgent.retellAgentId} does not have an LLM ID in Retell AI (may be using conversation-flow)`);
                }
              } else {
                console.log(`⚠️ Failed to fetch agent details from Retell AI: ${retellAgentResponse.statusText}`);
              }
            } catch (fetchError) {
              console.error('⚠️ Error fetching LLM ID from Retell AI:', fetchError);
            }
          }

          if (llmId) {
            // Get the knowledge base IDs from the LLM
            const retellLlmResponse = await fetch(`https://api.retellai.com/get-retell-llm/${llmId}`, {
              headers: {
                'Authorization': `Bearer ${process.env.RETELL_API_KEY}`
              }
            });

            if (retellLlmResponse.ok) {
              const retellLlm = await retellLlmResponse.json();
              const knowledgeBaseIds = retellLlm.knowledge_base_ids || [];
              const knowledgeBaseId = knowledgeBaseIds[0]; // Get the first knowledge base ID

              if (knowledgeBaseId) {
                // Update the knowledge base with new business information
                const { getActiveVoiceProvider } = await import('./services/VoiceAgentProviderFactory');
                const voiceProvider = getActiveVoiceProvider(storage);

                await voiceProvider.updateKnowledgeBase(knowledgeBaseId, {
                  businessName: existingAgent.name || req.body.businessName || 'Business',
                  businessInfo: req.body.rawBusinessInfo || '',
                  physicalAddress: req.body.address || updatedData?.address || '',
                  phoneNumber: req.body.phone || updatedData?.phone || '',
                  industry: existingAgent.industry || 'restaurant',
                  description: req.body.rawBusinessInfo || ''
                } as any);

                console.log(`✅ Successfully updated knowledge base ${knowledgeBaseId}`);

                // Ensure KB is linked to LLM (in case it was disconnected)
                if (!knowledgeBaseIds.includes(knowledgeBaseId)) {
                  console.log(`🔗 Linking knowledge base ${knowledgeBaseId} to LLM ${llmId}...`);

                  try {
                    const updateLlmResponse = await fetch(`https://api.retellai.com/update-retell-llm/${llmId}`, {
                      method: 'PATCH',
                      headers: {
                        'Authorization': `Bearer ${process.env.RETELL_API_KEY}`,
                        'Content-Type': 'application/json'
                      },
                      body: JSON.stringify({
                        knowledge_base_ids: [knowledgeBaseId]
                      })
                    });

                    if (updateLlmResponse.ok) {
                      console.log(`✅ Successfully linked KB ${knowledgeBaseId} to LLM ${llmId}`);
                    } else {
                      console.log(`⚠️ Failed to link KB to LLM: ${updateLlmResponse.statusText}`);
                    }
                  } catch (linkError) {
                    console.error('⚠️ Error linking KB to LLM:', linkError);
                  }
                } else {
                  console.log(`✅ KB ${knowledgeBaseId} already linked to LLM ${llmId}`);
                }
              } else {
                console.log(`⚠️ No knowledge base ID found in LLM ${llmId} for agent ${existingAgent.retellAgentId}`);
              }
            }
          }
        } catch (kbError) {
          console.error('⚠️ Failed to update knowledge base:', kbError);
          // Don't fail the request if KB update fails - just log the error
        }
      }

      res.json(updatedData);
    } catch (error) {
      console.error("Error updating restaurant data:", error);
      res.status(500).json({ message: "Failed to update restaurant data" });
    }
  });

