  // Update call metadata (tags, notes, VIP status, etc.)
  app.patch('/api/restaurant/:agentId/calls/:callId/meta', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId, callId } = req.params;
      
      // Validate request body
      const validationResult = callMetaUpdateSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({ 
          message: "Invalid update data", 
          errors: validationResult.error.format() 
        });
      }
      
      // Verify ownership of the restaurant agent (agentId here is voiceAgents.id)
      const agent = await storage.getVoiceAgent(agentId);
      if (!agent || agent.userId !== userId) {
        return res.status(403).json({ message: "Not authorized to update calls for this restaurant" });
      }

      // telephonyCallLogs.restaurantAgentId references restaurantData.id, NOT voiceAgents.id.
      // Resolve the restaurantData.id for this agent so we can look up the call correctly.
      const restaurantDataRecord = await storage.getRestaurantData(agentId);
      const restaurantDataId = restaurantDataRecord?.id;

      // Try primary lookup: call by callId AND restaurantData.id
      let existingCall = restaurantDataId
        ? await storage.getCallForAgent(callId, restaurantDataId)
        : undefined;

      // Fallback: fetch call directly by ID and verify ownership via phone numbers
      if (!existingCall) {
        const call = await storage.getCall(callId);
        if (!call) {
          return res.status(404).json({ message: "Call not found" });
        }

        // Verify the user owns this call via their assigned phone numbers
        const userPhoneNumbers = await storage.getUserPhoneNumbers(userId);
        const phoneNumberList = userPhoneNumbers.map(pn => pn.phoneNumber);
        const ownsCall = phoneNumberList.some(phone =>
          phone === call.toNumber || phone === call.fromNumber
        );

        if (!ownsCall) {
          return res.status(403).json({ message: "Not authorized to update this call" });
        }

        existingCall = call;
      }

      const validatedUpdates = validationResult.data;

      // Remove undefined values (keep only fields being updated)
      const sanitizedUpdates = Object.fromEntries(
        Object.entries(validatedUpdates).filter(([_, value]) => value !== undefined)
      );

      if (Object.keys(sanitizedUpdates).length === 0) {
        return res.status(400).json({ message: "No valid fields to update" });
      }

      const updatedCall = await storage.updateCallMeta(callId, sanitizedUpdates);

      // Manual flagging by user - do NOT send notifications (only AI auto-flags trigger notifications)
      if (sanitizedUpdates.flagged === true && existingCall.flagged !== true) {
        console.log(`🚩 MANUAL FLAG by user - NO notification sent (only AI auto-flags trigger alerts)`);
      }

      res.json(updatedCall);
    } catch (error) {
      console.error("Error updating call metadata:", error);
      res.status(500).json({ message: "Failed to update call metadata" });
    }
  });

