  // Helper function for fallback responses when OpenAI is unavailable
  function generateFallbackResponse(userInput: string): string {
    const input = userInput.toLowerCase();
    
    // Hours inquiries
    if (input.includes('hour') || input.includes('open') || input.includes('close') || input.includes('time')) {
      return "We're open Monday through Thursday 11 AM to 9 PM, Friday and Saturday 11 AM to 10 PM, and Sunday 12 PM to 8 PM. How can I help you today?";
    }
    
    // Reservation inquiries
    if (input.includes('reservation') || input.includes('book') || input.includes('table')) {
      return "I'd be happy to help with reservations! For immediate booking, please call us directly or I can take your information. What day and time were you thinking?";
    }
    
    // Menu inquiries
    if (input.includes('menu') || input.includes('food') || input.includes('pizza') || input.includes('special')) {
      return "We have delicious pizzas, pasta, and Italian specialties! Our most popular items are our wood-fired pizzas and fresh pasta. Would you like to hear about today's specials?";
    }
    
    // Location/directions
    if (input.includes('address') || input.includes('location') || input.includes('where') || input.includes('direction')) {
      return "We're located in the heart of downtown. I can text you our exact address and directions. What's your phone number?";
    }
    
    // Greetings
    if (input.includes('hi') || input.includes('hello') || input.includes('hey')) {
      return "Hello! Welcome to Pizza Palace! I'm your AI assistant. How can I help you today? I can assist with reservations, menu questions, hours, or directions.";
    }
    
    // Default response
    return "Thank you for calling Pizza Palace! I can help you with reservations, menu information, our hours, or directions. What would you like to know?";
  }

