  // Get active/live calls (authenticated)
  app.get('/api/telephony/calls/active', isAuthenticated, async (req, res) => {
    try {
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { agentId } = req.query;
      
      console.log(`📞 Active calls request: userId=${userId}, viewingOwnerId=${req.viewingOwnerId}, claims.sub=${req.user.claims.sub}, agentId=${agentId}`);

      // Get user's phone numbers for call history lookup
      let userPhoneNumbers = await storage.getUserPhoneNumbers(userId);
      
      console.log(`📞 User phone numbers from DB: ${userPhoneNumbers.length} assignments:`, userPhoneNumbers.map(a => ({ phoneNumber: a.phoneNumber, retellAgentId: a.retellAgentId })));
      
      // If agentId is provided, filter to only that agent's phone numbers
      // The agentId from frontend is the voice_agents.id, but we need to match
      // the retellAgentId in phone_number_assignments. Look up the voice agent first.
      if (agentId && typeof agentId === 'string') {
        // Look up the voice agent to get its retellAgentId
        const voiceAgent = await storage.getVoiceAgent(agentId);
        const retellAgentIdToMatch = voiceAgent?.retellAgentId;
        console.log(`📞 Voice agent lookup: agentId=${agentId}, retellAgentId=${retellAgentIdToMatch}`);
        
        userPhoneNumbers = userPhoneNumbers.filter(assignment => 
          assignment.retellAgentId === retellAgentIdToMatch ||
          assignment.retellAgentId === agentId ||
          (assignment as any).agentId === agentId
        );
        console.log(`📞 After agent filter (${agentId}): ${userPhoneNumbers.length} assignments`);
      }
      
      const phoneNumbers = userPhoneNumbers.map(assignment => assignment.phoneNumber);

      if (phoneNumbers.length === 0) {
        return res.json([]);
      }

      // Query for active calls (in-progress, ringing, queued, initiated, or answered) that started within the last hour
      // This prevents stale records from appearing as active
      const { or, inArray, desc, gt } = await import('drizzle-orm');
      const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);

      console.log(`📞 Active calls query starting: userId=${userId}, phoneNumbers=${JSON.stringify(phoneNumbers)}, oneHourAgo=${oneHourAgo.toISOString()}`);

      // First, check for any in-progress calls regardless of phone number (for debugging)
      const allInProgress = await db
        .select()
        .from(telephonyCallLogs)
        .where(eq(telephonyCallLogs.status, 'in-progress'));
      console.log(`📞 DEBUG: All in-progress calls in DB: ${allInProgress.length}`, allInProgress.map(c => ({ id: c.id, toNumber: c.toNumber, status: c.status })));

      const activeCalls = await db
        .select()
        .from(telephonyCallLogs)
        .where(
          and(
            or(
              eq(telephonyCallLogs.status, 'in-progress'),
              eq(telephonyCallLogs.status, 'ringing'),
              eq(telephonyCallLogs.status, 'queued'),
              eq(telephonyCallLogs.status, 'initiated'),
              eq(telephonyCallLogs.status, 'answered')
            ),
            inArray(telephonyCallLogs.toNumber, phoneNumbers),
            gt(telephonyCallLogs.startTime, oneHourAgo)
          )
        )
        .orderBy(desc(telephonyCallLogs.startTime));

      console.log(`✅ Found ${activeCalls.length} active calls for user:`, activeCalls.map(c => ({ id: c.id, status: c.status, toNumber: c.toNumber })));
      
      // Prevent caching for real-time active calls data
      res.set({
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        'Pragma': 'no-cache',
        'Expires': '0'
      });
      res.json(activeCalls);
    } catch (error) {
      console.error('Error fetching active calls:', error);
      res.status(500).json({ error: 'Failed to fetch active calls' });
    }
  });

