  // Sync SMS messages from Twilio to database (authenticated)
  app.post('/api/messaging/sync-sms', isAuthenticated, async (req, res) => {
    try {
      // Get userId from the user object (handle different auth methods)
      const userObj = req.user as any;
      const userId = userObj?.id || userObj?.claims?.sub || userObj;

      if (!userId) {
        return res.status(401).json({ error: 'User not authenticated' });
      }

      const userIdStr = String(userId);
      console.log(`🔄 Syncing SMS messages from Twilio for user: ${userIdStr}`);

      // Get user's phone number(s)
      const userPhoneNumbers = await storage.getUserPhoneNumbers(userIdStr);

      if (!userPhoneNumbers || userPhoneNumbers.length === 0) {
        return res.status(400).json({ error: 'No phone numbers found for this user' });
      }

      let totalSynced = 0;
      let totalSkipped = 0;

      // Sync messages for each phone number
      for (const phoneAssignment of userPhoneNumbers) {
        const phoneNumber = phoneAssignment.phoneNumber;
        console.log(`📱 Syncing messages for phone number: ${phoneNumber}`);

        try {
          // Get messages from Twilio (both sent and received)
          const twilioMessages = await twilioService.getSMSMessages({
            from: phoneNumber,
            limit: 1000
          });

          const sentMessages = twilioMessages;

          // Also get messages sent TO this number
          const receivedMessages = await twilioService.getSMSMessages({
            to: phoneNumber,
            limit: 1000
          });

          // Combine all messages
          const allMessages = [...sentMessages, ...receivedMessages];

          // Remove duplicates by message SID
          const uniqueMessages = allMessages.filter((msg, index, self) =>
            index === self.findIndex(m => m.sid === msg.sid)
          );

          console.log(`📨 Found ${uniqueMessages.length} unique messages for ${phoneNumber}`);

          // Save each message to database (skip if already exists)
          for (const twilioMsg of uniqueMessages) {
            try {
              // Check if message already exists
              const existingMessage = await db.query.smsMessages.findFirst({
                where: eq(smsMessages.twilioMessageSid, twilioMsg.sid)
              });

              if (existingMessage) {
                totalSkipped++;
                continue;
              }

              // Determine direction based on which number matches the user's phone
              const direction = twilioMsg.from === phoneNumber ? 'outbound' : 'inbound';

              // Insert new message
              await db.insert(smsMessages).values({
                userId: userIdStr,
                twilioMessageSid: twilioMsg.sid,
                fromNumber: twilioMsg.from,
                toNumber: twilioMsg.to,
                direction: direction,
                body: twilioMsg.body,
                status: twilioMsg.status,
                errorCode: twilioMsg.errorCode || null,
                errorMessage: twilioMsg.errorMessage || null,
                price: twilioMsg.price || null,
                priceUnit: twilioMsg.priceUnit || null,
                createdAt: twilioMsg.dateSent || twilioMsg.dateCreated,
              });

              totalSynced++;
            } catch (dbError: any) {
              console.error(`⚠️ Failed to save message ${twilioMsg.sid}:`, dbError);
            }
          }
        } catch (phoneError: any) {
          console.error(`⚠️ Failed to sync messages for ${phoneNumber}:`, phoneError);
        }
      }

      console.log(`✅ Sync complete: ${totalSynced} new messages saved, ${totalSkipped} already existed`);

      res.json({
        success: true,
        synced: totalSynced,
        skipped: totalSkipped,
        message: `Synced ${totalSynced} messages from Twilio`
      });
    } catch (error: any) {
      console.error('❌ Error syncing SMS messages from Twilio:', error);
      res.status(500).json({ error: error.message || 'Failed to sync SMS messages' });
    }
  });

