  // Send SMS message (authenticated)
  app.post('/api/messaging/send-sms', isAuthenticated, async (req, res) => {
    try {
      const { to, body } = req.body;

      // Get userId from the user object (handle different auth methods)
      const userObj = req.user as any;
      const userId = userObj?.id || userObj?.claims?.sub || userObj;

      if (!userId) {
        return res.status(401).json({ error: 'User not authenticated' });
      }

      const userIdStr = String(userId);
      console.log(`📱 Send SMS request from user: ${userIdStr}`);

      if (!to || !body) {
        return res.status(400).json({ error: 'Phone number and message body are required' });
      }

      // Phone number validation is now handled in twilioService.sendSMS() with automatic E.164 formatting
      // No need to validate format here - let the service handle it

      // Get user's provisioned Twilio phone number from subscription or phone numbers table
      let fromNumber: string | null = null;
      let phoneSource: string = '';

      // First try to get from user's phone numbers
      const userPhoneNumbers = await storage.getUserPhoneNumbers(userIdStr);
      if (userPhoneNumbers && userPhoneNumbers.length > 0) {
        fromNumber = userPhoneNumbers[0].phoneNumber;
        phoneSource = 'user phone numbers';
        console.log(`📱 Using user's provisioned phone number: ${fromNumber}`);
      }

      // Fallback to subscription's Twilio phone number
      if (!fromNumber) {
        const subscription = await storage.getUserSubscription(userIdStr);
        if (subscription?.twilioPhoneNumber) {
          fromNumber = subscription.twilioPhoneNumber;
          phoneSource = 'subscription';
          console.log(`📱 Using subscription phone number: ${fromNumber}`);
        }
      }

      // Fallback to business settings SMS phone number
      if (!fromNumber) {
        const businessSettings = await storage.getBusinessSettings(userIdStr);
        if (businessSettings?.twilioSmsPhoneNumber) {
          fromNumber = businessSettings.twilioSmsPhoneNumber;
          phoneSource = 'business settings SMS number';
          console.log(`📱 Using business settings SMS phone number: ${fromNumber}`);
        }
      }

      // Final fallback: use the transfer phone number from business settings
      if (!fromNumber) {
        const businessSettings = await storage.getBusinessSettings(userIdStr);
        if (businessSettings?.transferPhoneNumber) {
          fromNumber = businessSettings.transferPhoneNumber;
          phoneSource = 'business settings transfer number';
          console.log(`📱 Using transfer phone number as fallback: ${fromNumber}`);
        }
      }

      if (!fromNumber) {
        console.error(`❌ No phone number found for user ${userIdStr}`);
        return res.status(400).json({
          error: 'No Twilio phone number configured. Please complete your account setup to get a phone number.'
        });
      }

      console.log(`📞 Sending SMS from ${fromNumber} (${phoneSource}) to ${to}`);
      const message = await twilioService.sendSMS(to, body, fromNumber);

      console.log(`✅ SMS sent successfully: ${message.sid}, Status: ${message.status}`);

      // Save the sent message to the database
      try {
        await db.insert(smsMessages).values({
          userId: userIdStr,
          twilioMessageSid: message.sid,
          fromNumber: fromNumber,
          toNumber: to,
          direction: 'outbound',
          body: body,
          status: message.status,
          price: message.price || null,
          priceUnit: message.priceUnit || null,
        });
        console.log(`💾 Saved outbound SMS to database: ${message.sid}`);
      } catch (dbError: any) {
        console.error('⚠️ Failed to save SMS to database:', dbError);
        // Don't fail the request if database save fails
      }

      res.json({
        success: true,
        messageSid: message.sid,
        status: message.status,
        to: message.to,
        from: fromNumber,
        body: message.body
      });
    } catch (error: any) {
      console.error('❌ Error sending SMS:', error);

      // Provide more helpful error messages based on Twilio error codes
      let errorMessage = error.message || 'Failed to send SMS';

      if (error.code === 21614) {
        errorMessage = 'This phone number is not SMS-capable. Please contact support to enable SMS on your number.';
      } else if (error.code === 21211) {
        errorMessage = 'The recipient phone number is invalid. Please check the phone number format.';
      } else if (error.code === 21608) {
        errorMessage = 'The recipient number is unverified. For trial accounts, verify the number in your Twilio console.';
      } else if (error.code === 21610) {
        errorMessage = 'The recipient has opted out of receiving messages from this number.';
      }

      res.status(500).json({ error: errorMessage });
    }
  });

