  // NEW: Twilio Webhook for Retell AI Integration with Business Owner Fallback
  app.post('/api/twilio/voice-webhook', async (req, res) => {
    try {
      console.log('🔥 Incoming Twilio call webhook:', req.body);
      
      const { CallSid, From, To, CallStatus } = req.body;
      
      // Find which business this phone number belongs to
      const phoneAssignment = await storage.getPhoneNumberAssignmentByNumber(To);
      if (!phoneAssignment) {
        console.error(`❌ No phone assignment found for number: ${To}`);
        // Fallback TwiML response
        const fallbackTwiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
    <Say voice="Polly.Joanna">I'm sorry, this number is not configured. Please contact support.</Say>
    <Hangup/>
</Response>`;
        
        res.set('Content-Type', 'text/xml');
        return res.send(fallbackTwiml);
      }

      // Check trial limits - reject call if limits exceeded
      const { trialService } = await import('./services/TrialService');
      const canCall = await trialService.canMakeCall(phoneAssignment.userId);
      if (!canCall.allowed) {
        console.warn(`⏸️ Trial limit reached for user ${phoneAssignment.userId}: ${canCall.reason}`);
        const limitTwiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
    <Say voice="Polly.Joanna">Your trial has expired. Please upgrade your account to continue receiving calls.</Say>
    <Hangup/>
</Response>`;
        
        res.set('Content-Type', 'text/xml');
        return res.send(limitTwiml);
      }
      
      // Get business settings to check owner fallback preference
      const businessSettings = await storage.getBusinessSettings(phoneAssignment.userId);
      const enableOwnerFallback = businessSettings?.enableOwnerFallback || false;
      const ownerPhoneNumber = businessSettings?.ownerPhoneNumber;
      
      // Register the call with Retell AI to get a dynamic SIP URI
      let sipUri: string;
      try {
        const { RetellProvider } = await import('./services/RetellProvider');
        const retellProvider = new RetellProvider();
        const registered = await retellProvider.registerPhoneCall(
          phoneAssignment.retellAgentId,
          From,
          To,
          'inbound',
          { twilio_call_sid: CallSid }
        );
        sipUri = registered.sip_uri;
        console.log(`✅ Registered call with Retell AI, SIP URI: ${sipUri}`);
      } catch (retellError: any) {
        console.error(`❌ Failed to register call with Retell AI: ${retellError.message}`);
        const errorTwiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
    <Say voice="Polly.Joanna">We are sorry, but our AI receptionist is temporarily unavailable. Please try again shortly.</Say>
    <Hangup/>
</Response>`;
        res.set('Content-Type', 'text/xml');
        return res.send(errorTwiml);
      }

      // Create call log entry for monitoring
      // restaurantAgentId is a FK to restaurantData.id — leave null here since we
      // only have the Retell agent ID at this point; the webhook will populate it later.
      const callLogId = `call_${CallSid}_${Date.now()}`;
      await storage.createTelephonyCallLog({
        id: callLogId,
        twilioCallSid: CallSid,
        fromNumber: From,
        toNumber: To,
        direction: 'inbound',
        status: 'ringing',
        startTime: new Date()
      });

      let twimlResponse: string;

      if (enableOwnerFallback && ownerPhoneNumber) {
        console.log(`📞 Owner fallback enabled, trying owner first: ${ownerPhoneNumber}`);

        // TwiML with owner fallback (20 second timeout) then AI agent
        twimlResponse = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
    <Dial timeout="20" record="true" recordingStatusCallback="/api/twilio/recording-status" statusCallback="/api/twilio/call-status" statusCallbackEvent="initiated,ringing,answered,completed">
        <Number statusCallback="/api/twilio/call-status" statusCallbackEvent="initiated,ringing,answered,completed">${ownerPhoneNumber}</Number>
    </Dial>
    <Dial record="true" recordingStatusCallback="/api/twilio/recording-status" statusCallback="/api/twilio/call-status" statusCallbackEvent="initiated,ringing,answered,completed">
        <Sip statusCallback="/api/twilio/call-status" statusCallbackEvent="initiated,ringing,answered,completed">${sipUri}</Sip>
    </Dial>
</Response>`;
      } else {
        console.log(`🤖 Routing directly to Retell AI agent: ${phoneAssignment.retellAgentId}`);

        // Direct routing to Retell AI agent
        twimlResponse = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
    <Dial record="true" recordingStatusCallback="/api/twilio/recording-status" statusCallback="/api/twilio/call-status" statusCallbackEvent="initiated,ringing,answered,completed">
        <Sip statusCallback="/api/twilio/call-status" statusCallbackEvent="initiated,ringing,answered,completed">${sipUri}</Sip>
    </Dial>
</Response>`;
      }
      
      console.log('📞 Sending TwiML response for call routing');
      res.set('Content-Type', 'text/xml');
      res.send(twimlResponse);
      
    } catch (error) {
      console.error('❌ Twilio voice webhook error:', error);
      
      // Fallback TwiML response
      const fallbackTwiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
    <Say voice="Polly.Joanna">I'm sorry, we're experiencing technical difficulties. Please try calling back in a few minutes.</Say>
    <Hangup/>
</Response>`;
      
      res.set('Content-Type', 'text/xml');
      res.send(fallbackTwiml);
    }
  });

  // NEW: Twilio Call Status Update Webhook
  app.post('/api/twilio/call-status', async (req, res) => {
    try {
      // TODO: Add Twilio signature validation for security
      // const twilioSignature = req.headers['x-twilio-signature'];
      // if (!twilioService.validateWebhookSignature(req.url, req.body, twilioSignature)) {
      //   return res.status(403).json({ error: 'Invalid signature' });
      // }
      
      console.log('📊 Twilio call status update:', req.body);
      
      const { CallSid, CallStatus, Duration, CallDuration, From, To, EndTime } = req.body;
      
      if (!CallSid) {
        console.warn('⚠️ No CallSid in status update');
        return res.status(400).json({ error: 'CallSid required' });
      }
      
      // Update call log with new status and duration
      const existingLog = await storage.getTelephonyCallLogByTwilioSid(CallSid);
      if (existingLog) {
        // Check if this is a Retell-handled call
        const convData = existingLog.conversationData as any;
        const isRetellCall = convData?.retell_call_id || convData?.retellCallId || convData?.retell_agent_id;

        // Check if this call was transferred
        const isTransferredCall = convData?.transferred === true;

        // For Retell calls, handle duration carefully:
        // 1. If duration is already set by Retell, skip the status update to avoid conflicts
        // 2. If duration is missing (null or 0), allow Twilio to update it as fallback
        // 3. Always allow updates for transferred calls
        if (isRetellCall && CallStatus === 'completed' && existingLog.status === 'in-progress' && !isTransferredCall) {
          // Check if duration is already set by Retell
          if (existingLog.duration && existingLog.duration > 0) {
            console.log(`⏳ Skipping Twilio completed status for active Retell call ${CallSid} - Retell already set duration: ${existingLog.duration}s`);
            return res.status(200).json({ success: true });
          }
          // If duration is missing, continue to allow Twilio to set it
          console.log(`⚠️ Retell call ${CallSid} missing duration, using Twilio's duration as fallback`);
        }

        const updateData: any = {
          status: CallStatus,
          updatedAt: new Date()
        };

        // Add duration and end time for completed calls
        if (CallStatus === 'completed' && (Duration || CallDuration)) {
          const durationSeconds = Duration || CallDuration;
          updateData.duration = parseInt(durationSeconds);
          updateData.endTime = EndTime ? new Date(EndTime) : new Date();

          // Deduct trial minutes if user is on trial
          try {
            const phoneAssignment = await storage.getPhoneNumberAssignmentByNumber(To);
            if (phoneAssignment) {
              const { trialService } = await import('./services/TrialService');
              await trialService.deductMinutes(phoneAssignment.userId, parseInt(durationSeconds));
              console.log(`📊 Deducted ${durationSeconds}s from trial for user ${phoneAssignment.userId}`);
            }
          } catch (error) {
            console.error('Error deducting trial minutes:', error);
            // Don't fail the webhook if trial deduction fails
          }
        }

        await storage.updateTelephonyCallLog(existingLog.id, updateData);
        if (isTransferredCall) {
          console.log(`✅ Updated transferred call log ${existingLog.id} with status: ${CallStatus} (was transferred at ${convData.transferredAt})`);
        } else {
          console.log(`✅ Updated call log ${existingLog.id} with status: ${CallStatus}`);
        }
      } else {
        console.warn(`⚠️ No call log found for CallSid: ${CallSid}`);
      }
      
      res.status(200).json({ success: true });
    } catch (error) {
      console.error('❌ Error processing call status update:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  });

