  // Voice Status Callback - Handle call status updates from Twilio for live call display
  app.post('/api/voice/status-callback', async (req, res) => {
    try {
      console.log('📞 Voice status callback received:', JSON.stringify(req.body, null, 2));
      
      const { CallSid, CallStatus, From, To, Direction, Duration, Timestamp } = req.body;
      
      if (!CallSid) {
        console.warn('⚠️ Voice status callback missing CallSid');
        return res.status(200).send('OK');
      }

      console.log(`📞 Call ${CallSid}: Status=${CallStatus}, From=${From}, To=${To}`);

      // Check if a log already exists for this call
      const existingLog = await storage.getTelephonyCallLogByTwilioSid(CallSid);

      if (CallStatus === 'ringing' || CallStatus === 'initiated' || CallStatus === 'queued') {
        // Create new call log for incoming call
        if (!existingLog) {
          const callLogId = `call_${CallSid}_${Date.now()}`;
          await storage.createTelephonyCallLog({
            id: callLogId,
            twilioCallSid: CallSid,
            fromNumber: From || '',
            toNumber: To || '',
            direction: Direction?.toLowerCase() === 'outbound-api' ? 'outbound' : 'inbound',
            status: CallStatus,
            startTime: new Date()
          });
          console.log(`✅ Created call log ${callLogId} with status: ${CallStatus}`);
        } else {
          // Update existing log
          await storage.updateTelephonyCallLog(existingLog.id, {
            status: CallStatus
          });
          console.log(`✅ Updated call log ${existingLog.id} to status: ${CallStatus}`);
        }
      } else if (CallStatus === 'in-progress' || CallStatus === 'answered') {
        // Update to in-progress
        if (existingLog) {
          await storage.updateTelephonyCallLog(existingLog.id, {
            status: 'in-progress'
          });
          console.log(`✅ Updated call log ${existingLog.id} to in-progress`);
        } else {
          // Create if doesn't exist
          const callLogId = `call_${CallSid}_${Date.now()}`;
          await storage.createTelephonyCallLog({
            id: callLogId,
            twilioCallSid: CallSid,
            fromNumber: From || '',
            toNumber: To || '',
            direction: Direction?.toLowerCase() === 'outbound-api' ? 'outbound' : 'inbound',
            status: 'in-progress',
            startTime: new Date()
          });
          console.log(`✅ Created in-progress call log ${callLogId}`);
        }
      } else if (CallStatus === 'completed' || CallStatus === 'busy' || CallStatus === 'no-answer' || CallStatus === 'failed' || CallStatus === 'canceled') {
        // Update to final status - always update, Retell's call_analyzed webhook will add analytics later
        if (existingLog) {
          const updateData: any = {
            status: CallStatus,
            endTime: new Date()
          };

          // Only set duration from Twilio if it's not already set by Retell
          if (Duration && (!existingLog.duration || existingLog.duration === 0)) {
            updateData.duration = parseInt(Duration);
            console.log(`📊 Setting duration from Twilio for call ${existingLog.id}: ${Duration}s`);
          }

          await storage.updateTelephonyCallLog(existingLog.id, updateData);
          console.log(`✅ Updated call log ${existingLog.id} to ${CallStatus}`);
        }
      }

      res.status(200).send('OK');
    } catch (error) {
      console.error('❌ Error processing voice status callback:', error);
      res.status(200).send('OK'); // Still respond OK to prevent Twilio retries
    }
  });

