  // Sync subscription after Stripe Checkout redirect
  app.post('/api/billing/sync-checkout', isAuthenticated, async (req: any, res) => {
    try {
      const stripe = getStripe();
      const userId = req.viewingOwnerId || req.user.claims.sub;
      const { sessionId } = req.body;

      if (!sessionId) {
        return res.status(400).json({ message: 'sessionId is required' });
      }

      // Retrieve the checkout session from Stripe with expanded subscription
      const session = await stripe.checkout.sessions.retrieve(sessionId, {
        expand: ['subscription', 'subscription.items.data.price'],
      });

      if (!session.subscription) {
        return res.json({ success: false, message: 'No subscription found in session' });
      }

      const stripeSub = session.subscription as any;
      const planSlug = (session.metadata?.planSlug || stripeSub.metadata?.planSlug) as string | undefined;

      // Find existing DB subscription by Stripe subscription ID
      let existing = await storage.getUserSubscriptionByStripeId(stripeSub.id);

      if (existing) {
        // Update status to active and sync period data
        await storage.updateUserSubscription(existing.id, {
          status: stripeSub.status,
          currentPeriodStart: new Date(stripeSub.current_period_start * 1000),
          currentPeriodEnd: new Date(stripeSub.current_period_end * 1000),
          cancelAtPeriodEnd: stripeSub.cancel_at_period_end,
        });
        console.log(`✅ Synced subscription ${stripeSub.id} for user ${userId}: status=${stripeSub.status}`);
      } else if (planSlug && SUBSCRIPTION_PLANS[planSlug as keyof typeof SUBSCRIPTION_PLANS]) {
        // Subscription not yet in DB (webhook hasn't fired) — create it now
        const dbUser = await storage.getUser(userId);
        const dbPlanId = await getDbPlanIdFromSlug(planSlug);
        if (dbPlanId && dbUser?.stripeCustomerId) {
          await storage.createUserSubscription({
            userId,
            stripeCustomerId: dbUser.stripeCustomerId,
            stripeSubscriptionId: stripeSub.id,
            stripePriceId: stripeSub.items.data[0]?.price?.id || '',
            planId: dbPlanId,
            status: stripeSub.status,
            currentPeriodStart: new Date(stripeSub.current_period_start * 1000),
            currentPeriodEnd: new Date(stripeSub.current_period_end * 1000),
            cancelAtPeriodEnd: false,
            trialEnd: null,
          });
          console.log(`✅ Created subscription ${stripeSub.id} for user ${userId} via sync`);
        }
      }

      res.json({ success: true, status: stripeSub.status });
    } catch (error: any) {
      console.error('Error syncing checkout:', error);
      res.status(500).json({ message: error?.message || 'Failed to sync checkout' });
    }
  });

  // Billing portal redirect
  app.post('/api/billing/portal', async (req, res) => {
    console.log('🔐 Billing portal request received');
    console.log('🔐 Authentication status:', req.isAuthenticated());
    console.log('🔐 User session:', req.user ? 'Present' : 'Missing');

    if (!req.isAuthenticated()) {
      console.log('❌ Billing portal: User not authenticated');
      return res.status(401).json({ message: "Unauthorized" });
    }

    try {
      const user = req.user as any;
      const userId = user.claims.sub;
      const email = user.claims.email;

      console.log('✅ Billing portal: Processing for user', email);

      // Get Stripe instance (this will throw if not configured)
      const stripe = getStripe();

      // Get user from database to find Stripe customer ID
      const dbUser = await storage.getUser(userId);

      let customerId = dbUser?.stripeCustomerId;

      // Validate that the customer exists in Stripe
      if (customerId) {
        try {
          console.log('🔍 Validating Stripe customer:', customerId);
          await stripe.customers.retrieve(customerId);
          console.log('✅ Stripe customer validated:', customerId);
        } catch (customerError: any) {
          if (customerError.code === 'resource_missing') {
            console.log('⚠️ Stripe customer not found, will create new one');
            customerId = undefined; // Reset to trigger creation
          } else {
            throw customerError; // Re-throw other errors
          }
        }
      }

      // If no customer ID exists or customer was invalid, create one
      if (!customerId) {
        console.log('🆕 Creating new Stripe customer for user:', email);
        const customer = await stripe.customers.create({
          email: email,
          metadata: {
            userId: userId
          }
        });
        customerId = customer.id;
        console.log('✅ Created Stripe customer:', customerId);

        // Update user with Stripe customer ID
        await storage.upsertUser({
          id: userId,
          email: email,
          stripeCustomerId: customerId
        });
      } else {
        console.log('✅ Using existing Stripe customer:', customerId);
      }

      // Create billing portal session
      console.log('🎯 Creating billing portal session...');
      
      let session;
      try {
        session = await stripe.billingPortal.sessions.create({
          customer: customerId,
          return_url: `${req.protocol}://${req.get('host')}/dashboard`,
        });
      } catch (portalError: any) {
        // Check if error is due to missing configuration
        if (portalError.message?.includes('configuration') || portalError.message?.includes('customer portal settings')) {
          console.log('⚙️ No portal configuration found, creating default configuration...');
          
          try {
            // Create a default billing portal configuration
            const configuration = await stripe.billingPortal.configurations.create({
              business_profile: {
                headline: 'Manage your subscription',
              },
              features: {
                customer_update: {
                  allowed_updates: ['email', 'address'],
                  enabled: true,
                },
                invoice_history: {
                  enabled: true,
                },
                payment_method_update: {
                  enabled: true,
                },
                subscription_cancel: {
                  enabled: true,
                  mode: 'at_period_end',
                  cancellation_reason: {
                    enabled: true,
                    options: [
                      'too_expensive',
                      'missing_features',
                      'switched_service',
                      'unused',
                      'customer_service',
                      'too_complex',
                      'low_quality',
                      'other',
                    ],
                  },
                },
                // Note: subscription_update is disabled because it requires a products array
                // with specific Stripe product IDs. Enable this manually in Stripe Dashboard
                // at https://dashboard.stripe.com/settings/billing/portal if you want
                // customers to upgrade/downgrade plans
              },
              default_return_url: `${req.protocol}://${req.get('host')}/dashboard`,
            });

            console.log('✅ Created default portal configuration:', configuration.id);

            // Retry creating the portal session with the new configuration
            session = await stripe.billingPortal.sessions.create({
              customer: customerId,
              configuration: configuration.id,
              return_url: `${req.protocol}://${req.get('host')}/dashboard`,
            });

            console.log('✅ Portal session created with new configuration');
          } catch (configError) {
            console.error('❌ Failed to create portal configuration:', configError);
            throw portalError; // Throw original error if configuration creation fails
          }
        } else {
          throw portalError; // Re-throw if it's a different error
        }
      }

      console.log('✅ Billing portal session created:', session.url);
      res.json({ url: session.url });
    } catch (error) {
      console.error('❌ Billing portal error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      // Check if it's a Stripe configuration error
      if (errorMessage.includes('STRIPE_SECRET_KEY')) {
        res.status(503).json({
          message: 'Billing portal is currently unavailable. Please contact support.',
          error: errorMessage
        });
      } else if (errorMessage.includes('configuration') || errorMessage.includes('customer portal settings')) {
        res.status(500).json({
          message: 'Failed to configure billing portal. Please ensure your Stripe account is properly set up.',
          error: errorMessage
        });
      } else {
        res.status(500).json({
          message: 'Failed to access billing portal',
          error: errorMessage
        });
      }
    }
  });

