  // Get subscription details
  app.get('/api/billing/subscription', async (req, res) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Unauthorized" });
    }

    try {
      const user = req.user as any;
      const userId = user.claims.sub;
      const dbUser = await storage.getUser(userId);

      if (!dbUser?.stripeCustomerId) {
        return res.json({ subscription: null });
      }

      const stripe = getStripe();

      // Get active or trialing subscriptions with expanded data
      // Note: Stripe only allows 4 levels of expansion — do NOT expand price.product here
      const [activeSubscriptions, trialingSubscriptions] = await Promise.all([
        stripe.subscriptions.list({
          customer: dbUser.stripeCustomerId,
          status: 'active',
          limit: 1,
          expand: ['data.items.data.price'],
        }),
        stripe.subscriptions.list({
          customer: dbUser.stripeCustomerId,
          status: 'trialing',
          limit: 1,
          expand: ['data.items.data.price'],
        }),
      ]);

      const subscription = activeSubscriptions.data[0] || trialingSubscriptions.data[0] || null;

      // Extract plan details from subscription if available
      let planDetails = null;
      if (subscription && subscription.items.data.length > 0) {
        const item = subscription.items.data[0];
        const price = item.price;

        // Helper function to extract plan name from various sources
        const getPlanName = () => {
          // 1. Subscription metadata set by our own checkout/plan-switch code
          if (subscription.metadata?.planName) return subscription.metadata.planName;
          if (subscription.metadata?.plan_name) return subscription.metadata.plan_name;

          // 2. Price metadata or nickname
          if (price.metadata?.plan_name) return price.metadata.plan_name;
          if (price.nickname) return price.nickname;

          // 3. Map by price amount (cents)
          const amount = price.unit_amount || 0;
          if (amount === 9900) return 'Small';
          if (amount === 29900) return 'Medium';
          if (amount === 49900) return 'Large';

          // 4. Fetch product name as last resort (separate call to avoid depth limit)
          return 'Unknown';
        };

        planDetails = {
          amount: price.unit_amount, // Amount in cents
          currency: price.currency,
          interval: price.recurring?.interval,
          intervalCount: price.recurring?.interval_count,
          planName: getPlanName(),
          minutes: price.metadata?.minutes ? parseInt(price.metadata.minutes) : null,
          overageRate: price.metadata?.overage_rate ? parseFloat(price.metadata.overage_rate) : null,
        };
      }

      res.json({
        subscription,
        planDetails
      });
    } catch (error) {
      console.error('Error fetching subscription:', error);
      res.status(500).json({ message: 'Failed to fetch subscription' });
    }
  });

