  // Check usage and send warning if needed
  app.post('/api/billing/check-usage-warning', async (req, res) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Unauthorized" });
    }

    try {
      const user = req.user as any;
      const userId = user.claims.sub;
      const dbUser = await storage.getUser(userId);

      if (!dbUser || !dbUser.billingNotifyUsageWarning) {
        return res.json({ sent: false, message: 'Usage warnings disabled' });
      }

      // Get user subscription and stats
      const subscription = await storage.getUserSubscription(userId);
      const stats = await storage.getUserStats(userId);

      if (!subscription || !stats) {
        return res.json({ sent: false, message: 'No subscription or stats found' });
      }

      const planMinutes = subscription.minuteLimit || 800;
      const minutesUsed = stats.phoneMinutesThisMonth || 0;
      const percentageUsed = (minutesUsed / planMinutes) * 100;

      // Only send if at 80% or above
      if (percentageUsed >= 80 && percentageUsed < 100) {
        const { checkAndSendUsageWarning } = await import('./services/billingNotificationService');

        const sent = await checkAndSendUsageWarning(
          dbUser.email!,
          dbUser.firstName || dbUser.email!.split('@')[0],
          minutesUsed,
          planMinutes,
          subscription.planName || 'Subscription',
          subscription.overageRate || 0.45,
          dbUser.lastUsageWarningAt?.getTime()
        );

        if (sent) {
          // Update last warning timestamp
          await storage.upsertUser({
            id: userId,
            lastUsageWarningAt: new Date()
          });
        }

        return res.json({ sent, percentageUsed: percentageUsed.toFixed(1) });
      }

      res.json({ sent: false, percentageUsed: percentageUsed.toFixed(1), message: 'Below threshold' });
    } catch (error) {
      console.error('Error checking usage warning:', error);
      res.status(500).json({ message: 'Failed to check usage' });
    }
  });

  // Calculate proration for plan change
  app.get('/api/billing/proration/:priceId', async (req, res) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Unauthorized" });
    }

    try {
      const user = req.user as any;
      const userId = user.claims.sub;
      const { priceId } = req.params;
      
      const dbUser = await storage.getUser(userId);
      if (!dbUser?.stripeCustomerId) {
        return res.status(400).json({ message: 'No Stripe customer found' });
      }

      const subscription = await storage.getUserSubscription(userId);
      if (!subscription?.stripeSubscriptionId) {
        return res.status(400).json({ message: 'No active subscription found' });
      }

      // Retrieve current subscription from Stripe
      const stripeSubscription = await stripe.subscriptions.retrieve(subscription.stripeSubscriptionId);
      
      // Preview the upcoming invoice with the new price
      const upcomingInvoice = await stripe.invoices.retrieveUpcoming({
        customer: dbUser.stripeCustomerId,
        subscription: subscription.stripeSubscriptionId,
        subscription_items: [
          {
            id: stripeSubscription.items.data[0].id,
            price: priceId,
          },
        ],
        subscription_proration_behavior: 'always_invoice',
      });

      // Calculate next billing date
      const nextBillingDate = new Date(upcomingInvoice.period_end * 1000);
      const formattedDate = nextBillingDate.toLocaleDateString('en-US', {
        month: 'long',
        day: 'numeric',
        year: 'numeric',
      });

      res.json({
        proratedAmount: upcomingInvoice.amount_due, // Amount in cents
        newBillingDate: formattedDate,
      });
    } catch (error) {
      console.error('Error calculating proration:', error);
      res.status(500).json({ message: 'Failed to calculate proration' });
    }
  });

  // Create a SetupIntent so the client can save a card without charging it
  app.post('/api/billing/setup-intent', async (req: any, res) => {
    if (!req.isAuthenticated()) return res.status(401).json({ message: 'Unauthorized' });
    try {
      const userId = (req.user as any).claims.sub;
      const dbUser = await storage.getUser(userId);
      const stripe = getStripe();

      let customerId = dbUser?.stripeCustomerId;
      if (!customerId) {
        const customer = await stripe.customers.create({ email: dbUser?.email || '' });
        customerId = customer.id;
        await storage.updateUserStripeCustomerId(userId, customerId);
      }

      const setupIntent = await stripe.setupIntents.create({
        customer: customerId,
        usage: 'off_session',
      });
      res.json({ clientSecret: setupIntent.client_secret });
    } catch (error) {
      console.error('Error creating setup intent:', error);
      res.status(500).json({ message: 'Failed to create setup intent' });
    }
  });

  // Attach a confirmed payment method to the customer and set it as default
  app.post('/api/billing/attach-payment-method', async (req: any, res) => {
    if (!req.isAuthenticated()) return res.status(401).json({ message: 'Unauthorized' });
    try {
      const userId = (req.user as any).claims.sub;
      const { paymentMethodId } = req.body;
      if (!paymentMethodId) return res.status(400).json({ message: 'paymentMethodId is required' });

      const dbUser = await storage.getUser(userId);
      if (!dbUser?.stripeCustomerId) return res.status(400).json({ message: 'No Stripe customer found' });

      const stripe = getStripe();
      await stripe.paymentMethods.attach(paymentMethodId, { customer: dbUser.stripeCustomerId });
      await stripe.customers.update(dbUser.stripeCustomerId, {
        invoice_settings: { default_payment_method: paymentMethodId },
      });
      res.json({ success: true });
    } catch (error) {
      console.error('Error attaching payment method:', error);
      res.status(500).json({ message: 'Failed to attach payment method' });
    }
  });

  // Create or change a subscription using the customer's default payment method
  app.post('/api/billing/subscribe', async (req: any, res) => {
    if (!req.isAuthenticated()) return res.status(401).json({ message: 'Unauthorized' });
    try {
      const userId = (req.user as any).claims.sub;
      const { planSlug } = req.body;

      const selectedPlan = SUBSCRIPTION_PLANS[planSlug as keyof typeof SUBSCRIPTION_PLANS];
      if (!selectedPlan) return res.status(400).json({ message: 'Invalid plan slug' });

      const dbUser = await storage.getUser(userId);
      if (!dbUser?.stripeCustomerId) {
        return res.status(400).json({ message: 'No payment method on file. Please add a card first.' });
      }

      const stripe = getStripe();

      // Verify customer has a default payment method
      const customer = await stripe.customers.retrieve(dbUser.stripeCustomerId) as any;
      const defaultPM = customer.invoice_settings?.default_payment_method;
      if (!defaultPM) {
        return res.status(400).json({ message: 'No payment method on file. Please add a card first.' });
      }

      // Find or create a product for this plan
      const allProducts = await stripe.products.list({ limit: 100, active: true });
      let product = allProducts.data.find(p => p.name === `VoiceBot ${selectedPlan.name} Plan`);
      if (!product) {
        product = await stripe.products.create({
          name: `VoiceBot ${selectedPlan.name} Plan`,
          metadata: { planSlug, minutes: String(selectedPlan.minutes) },
        });
      }

      // Always create a fresh price to ensure correct amount
      const price = await stripe.prices.create({
        product: product.id,
        unit_amount: selectedPlan.amount,
        currency: 'usd',
        recurring: { interval: 'month' },
        metadata: { planSlug, minutes: String(selectedPlan.minutes) },
      });

      const existingSubscription = await storage.getUserSubscription(userId);
      // Only treat as a real existing subscription if the ID is a genuine Stripe sub_ ID
      const hasRealStripeSubscription = !!(
        existingSubscription?.stripeSubscriptionId?.startsWith('sub_')
      );
      let stripeSubscription: any;

      if (hasRealStripeSubscription) {
        // Update existing real Stripe subscription to new plan
        const sub = await stripe.subscriptions.retrieve(existingSubscription!.stripeSubscriptionId!);
        stripeSubscription = await stripe.subscriptions.update(existingSubscription!.stripeSubscriptionId!, {
          items: [{ id: sub.items.data[0].id, price: price.id }],
          proration_behavior: 'always_invoice',
        });
        await storage.updateUserSubscription(existingSubscription!.id, {
          stripePriceId: price.id,
          planName: selectedPlan.name,
          minuteLimit: selectedPlan.minutes,
          amount: selectedPlan.amount,
          currentPeriodEnd: new Date(stripeSubscription.current_period_end * 1000),
        });
      } else {
        // Create a brand-new Stripe subscription (covers first-time and trial-only users)
        stripeSubscription = await stripe.subscriptions.create({
          customer: dbUser.stripeCustomerId,
          items: [{ price: price.id }],
          default_payment_method: defaultPM,
          expand: ['latest_invoice.payment_intent'],
          metadata: { planSlug, planName: selectedPlan.name },
        });
        const dbPlanId = await getDbPlanIdFromSlug(planSlug);
        if (existingSubscription) {
          // Update the existing DB record (trial row) with the real Stripe IDs
          await storage.updateUserSubscription(existingSubscription.id, {
            stripeSubscriptionId: stripeSubscription.id,
            stripePriceId: price.id,
            planName: selectedPlan.name,
            minuteLimit: selectedPlan.minutes,
            amount: selectedPlan.amount,
            status: stripeSubscription.status,
            currentPeriodEnd: new Date(stripeSubscription.current_period_end * 1000),
          });
        } else if (dbPlanId) {
          await storage.createUserSubscription({
            userId,
            stripeCustomerId: dbUser.stripeCustomerId,
            stripeSubscriptionId: stripeSubscription.id,
            stripePriceId: price.id,
            planId: dbPlanId,
            status: stripeSubscription.status,
            currentPeriodStart: new Date(stripeSubscription.current_period_start * 1000),
            currentPeriodEnd: new Date(stripeSubscription.current_period_end * 1000),
            cancelAtPeriodEnd: false,
            trialEnd: null,
          });
        }
      }

      console.log(`✅ Subscribed user ${userId} to ${selectedPlan.name} plan (${stripeSubscription.id})`);
      res.json({ success: true, status: stripeSubscription.status, plan: selectedPlan.name });
    } catch (error: any) {
      console.error('Error subscribing:', error);
      res.status(500).json({ message: error?.message || 'Failed to subscribe' });
    }
  });

  // Change subscription plan
  app.post('/api/billing/change-plan', async (req, res) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Unauthorized" });
    }

    try {
      const user = req.user as any;
      const userId = user.claims.sub;
      const { priceId } = req.body;

      if (!priceId) {
        return res.status(400).json({ message: 'Price ID is required' });
      }

      const dbUser = await storage.getUser(userId);
      if (!dbUser?.stripeCustomerId) {
        return res.status(400).json({ message: 'No Stripe customer found' });
      }

      const subscription = await storage.getUserSubscription(userId);
      if (!subscription?.stripeSubscriptionId) {
        return res.status(400).json({ message: 'No active subscription found' });
      }

      // Retrieve current subscription from Stripe
      const stripeSubscription = await stripe.subscriptions.retrieve(subscription.stripeSubscriptionId);
      
      // Update the subscription with the new price
      const updatedSubscription = await stripe.subscriptions.update(subscription.stripeSubscriptionId, {
        items: [
          {
            id: stripeSubscription.items.data[0].id,
            price: priceId,
          },
        ],
        proration_behavior: 'always_invoice',
      });

      // Retrieve the price details to update our database
      const price = await stripe.prices.retrieve(priceId);
      const product = await stripe.products.retrieve(price.product as string);

      // Extract plan details from metadata
      const planMinutes = product.metadata?.minutes ? parseInt(product.metadata.minutes) : null;
      const planName = product.name || 'Unknown Plan';

      // Update subscription in our database
      await storage.updateUserSubscription(userId, {
        stripePriceId: priceId,
        planName: planName,
        minuteLimit: planMinutes,
        amount: price.unit_amount || 0,
        currentPeriodEnd: new Date(updatedSubscription.current_period_end * 1000),
      });

      res.json({
        success: true,
        message: 'Plan updated successfully',
        subscription: {
          planName,
          amount: price.unit_amount,
          minuteLimit: planMinutes,
        },
      });
    } catch (error: any) {
      console.error('Error changing plan:', error);
      res.status(500).json({ 
        message: error?.message || 'Failed to change plan' 
      });
    }
  });

  // Update Retell AI agent greeting
  app.post('/api/voice/update-agent-greeting', async (req, res) => {
    console.log('🎙️ Update agent greeting request received');
    
    if (!req.isAuthenticated()) {
      console.log('❌ Update greeting: User not authenticated');
      return res.status(401).json({ message: "Unauthorized" });
    }

    try {
      const { agentId, businessHoursGreeting, afterHoursGreeting } = req.body;

      if (!agentId || !businessHoursGreeting) {
        return res.status(400).json({ 
          message: 'Agent ID and business hours greeting are required' 
        });
      }

      // Check if RETELL_API_KEY is available
      const retellApiKey = process.env.RETELL_API_KEY;
      if (!retellApiKey) {
        console.log('❌ RETELL_API_KEY not configured');
        return res.status(500).json({ 
          message: 'Retell AI is not configured properly' 
        });
      }

      console.log(`🔄 Updating Retell agent ${agentId} with new greeting`);

      // Update agent using Retell API
      const response = await fetch(`https://api.retellai.com/update-agent/${agentId}`, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${retellApiKey}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          response_engine: {
            instructions: businessHoursGreeting
          }
        })
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        console.log('❌ Retell API error:', response.status, errorData);
        throw new Error(`Retell API error: ${response.status} ${response.statusText}`);
      }

      const result = await response.json();
      console.log('✅ Successfully updated Retell agent greeting');

      res.json({
        success: true,
        message: 'Agent greeting updated successfully',
        agentId: agentId
      });

    } catch (error) {
      console.error('❌ Failed to update agent greeting:', error);
      res.status(500).json({ 
        message: 'Failed to update agent greeting',
        error: error instanceof Error ? error.message : 'Unknown error'
      });
    }
  });

