  // Retell AI phone connection endpoint
  app.post('/api/restaurant/:restaurantId/connect-retell-phone', isAuthenticated, async (req, res) => {
    try {
      const { restaurantId } = req.params;
      const { phoneNumber, agentId } = req.body;

      if (!phoneNumber || !agentId) {
        return res.status(400).json({
          success: false,
          error: 'Missing required fields: phoneNumber and agentId'
        });
      }

      console.log(`🔗 Connecting Retell AI agent ${agentId} to phone ${phoneNumber} for restaurant ${restaurantId}`);

      // Get Retell provider and connect the phone
      const retellProvider = new RetellProvider(storage);
      const result = await retellProvider.connectAgentToPhoneNumber(agentId, phoneNumber);

      if (result.success) {
        // Configure Twilio phone number to point directly to Retell AI
        try {
          const { twilioService } = await import('./services/twilioService');

          // Get all Twilio phone numbers to find the SID for this number
          const existingNumbers = await twilioService.getExistingPhoneNumbers();
          const targetPhone = existingNumbers.find((phone: any) => phone.phoneNumber === phoneNumber);

          if (targetPhone) {
            // Configure Twilio phone number to use Retell AI's webhook endpoint directly
            await twilioService.updatePhoneNumberConfiguration(targetPhone.sid, {
              voiceUrl: 'https://api.retellai.com/twilio-voice-webhook',
              friendlyName: `Retell AI - ${restaurantId}`
            });
            console.log(`📞 Updated Twilio phone number ${phoneNumber} to use Retell AI webhook`);
          } else {
            console.warn(`⚠️ Twilio phone number ${phoneNumber} not found in account`);
          }
        } catch (twilioError) {
          console.warn(`⚠️ Failed to update Twilio configuration: ${twilioError}`);
          // Continue anyway since Retell connection succeeded
        }

        // Store the connection in the database
        await storage.upsertUserCredentials({
          userId: req.user.id,
          integrationType: 'retell_phone_connection',
          credentialName: phoneNumber,
          credentialValue: JSON.stringify({
            agentId,
            phoneNumber,
            restaurantId,
            connectedAt: new Date().toISOString()
          }),
          isActive: true
        });

        console.log(`✅ Successfully connected Retell AI to phone ${phoneNumber}`);

        res.json({
          success: true,
          message: `Phone number ${phoneNumber} has been connected to your Retell AI receptionist`,
          data: {
            agentId,
            phoneNumber,
            restaurantId
          }
        });
      } else {
        res.status(422).json({
          success: false,
          error: result.error || 'Failed to connect phone number',
          message: 'Unable to connect your phone number to Retell AI. Please check your credentials and try again.'
        });
      }

    } catch (error) {
      console.error('❌ Retell AI connection error:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to connect Retell AI phone',
        message: 'An error occurred while connecting your phone. Please try again later.'
      });
    }
  });

  // Complete address information for phone provisioning
  app.post('/api/address/complete', isAuthenticated, async (req, res) => {
    try {
      const { street, city, state, zipCode, country = 'US', subscriptionId } = req.body;
      const userId = req.user.id;

      // Validate required fields
      if (!street || !city || !state || !zipCode) {
        return res.status(400).json({
          success: false,
          error: 'All address fields are required: street, city, state, zipCode'
        });
      }

      console.log(`📍 Processing address completion for user ${userId}`);

      // Get the incomplete address data from business settings
      const businessSettings = await storage.getBusinessSettings(userId);
      let incompleteData = null;
      let targetSubscriptionId = subscriptionId;

      if (businessSettings && businessSettings.incompleteAddressData) {
        try {
          incompleteData = JSON.parse(businessSettings.incompleteAddressData);
          targetSubscriptionId = targetSubscriptionId || incompleteData.subscriptionId;
        } catch (error) {
          console.error('Error parsing incomplete address data:', error);
        }
      }

      if (!targetSubscriptionId) {
        return res.status(400).json({
          success: false,
          error: 'No subscription ID found for address completion'
        });
      }

      // Create complete business data with the provided address
      const completeBusinessData = {
        businessName: incompleteData?.businessName || 'Your Business',
        street,
        city,
        state,
        zipCode,
        country,
        businessAddress: `${street}, ${city}, ${state} ${zipCode}`,
        businessPhone: incompleteData?.businessPhone,
        businessWebsite: incompleteData?.businessWebsite,
        businessEmail: incompleteData?.businessEmail
      };

      // Resume phone provisioning with complete address
      const { integratedPhoneProvisioner } = await import('./services/integratedPhoneProvisioner');
      const provisioningResult = await integratedPhoneProvisioner.provisionPhoneWithEmergencyAddress({
        userId,
        subscriptionId: targetSubscriptionId,
        businessData: completeBusinessData,
        retellAgentId: incompleteData?.retellAgentId || '',
        areaCode: undefined, // Will be determined from address
        phoneNumberType: 'local'
      });

      if (provisioningResult.success && provisioningResult.phoneNumber) {
        // Clear the incomplete address flag from business settings
        await storage.upsertBusinessSettings(userId, {
          addressCompletionRequired: false,
          incompleteAddressData: null
        });

        // CRITICAL: Mark subscription as "completed" now that phone is provisioned
        await storage.markProvisioningCompleted(targetSubscriptionId, {
          retellAgentId: provisioningResult.retellAgentId || incompleteData?.retellAgentId || '',
          conversationFlowId: provisioningResult.retellAgentId || incompleteData?.retellAgentId || '',
          knowledgeBaseId: undefined, // May already be set from earlier provisioning
          twilioPhoneNumber: provisioningResult.phoneNumber,
          twilioPhoneSid: provisioningResult.phoneNumberSid || '',
          sipTrunkingSid: provisioningResult.sipTrunkingSid,
          emergencyAddressSid: provisioningResult.emergencyAddressSid
        });

        console.log('✅ Address completion and phone provisioning successful - subscription marked as completed');

        res.json({
          success: true,
          message: 'Address completed and phone number provisioned successfully',
          data: {
            phoneNumber: provisioningResult.phoneNumber,
            phoneNumberSid: provisioningResult.phoneNumberSid,
            emergencyAddressSid: provisioningResult.emergencyAddressSid
          }
        });
      } else {
        console.error('❌ Phone provisioning failed after address completion:', provisioningResult.error);

        res.status(422).json({
          success: false,
          error: 'Phone provisioning failed after address completion',
          details: provisioningResult.error
        });
      }

    } catch (error: any) {
      console.error('❌ Address completion error:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to complete address and provision phone number',
        details: error.message
      });
    }
  });

