  // Update a knowledge source (for text and URL sources)
  app.patch('/api/knowledge-sources/:sourceId', isAuthenticated, async (req: any, res) => {
    try {
      const { sourceId } = req.params;
      const { title, textContent, url, autoRefresh, refresh } = req.body;
      const userId = req.user.claims.sub;

      // Get the source first to verify ownership
      const source = await storage.getKnowledgeSource(sourceId);
      if (!source) {
        return res.status(404).json({ message: 'Knowledge source not found' });
      }

      // Verify the agent belongs to the user
      const agent = await storage.getVoiceAgent(source.agentId);
      if (!agent || agent.userId !== userId) {
        return res.status(403).json({ message: 'Not authorized' });
      }

      // Handle refresh request for URL sources
      if (refresh && source.type === 'url') {
        console.log(`🔄 Refreshing URL source: ${source.url}`);

        // Update the updatedAt timestamp to indicate refresh
        await storage.updateKnowledgeSource(sourceId, {
          updatedAt: new Date()
        });

        // If using Retell AI, trigger re-scraping by updating the source
        if (source.knowledgeBaseId && source.sourceId && source.url) {
          const provider = getActiveVoiceProvider(storage);
          try {
            await fetch(`https://api.retellai.com/v2/knowledge-base/${source.knowledgeBaseId}/source/${source.sourceId}`, {
              method: 'PATCH',
              headers: {
                'Authorization': `Bearer ${process.env.RETELL_API_KEY}`,
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({
                url: source.url // Re-submit the same URL to trigger re-scraping
              })
            });
            console.log('✅ URL source refreshed in Retell AI');
          } catch (retellError) {
            console.error('❌ Error refreshing in Retell AI:', retellError);
            // Continue anyway - at least we updated the timestamp
          }
        }

        const updatedSource = await storage.getKnowledgeSource(sourceId);
        return res.json(updatedSource);
      }

      // Update based on source type
      if (source.type === 'text' && textContent !== undefined) {
        let newSourceId = source.sourceId;

        // Update text content in Retell AI using delete + add pattern
        if (source.knowledgeBaseId && source.sourceId) {
          try {
            console.log(`🔄 Updating text source in Retell AI: ${source.sourceId}`);
            
            // Step 1: Delete the old source from Retell AI
            const deleteResponse = await fetch(`https://api.retellai.com/delete-knowledge-base-source/${source.knowledgeBaseId}/source/${source.sourceId}`, {
              method: 'DELETE',
              headers: {
                'Authorization': `Bearer ${process.env.RETELL_API_KEY}`,
                'Content-Type': 'application/json'
              }
            });

            if (deleteResponse.ok) {
              console.log('✅ Old text source deleted from Retell AI');
            } else {
              const errorData = await deleteResponse.json().catch(() => ({}));
              console.warn('⚠️ Failed to delete old source from Retell AI:', deleteResponse.status, errorData);
            }

            // Step 2: Add the new source to Retell AI
            const formData = new FormData();
            formData.append('knowledge_base_texts', JSON.stringify([{
              title: title || source.title || 'Text Source',
              text: textContent
            }]));

            const addResponse = await fetch(`https://api.retellai.com/add-knowledge-base-sources/${source.knowledgeBaseId}`, {
              method: 'POST',
              headers: {
                'Authorization': `Bearer ${process.env.RETELL_API_KEY}`
              },
              body: formData
            });

            if (addResponse.ok) {
              const addResult = await addResponse.json();
              console.log('✅ New text source added to Retell AI:', addResult);
              
              // Get the new source ID from the response
              if (addResult.knowledge_base_sources && addResult.knowledge_base_sources.length > 0) {
                newSourceId = addResult.knowledge_base_sources[0].source_id;
                console.log(`✅ New source ID: ${newSourceId}`);
              }
            } else {
              const errorData = await addResponse.json().catch(() => ({}));
              console.error('❌ Failed to add new source to Retell AI:', addResponse.status, errorData);
              throw new Error('Failed to update source in Retell AI');
            }
          } catch (retellError: any) {
            console.error('❌ Error updating text source in Retell AI:', retellError);
            // Continue with database update even if Retell update fails
          }
        }

        // Update in database with new sourceId if it changed
        await storage.updateKnowledgeSource(sourceId, {
          textContent,
          title: title || source.title,
          sourceId: newSourceId, // Update with new Retell AI source ID
          updatedAt: new Date()
        });
      } else if (source.type === 'url' && (url !== undefined || autoRefresh !== undefined)) {
        const updateData: any = { updatedAt: new Date() };

        if (url !== undefined && url !== source.url) {
          // If URL changed, need to re-scrape
          // For now, just update the URL and autoRefresh setting
          updateData.url = url;
        }

        if (autoRefresh !== undefined) {
          updateData.autoRefresh = autoRefresh;
        }

        await storage.updateKnowledgeSource(sourceId, updateData);
      }

      const updatedSource = await storage.getKnowledgeSource(sourceId);
      res.json(updatedSource);
    } catch (error: any) {
      console.error('❌ Error updating knowledge source:', error);
      res.status(500).json({
        message: error.message || 'Failed to update knowledge source'
      });
    }
  });

