  // Create a new customer memory
  app.post('/api/customer-memories', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.claims.sub;
      const { customerProfileId, agentId, title, content } = req.body;

      // Basic input validation
      if (!agentId || typeof agentId !== 'string') {
        return res.status(400).json({ message: 'agentId is required' });
      }
      if (!customerProfileId || typeof customerProfileId !== 'string') {
        return res.status(400).json({ message: 'customerProfileId is required' });
      }
      if (title !== undefined && title !== null && typeof title === 'string' && title.length > 200) {
        return res.status(400).json({ message: 'Title must be 200 characters or fewer' });
      }
      if (content !== undefined && content !== null && typeof content === 'string' && content.length > 100_000) {
        return res.status(400).json({ message: 'Content must be 100,000 characters or fewer' });
      }

      // Verify the agent belongs to the user
      const agent = await storage.getVoiceAgent(agentId);
      if (!agent || agent.userId !== userId) {
        return res.status(403).json({ message: 'Not authorized' });
      }

      // Verify the customer profile belongs to this agent to prevent cross-agent data injection
      const customerProfile = await storage.getCustomerProfile(customerProfileId);
      if (!customerProfile || customerProfile.agentId !== agentId) {
        return res.status(403).json({ message: 'Customer does not belong to this agent' });
      }

      // Calculate word count
      const wordCount = content ? content.split(/\s+/).filter((w: string) => w.length > 0).length : 0;

      const memory = await storage.createCustomerMemory({
        customerProfileId,
        agentId,
        userId,
        title: title || null,
        content: content || null,
        wordCount,
      });

      res.json({ memory });
    } catch (error: any) {
      console.error('❌ Error creating customer memory:', error);
      res.status(500).json({
        message: error.message || 'Failed to create customer memory'
      });
    }
  });

