  // Admin: retry provisioning for a specific user (for fixing failed sign-ups)
  app.post('/api/admin/retry-provision/:userId', async (req, res) => {
    try {
      const userId = req.params.userId;
      console.log(`🔧 [ADMIN] Retrying provisioning for user: ${userId}`);

      if (!userId) {
        return res.status(400).json({ success: false, error: 'userId is required' });
      }

      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ success: false, error: `User ${userId} not found` });
      }

      const subscription = await storage.getUserSubscription(userId);
      if (!subscription) {
        return res.status(404).json({ success: false, error: `No subscription found for user ${userId}` });
      }

      // Reset provisioning status to allow retry
      await storage.markProvisioningFailed(subscription.id, 'reset_for_retry');
      console.log(`🔄 Reset provisioning status for subscription ${subscription.id}`);

      // Get business info for this user
      const businessInfoText = await getRawBusinessInfoForUser(userId);
      if (!businessInfoText) {
        return res.status(400).json({
          success: false,
          error: 'No business information found for this user. They need to complete onboarding first.'
        });
      }

      console.log(`📋 Business info found (${businessInfoText.length} chars), starting provisioning...`);

      const { SubscriptionProvisioningService } = await import('./services/SubscriptionProvisioningService');
      const provisioningService = new SubscriptionProvisioningService();

      const result = await provisioningService.provisionSubscription(
        userId,
        subscription.id,
        businessInfoText
      );

      console.log(`✅ [ADMIN] Provisioning completed for user ${userId}:`, result);

      res.json({
        success: result.success,
        userId,
        subscriptionId: subscription.id,
        retellAgentId: result.retellAgentId,
        phoneNumber: result.twilioPhoneNumber,
        knowledgeBaseId: result.knowledgeBaseId,
        warnings: result.warnings,
        error: result.error
      });

    } catch (error: any) {
      console.error(`❌ [ADMIN] Retry provisioning failed:`, error);
      res.status(500).json({ success: false, error: error.message });
    }
  });

