  // SMS ENDPOINTS - Unified send_sms_confirmation handler
  app.post('/api/retell/send_sms_confirmation', async (req: any, res) => {
    try {
      console.log('📧 ===== UNIFIED SMS CONFIRMATION CALLED =====');
      
      // Retell AI custom function format: { call: {...}, name: "...", args: {...} }
      const { args, call, name, arguments: funcArguments } = req.body;
      const effectiveArgs = args || funcArguments || {};
      
      const callId = call?.call_id;
      const agentId = call?.agent_id;
      // from_number is null for SIP-routed calls (Twilio→SIP→Retell); real caller is in call.metadata.original_from
      const fromNumber = call?.from_number || call?.metadata?.original_from || call?.metadata?.from_number;
      const toNumber = call?.to_number || call?.metadata?.original_to; // Business phone number
      const functionName = name || effectiveArgs?.function_name || 'send_sms_confirmation';
      
      console.log('📧 Parsed data:');
      console.log('📧   Call ID:', callId);
      console.log('📧   Agent ID:', agentId);
      console.log('📧   From Number (customer):', fromNumber);
      console.log('📧   To Number (business):', toNumber);
      console.log('📧   Function name:', functionName);
      console.log('📧   Args:', JSON.stringify(effectiveArgs, null, 2));

      // Use customer_phone from args or from_number from call metadata
      const customerPhone = effectiveArgs?.customer_phone || effectiveArgs?.phone || fromNumber;
      const actionType = effectiveArgs?.action_type || 'confirmation';
      const details = effectiveArgs?.details || effectiveArgs || {};
      const effectiveAgentId = effectiveArgs?.agent_id || agentId;

      console.log('📧 Customer phone (caller):', customerPhone);

      // Get SMS settings from database
      let smsMessageType = 'prompt';
      let smsContent = '';
      let smsBody = '';
      let recipientPhoneFromSettings2: string | null = null;

      if (effectiveAgentId) {
        try {
          // First get the voiceAgent to find the agent ID
          const voiceAgent = await db.query.voiceAgents.findFirst({
            where: eq(voiceAgents.retellAgentId, effectiveAgentId)
          });

          if (voiceAgent) {
            // 1. Look up by exact function name (user-created actions like 'message', 'notify_team', etc.)
            // 2. Fall back to send_sms_confirmation for built-in flow
            // 3. Fall back to appointment actions for backward compat
            const functionSettings = (functionName && functionName !== 'send_sms_confirmation'
              ? await db.query.agentFunctionSettings.findFirst({
                  where: and(
                    eq(agentFunctionSettings.agentId, voiceAgent.id),
                    eq(agentFunctionSettings.functionName, functionName)
                  )
                })
              : null)
              || await db.query.agentFunctionSettings.findFirst({
                  where: and(
                    eq(agentFunctionSettings.agentId, voiceAgent.id),
                    eq(agentFunctionSettings.functionName, 'send_sms_confirmation')
                  )
                })
              || await db.query.agentFunctionSettings.findFirst({
                  where: and(
                    eq(agentFunctionSettings.agentId, voiceAgent.id),
                    or(
                      eq(agentFunctionSettings.functionName, 'book_appointment'),
                      eq(agentFunctionSettings.functionName, 'cancel_appointment'),
                      eq(agentFunctionSettings.functionName, 'modify_appointment_details'),
                      eq(agentFunctionSettings.functionName, 'reschedule_appointment')
                    )
                  )
                });

            if (functionSettings) {
              smsMessageType = functionSettings.smsMessageType || 'prompt';
              smsContent = functionSettings.smsContent || '';
              recipientPhoneFromSettings2 = (functionSettings as any).recipientPhone || null;
              console.log(`📧 Found SMS settings for '${functionSettings.functionName}': type=${smsMessageType}, recipientPhone=${recipientPhoneFromSettings2 || 'none'}, content=${smsContent?.substring(0, 50)}...`);
            }
          }
        } catch (dbError) {
          console.error('Error fetching SMS settings:', dbError);
        }
      }

      // Replace placeholders in recipientPhone if it contains any (e.g., {{customer_phone_number}})
      let processedRecipientPhone2 = recipientPhoneFromSettings2;
      if (recipientPhoneFromSettings2 && recipientPhoneFromSettings2.includes('{{')) {
        const allData = { ...details, ...args };
        console.log(`📧 [DEBUG] Processing recipientPhone placeholders: ${recipientPhoneFromSettings2}`);

        processedRecipientPhone2 = recipientPhoneFromSettings2.replace(/\{\{([^}]+)\}\}/gi, (match, placeholderName) => {
          const normalizedName = placeholderName.trim();

          // Try exact match
          if (allData[normalizedName] !== undefined && allData[normalizedName] !== null) {
            console.log(`📧 [DEBUG] ✓ Recipient phone placeholder match: ${normalizedName} = ${allData[normalizedName]}`);
            return String(allData[normalizedName]);
          }

          // Try underscored version
          const underscored = normalizedName.replace(/\s+/g, '_');
          if (allData[underscored] !== undefined && allData[underscored] !== null) {
            console.log(`📧 [DEBUG] ✓ Recipient phone placeholder match (underscored): ${underscored} = ${allData[underscored]}`);
            return String(allData[underscored]);
          }

          // Try spaced version
          const spaced = normalizedName.replace(/_/g, ' ');
          if (allData[spaced] !== undefined && allData[spaced] !== null) {
            console.log(`📧 [DEBUG] ✓ Recipient phone placeholder match (spaced): ${spaced} = ${allData[spaced]}`);
            return String(allData[spaced]);
          }

          console.log(`📧 [DEBUG] ✗ No match for recipient phone placeholder: ${normalizedName}`);
          return '';
        });

        console.log(`📧 [DEBUG] Processed recipientPhone: ${recipientPhoneFromSettings2} → ${processedRecipientPhone2}`);
      }

      // Use fixed recipient phone from settings (team notification) or fall back to customer's phone
      const smsDestination2 = processedRecipientPhone2 || customerPhone;
      console.log(`📧 SMS destination: ${smsDestination2} (${processedRecipientPhone2 ? 'fixed recipient from settings' : 'customer phone'})`)

      // Generate SMS content
      if (smsMessageType === 'static' && smsContent) {
        // Static message - replace variables
        // Combine args and details for comprehensive placeholder replacement
        const allData = { ...details, ...args };

        // Replace ALL {{placeholder}} patterns dynamically with values from args/details
        smsBody = smsContent.replace(/\{\{([^}]+)\}\}/gi, (match, placeholderName) => {
          const normalizedName = placeholderName.trim();

          // Try exact match first
          if (allData[normalizedName] !== undefined && allData[normalizedName] !== null) {
            return String(allData[normalizedName]);
          }

          // Try converting spaces to underscores (e.g., "customer name" → "customer_name")
          const underscored = normalizedName.replace(/\s+/g, '_');
          if (allData[underscored] !== undefined && allData[underscored] !== null) {
            return String(allData[underscored]);
          }

          // Try converting underscores to spaces (e.g., "customer_name" → "customer name")
          const spaced = normalizedName.replace(/_/g, ' ');
          if (allData[spaced] !== undefined && allData[spaced] !== null) {
            return String(allData[spaced]);
          }

          // Special handling for common variations
          if (normalizedName.match(/appointment[_\s]?date/i)) {
            return String(allData.appointment_date || allData.date || '');
          }
          if (normalizedName.match(/appointment[_\s]?time/i)) {
            return String(allData.appointment_time || allData.time || '');
          }

          // If no match found, return empty string (don't show the placeholder)
          return '';
        });
      } else if (smsMessageType === 'prompt' && smsContent) {
        // AI-generated message using the prompt
        try {
          const aiResponse = await openai.chat.completions.create({
            model: 'gpt-4o-mini',
            messages: [
              {
                role: 'system',
                content: 'You are a helpful assistant that generates professional SMS messages for businesses. Generate a concise, friendly SMS message (under 160 characters if possible) based on the user\'s prompt and context. Do not include any quotes or extra formatting - just the message text.'
              },
              {
                role: 'user',
                content: `Generate an SMS message based on this prompt: "${smsContent}"
                
Context:
- Action type: ${actionType}
- Customer name: ${args?.customer_name || details?.customer_name || 'Customer'}
- Details: ${JSON.stringify(details)}
- Business context from conversation`
              }
            ],
            max_tokens: 100,
            temperature: 0.7
          });

          smsBody = aiResponse.choices[0]?.message?.content?.trim() || '';
          console.log(`📧 AI generated SMS: ${smsBody}`);
        } catch (aiError) {
          console.error('Error generating AI SMS:', aiError);
          // Fallback to a generic message
          smsBody = `Thank you for your ${actionType}! We'll be in touch shortly.`;
        }
      } else {
        // Default fallback message
        smsBody = `Thank you for your ${actionType}! We'll be in touch shortly.`;
      }

      // Send SMS via Twilio
      try {
        // Get the user's phone number to send from
        let fromPhoneNumber = null;

        if (effectiveAgentId) {
          const voiceAgent = await db.query.voiceAgents.findFirst({
            where: eq(voiceAgents.retellAgentId, effectiveAgentId)
          });

          if (voiceAgent?.userId) {
            const userPhoneNumbers = await storage.getUserPhoneNumbers(voiceAgent.userId);
            if (userPhoneNumbers && userPhoneNumbers.length > 0) {
              fromPhoneNumber = userPhoneNumbers[0].phoneNumber;
              console.log(`📧 Found user's phone number: ${fromPhoneNumber}`);
            } else {
              console.error(`❌ No phone numbers found for user ${voiceAgent.userId}`);
            }
          }
        }

        // Validate we have all required data
        if (!fromPhoneNumber) {
          console.error('❌ Cannot send SMS: No from phone number available');
          return res.json({
            success: false,
            error: 'No phone number configured',
            message: 'I apologize, but the confirmation text could not be sent. Your phone number needs to be configured.'
          });
        }

        if (!smsBody) {
          console.error('❌ Cannot send SMS: No message body generated');
          return res.json({
            success: false,
            error: 'No message content',
            message: 'I apologize, but the confirmation text could not be sent.'
          });
        }

        if (!smsDestination2) {
          console.error('❌ Cannot send SMS: No destination phone number available');
          return res.json({
            success: false,
            error: 'No destination phone number available',
            message: 'I apologize, but I cannot send the SMS right now.'
          });
        }

        console.log(`📧 Sending SMS from ${fromPhoneNumber} to ${smsDestination2}`);
        console.log(`📧 Message: ${smsBody}`);

        // Actually send the SMS
        const twilioResult = await twilioService.sendSMS(smsDestination2, smsBody, fromPhoneNumber);

        console.log(`✅ SMS sent successfully to ${smsDestination2}`);
        console.log(`✅ Twilio SID: ${twilioResult.sid}, Status: ${twilioResult.status}`);

        // Stamp order_amount onto the call log so Revenue metrics reflect the order total
        try {
          const orderTotal = parseFloat(
            details?.total || details?.order_total || details?.amount ||
            effectiveArgs?.total || effectiveArgs?.order_total || effectiveArgs?.amount || '0'
          );
          if (callId && orderTotal > 0) {
            const recentLogs = await storage.getTelephonyCallLogsByPhoneNumbers(
              [toNumber].filter(Boolean) as string[], 20, 0
            );
            const matchedLog = recentLogs.find((log: any) => {
              const cd = (log.conversationData as any) || {};
              return cd.retell_call_id === callId || cd.retellCallId === callId || log.twilioCallSid === callId;
            });
            if (matchedLog) {
              const existingCd = (matchedLog.conversationData as any) || {};
              await storage.updateTelephonyCallLog(matchedLog.id, {
                conversationData: { ...existingCd, order_amount: orderTotal }
              });
              console.log(`✅ Stamped order_amount $${orderTotal} on call log ${matchedLog.id}`);
            }
          }
        } catch (stampErr) {
          console.error('⚠️ Could not stamp order_amount on call log:', stampErr);
        }

        return res.json({
          success: true,
          message: 'Confirmation text sent successfully',
          action_type: actionType,
          sent_to: smsDestination2,
          sms_body: smsBody,
          twilio_sid: twilioResult.sid
        });

      } catch (twilioError: any) {
        console.error('❌ Error sending SMS via Twilio:', twilioError);
        console.error('❌ Error details:', {
          code: twilioError.code,
          message: twilioError.message,
          moreInfo: twilioError.moreInfo
        });

        // Return specific error messages based on Twilio error codes
        let errorMessage = 'I apologize, but the confirmation text could not be sent.';

        if (twilioError.code === 21614) {
          errorMessage = 'The phone number is not enabled for SMS. Please enable SMS in your Twilio console.';
          console.error('❌ SOLUTION: Enable SMS on your Twilio phone number in the Twilio console under Phone Numbers > Manage > Active Numbers');
        } else if (twilioError.code === 21211) {
          errorMessage = 'The recipient phone number format is invalid.';
        } else if (twilioError.code === 21608) {
          errorMessage = 'For trial accounts, the recipient number must be verified in Twilio.';
        } else if (twilioError.code === 21610) {
          errorMessage = 'The recipient has opted out of receiving messages.';
        }

        return res.json({
          success: false,
          error: twilioError.message || 'SMS sending failed',
          error_code: twilioError.code,
          message: errorMessage
        });
      }
    } catch (error) {
      console.error('❌ Error sending SMS confirmation:', error);
      res.status(500).json({ 
        success: false, 
        error: error instanceof Error ? error.message : 'Unknown error',
        message: 'I apologize, but the confirmation text could not be sent right now.'
      });
    }
  });

