  // NOTIFY TEAM ENDPOINT - "Leave a text message to our team" action
  // Sends SMS to team members assigned to this agent who have SMS enabled
  app.post('/api/retell/notify_team', async (req: any, res) => {
    try {
      console.log('💬 ===== NOTIFY TEAM CALLED =====');
      console.log('💬 Full request body:', JSON.stringify(req.body, null, 2));

      const { args, call } = req.body;
      const retellAgentId = call?.agent_id || args?.agent_id;
      const fromNumber = call?.from_number; // Customer's phone
      const toNumber = call?.to_number;   // Business Twilio number

      const customerName = args?.customer_name || args?.name || 'A customer';
      const customerMessage = args?.message || args?.customer_message || args?.details || 'left a message for the team';

      console.log('💬 Retell Agent ID:', retellAgentId);
      console.log('💬 Customer name:', customerName);
      console.log('💬 Customer message:', customerMessage);
      console.log('💬 Customer phone (from_number):', fromNumber);

      if (!retellAgentId) {
        console.error('❌ notify_team: No agent_id provided');
        return res.json({ success: false, message: 'Agent ID is required to notify team.' });
      }

      // Look up the voice agent by Retell agent ID
      const voiceAgent = await db.query.voiceAgents.findFirst({
        where: eq(voiceAgents.retellAgentId, retellAgentId)
      });

      if (!voiceAgent) {
        console.error(`❌ notify_team: No voice agent found for Retell ID ${retellAgentId}`);
        return res.json({ success: false, message: 'Voice agent not found.' });
      }

      const ownerId = voiceAgent.userId;
      const databaseAgentId = voiceAgent.id;

      console.log('💬 Voice agent found:', databaseAgentId, '| Owner:', ownerId);

      // Get the Twilio from-number
      let smsFromNumber = toNumber;
      const userPhoneNumbers = await storage.getUserPhoneNumbers(ownerId);
      if (userPhoneNumbers && userPhoneNumbers.length > 0) {
        smsFromNumber = userPhoneNumbers[0].phoneNumber;
        console.log('💬 Business Twilio number:', smsFromNumber);
      }

      if (!smsFromNumber) {
        console.error('❌ notify_team: No Twilio phone number found for owner', ownerId);
        return res.json({ success: false, message: 'No business phone number configured to send SMS from.' });
      }

      // Find team members assigned to this agent who have SMS enabled
      const teamMembersWithSms = await db
        .select({
          userId: teamMembers.userId,
          assignedAgentIds: teamMembers.assignedAgentIds,
          phoneNumber: users.phoneNumber,
          enableSMS: users.enableSMS,
          firstName: users.firstName,
          lastName: users.lastName
        })
        .from(teamMembers)
        .innerJoin(users, eq(teamMembers.userId, users.id))
        .where(eq(teamMembers.ownerId, ownerId));

      // Filter: must have SMS enabled, a phone number, and be assigned to this agent (or have no agent restrictions)
      const eligibleMembers = teamMembersWithSms.filter(m => {
        if (!m.enableSMS || !m.phoneNumber) return false;
        const assigned: string[] = (m.assignedAgentIds as string[]) || [];
        // If no agent restrictions or this agent is in the list
        return assigned.length === 0 || assigned.includes(databaseAgentId);
      });

      // Also notify the owner if they have SMS enabled
      const ownerRecord = await db.query.users.findFirst({
        where: eq(users.id, ownerId)
      });
      const ownerEligible = ownerRecord?.enableSMS && ownerRecord?.phoneNumber;

      console.log(`💬 Eligible team members: ${eligibleMembers.length} | Owner eligible: ${ownerEligible}`);

      const smsBody = `📩 ${customerName} left a message: "${customerMessage}"${fromNumber ? ` | Callback: ${fromNumber}` : ''}`;

      const recipients: string[] = [];
      if (ownerEligible && ownerRecord!.phoneNumber) {
        recipients.push(ownerRecord!.phoneNumber);
      }
      for (const member of eligibleMembers) {
        if (member.phoneNumber && !recipients.includes(member.phoneNumber)) {
          recipients.push(member.phoneNumber);
        }
      }

      if (recipients.length === 0) {
        console.warn('⚠️ notify_team: No eligible recipients with SMS enabled and phone numbers');
        return res.json({
          success: true,
          message: 'Message received. No team members have SMS notifications enabled.',
          recipients_notified: 0
        });
      }

      console.log(`💬 Sending SMS to ${recipients.length} recipient(s): ${recipients.join(', ')}`);

      const results: any[] = [];
      for (const recipientPhone of recipients) {
        try {
          const twilioResult = await twilioService.sendSMS(recipientPhone, smsBody, smsFromNumber);
          console.log(`✅ SMS sent to ${recipientPhone} | SID: ${twilioResult.sid}`);
          results.push({ phone: recipientPhone, sid: twilioResult.sid, status: twilioResult.status });
        } catch (smsErr: any) {
          console.error(`❌ Failed to send SMS to ${recipientPhone}:`, smsErr.message);
          results.push({ phone: recipientPhone, error: smsErr.message });
        }
      }

      const successCount = results.filter(r => !r.error).length;
      return res.json({
        success: successCount > 0,
        message: `Message delivered to ${successCount} of ${recipients.length} team member(s).`,
        recipients_notified: successCount,
        results
      });

    } catch (error) {
      console.error('❌ Error in notify_team webhook:', error);
      return res.status(500).json({
        success: false,
        message: error instanceof Error ? error.message : 'Failed to notify team'
      });
    }
  });

  // CUSTOMER MEMORY ENDPOINT - Retrieves customer history and context
  app.post('/api/retell/customer_memory', async (req: any, res) => {
    try {
      const { args, call } = req.body;
      const agentId = call?.agent_id;
      const fromNumber = call?.from_number; // Customer's phone number
      
      console.log('🧠 ===== CUSTOMER MEMORY CALLED =====');
      console.log('🧠 Phone number:', args?.phone_number || fromNumber);
      console.log('🧠 Agent ID:', args?.agent_id || agentId);

      // Use phone_number from args or from_number from call metadata
      const phoneNumber = args?.phone_number || fromNumber;
      const effectiveAgentId = args?.agent_id || agentId;

      if (!phoneNumber) {
        return res.json({
          success: true,
          is_new_customer: true,
          message: 'New customer - no previous history found'
        });
      }

      if (!effectiveAgentId) {
        return res.json({
          success: false,
          error: 'Agent ID not available',
          message: 'Unable to retrieve customer information at this time.'
        });
      }

      // Map agentId to userId
      const agent = await storage.getVoiceAgentByRetellAgentId(effectiveAgentId);
      if (!agent) {
        console.log('🧠 Agent not found');
        return res.json({
          success: true,
          is_new_customer: true,
          phone_number: phoneNumber,
          message: 'New customer - no previous history found'
        });
      }

      const userId = agent.userId;

      // Ensure agent has a contact_memory integration (auto-provision if missing)
      const agentIntegsForMemory = await storage.getAgentIntegrations(agent.id);
      const hasContactsIntegration = agentIntegsForMemory.some((i: any) => i.type === 'contact_memory');
      if (!hasContactsIntegration) {
        try {
          await storage.createAgentIntegration({
            userId,
            agentId: agent.id,
            name: 'Contacts',
            type: 'contact_memory',
            description: 'Built-in customer contact memory from Contacts tab',
          } as any);
          console.log('🔗 Auto-provisioned contact_memory integration for agent', agent.id);
        } catch (e) {
          console.warn('⚠️ Could not auto-provision contact_memory integration:', e);
        }
      }

      // Query customer profile by phone number and userId
      const customerProfile = await storage.getCustomerProfileByPhone(phoneNumber, userId);
      
      if (!customerProfile) {
        console.log('🧠 No previous customer profile found - new customer');
        return res.json({
          success: true,
          is_new_customer: true,
          phone_number: phoneNumber,
          message: 'New customer - no previous history found'
        });
      }

      const isVIP = customerProfile.tags?.includes('VIP') || false;
      
      console.log(`🧠 Found returning customer: ${customerProfile.name || 'Unknown'} (VIP: ${isVIP})`);
      
      return res.json({
        success: true,
        is_new_customer: false,
        customer_name: customerProfile.name,
        phone_number: customerProfile.phone,
        email: customerProfile.email,
        is_vip: isVIP,
        tags: customerProfile.tags || [],
        notes: customerProfile.notes,
        total_calls: customerProfile.totalCalls || 0,
        lifetime_value: customerProfile.lifetimeValue || 0,
        last_contact: customerProfile.lastContactDate,
        message: isVIP 
          ? `Welcome back, ${customerProfile.name}! We're happy to have you calling again.`
          : `Welcome back, ${customerProfile.name}!`
      });
    } catch (error) {
      console.error('❌ Error retrieving customer memory:', error);
      res.status(500).json({ 
        success: false, 
        error: error instanceof Error ? error.message : 'Unknown error',
        message: 'Unable to retrieve customer information at this time.'
      });
    }
  });

  // ── GET CUSTOMER MEMORY (conversation-flow agents — "Usual" confidence scoring) ─────────────────
  app.post('/api/retell/get_customer_memory', async (req: any, res) => {
    try {
      const { args, call } = req.body;
      const agentId = call?.agent_id;
      const fromNumber = call?.from_number;
      const phoneNumber = args?.phone_number || fromNumber;
      const effectiveAgentId = args?.agent_id || agentId;

      console.log('🧠 get_customer_memory called — phone:', phoneNumber, '| agent:', effectiveAgentId);

      if (!phoneNumber) {
        return res.json({ success: true, is_new_customer: true, message: 'New customer — no previous history found' });
      }
      if (!effectiveAgentId) {
        return res.json({ success: false, error: 'Agent ID not available' });
      }

      const agent = await storage.getVoiceAgentByRetellAgentId(effectiveAgentId);
      if (!agent) {
        return res.json({ success: true, is_new_customer: true, phone_number: phoneNumber, message: 'New customer — no previous history found' });
      }

      const userId = agent.userId;

      // Ensure agent has a contact_memory integration (auto-provision if missing)
      const agentIntegsForGet = await storage.getAgentIntegrations(agent.id);
      const hasContactsIntegrationGet = agentIntegsForGet.some((i: any) => i.type === 'contact_memory');
      if (!hasContactsIntegrationGet) {
        try {
          await storage.createAgentIntegration({
            userId,
            agentId: agent.id,
            name: 'Contacts',
            type: 'contact_memory',
            description: 'Built-in customer contact memory from Contacts tab',
          } as any);
          console.log('🔗 Auto-provisioned contact_memory integration for agent (get)', agent.id);
        } catch (e) {
          console.warn('⚠️ Could not auto-provision contact_memory integration:', e);
        }
      }

      const customerProfile = await storage.getCustomerProfileByPhone(phoneNumber, userId);
      if (!customerProfile) {
        console.log('🧠 New customer — no profile');
        return res.json({ success: true, is_new_customer: true, phone_number: phoneNumber, message: 'New customer — no previous history found' });
      }

      // Load agent-specific memory
      const memory = await storage.getCustomerMemoriesByCustomer(customerProfile.id, agent.id);

      // Parse content as JSON (graceful fallback for plain-text legacy records)
      let memoryData: Record<string, any> = {};
      if (memory?.content) {
        try { memoryData = JSON.parse(memory.content); } catch { memoryData = { personal_notes: memory.content }; }
      }

      // ─── Confidence scoring ───────────────────────────────────────────────────
      const bookingHistory: Array<{ service: string; staff?: string; date: string }> = memoryData.booking_history || [];
      const now = new Date();
      const ninetyDaysAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);

      const recentHistory = bookingHistory.filter(b => {
        const d = new Date(b.date);
        return !isNaN(d.getTime()) && d >= ninetyDaysAgo;
      });

      // Count service+staff combos
      const comboCounts: Record<string, { count: number; service: string; staff?: string }> = {};
      for (const b of recentHistory) {
        const key = `${b.service}|${b.staff || ''}`;
        if (!comboCounts[key]) comboCounts[key] = { count: 0, service: b.service, staff: b.staff };
        comboCounts[key].count++;
      }
      // Fall back to all-time if no recent history
      if (Object.keys(comboCounts).length === 0 && bookingHistory.length > 0) {
        for (const b of bookingHistory) {
          const key = `${b.service}|${b.staff || ''}`;
          if (!comboCounts[key]) comboCounts[key] = { count: 0, service: b.service, staff: b.staff };
          comboCounts[key].count++;
        }
      }

      let topCombo: { count: number; service: string; staff?: string } | null = null;
      for (const c of Object.values(comboCounts)) {
        if (!topCombo || c.count > topCombo.count) topCombo = c;
      }

      let usual_label: string | null = null;
      let usual_label_text: string | null = null;
      let usual_greeting_suggestion: string | null = null;
      let booking_count = 0;

      if (topCombo) {
        booking_count = topCombo.count;
        if (booking_count >= 3 && recentHistory.length > 0) {
          usual_label = 'usual'; usual_label_text = 'Usual';
        } else if (booking_count === 2) {
          usual_label = 'preferred'; usual_label_text = 'Preferred';
        } else {
          usual_label = 'last_seen'; usual_label_text = 'Last seen with';
        }

        if (topCombo.service) {
          const staff = topCombo.staff;
          if (usual_label === 'usual') {
            usual_greeting_suggestion = staff
              ? `Should we get you down for your usual ${topCombo.service} with ${staff}?`
              : `Should we get you down for your usual ${topCombo.service}?`;
          } else if (usual_label === 'preferred') {
            usual_greeting_suggestion = staff
              ? `I see you prefer ${topCombo.service} with ${staff} — would you like to book that again?`
              : `I see you prefer ${topCombo.service} — would you like to book that again?`;
          } else {
            usual_greeting_suggestion = staff
              ? `Last time you had ${topCombo.service} with ${staff} — would you like that again?`
              : `Last time you had ${topCombo.service} — would you like that again?`;
          }
        }
      }

      // Days since last visit + verification flag
      const lastVisitRaw = memoryData.last_visit_date || customerProfile.lastCallDate;
      let days_since_last_visit: number | null = null;
      if (lastVisitRaw) {
        const last = new Date(lastVisitRaw);
        if (!isNaN(last.getTime())) {
          days_since_last_visit = Math.floor((now.getTime() - last.getTime()) / (24 * 60 * 60 * 1000));
        }
      }
      const needs_verification = days_since_last_visit !== null && days_since_last_visit > 90;

      const isVIP = customerProfile.tags?.includes('VIP') || (customerProfile as any).vipStatus || false;
      const { booking_history: _bh, ...memoryFields } = memoryData; // strip raw history

      console.log(`🧠 Returning memory for ${customerProfile.customerName || phoneNumber} — label: ${usual_label || 'none'}, count: ${booking_count}`);

      return res.json({
        success: true,
        is_new_customer: false,
        customer_name: memoryData.customer_name || customerProfile.customerName,
        phone_number: customerProfile.phoneNumber,
        email: memoryData.email || customerProfile.email,
        is_vip: isVIP,
        total_calls: customerProfile.totalCalls || 0,
        // All stored memory fields (preferred_service, preferred_technician, etc.)
        ...memoryFields,
        // Confidence scoring
        booking_count,
        usual_label,
        usual_label_text,
        usual_greeting_suggestion,
        days_since_last_visit,
        needs_verification,
      });
    } catch (error) {
      console.error('❌ Error in get_customer_memory:', error);
      res.status(500).json({ success: false, error: error instanceof Error ? error.message : 'Unknown error' });
    }
  });

  // ── UPDATE CUSTOMER MEMORY (conversation-flow agents) ────────────────────────────────────────
  app.post('/api/retell/update_customer_memory', async (req: any, res) => {
    try {
      const body = req.body;
      const args: Record<string, any> = body.arguments || body.args || body;
      const call = body.call;
      const agentId = call?.agent_id;
      const fromNumber = call?.from_number;
      const phoneNumber = args.preferred_phone || args.phone_number || fromNumber;
      const effectiveAgentId = agentId;

      console.log('💾 update_customer_memory — phone:', phoneNumber, '| agent:', effectiveAgentId);

      if (!phoneNumber || !effectiveAgentId) {
        return res.json({ success: false, error: 'Missing phone or agent ID' });
      }

      const agent = await storage.getVoiceAgentByRetellAgentId(effectiveAgentId);
      if (!agent) return res.json({ success: false, error: 'Agent not found' });
      const userId = agent.userId;

      // Ensure agent has a contact_memory integration (auto-provision if missing)
      const agentIntegsForUpdate = await storage.getAgentIntegrations(agent.id);
      const hasContactsIntegrationUpdate = agentIntegsForUpdate.some((i: any) => i.type === 'contact_memory');
      if (!hasContactsIntegrationUpdate) {
        try {
          await storage.createAgentIntegration({
            userId,
            agentId: agent.id,
            name: 'Contacts',
            type: 'contact_memory',
            description: 'Built-in customer contact memory from Contacts tab',
          } as any);
          console.log('🔗 Auto-provisioned contact_memory integration for agent (update)', agent.id);
        } catch (e) {
          console.warn('⚠️ Could not auto-provision contact_memory integration:', e);
        }
      }

      // Find or create customer profile
      let customerProfile = await storage.getCustomerProfileByPhone(phoneNumber, userId);
      if (!customerProfile) {
        const digits = phoneNumber.replace(/\D/g, '');
        const normalized = digits.startsWith('1') ? `+${digits}` : `+1${digits}`;
        customerProfile = await storage.createCustomerProfile({
          phoneNumber,
          normalizedPhone: normalized,
          customerName: args.customer_name || null,
          email: args.email || null,
          userId,
          firstCallDate: new Date(),
          lastCallDate: new Date(),
          segment: 'new',
        });
      } else if (args.consent_given) {
        await storage.updateCustomerProfile(customerProfile.id, {
          ...(args.customer_name ? { customerName: args.customer_name } : {}),
          ...(args.email ? { email: args.email } : {}),
          lastCallDate: new Date(),
        });
      }

      // Load existing memory
      const existingMemory = await storage.getCustomerMemoriesByCustomer(customerProfile.id, agent.id);
      let memoryData: Record<string, any> = {};
      if (existingMemory?.content) {
        try { memoryData = JSON.parse(existingMemory.content); } catch { memoryData = { personal_notes: existingMemory.content }; }
      }

      // Fields not persisted in JSON content (handled separately or excluded)
      const exclude = new Set(['phone_number', 'preferred_phone', 'booking_history', 'booked_service', 'booked_staff', 'booked_date', 'consent_given']);

      // Merge all non-excluded, non-empty args into memory
      for (const [k, v] of Object.entries(args)) {
        if (!exclude.has(k) && v !== null && v !== undefined && v !== '') {
          memoryData[k] = v;
        }
      }

      // Append to booking_history when a completed booking is reported
      const bookedService = args.booked_service || (args.consent_given ? args.preferred_service : null);
      const bookedStaff = args.booked_staff || args.preferred_technician || args.preferred_barber || args.preferred_staff;
      const bookedDate = args.booked_date || args.last_visit_date || new Date().toISOString().split('T')[0];

      if (bookedService && args.consent_given) {
        const history: Array<{ service: string; staff?: string; date: string }> = memoryData.booking_history || [];
        history.push({ service: bookedService, ...(bookedStaff ? { staff: bookedStaff } : {}), date: bookedDate });
        memoryData.booking_history = history.slice(-20); // keep last 20
        memoryData.last_visit_date = bookedDate;
      }

      // Preference override — customer explicitly chose something new
      if (args.preference_override && bookedService) {
        memoryData.preferred_service = bookedService;
        if (bookedStaff) memoryData.preferred_technician = bookedStaff;
      }

      const contentJson = JSON.stringify(memoryData);
      const wordCount = contentJson.split(/\s+/).length;

      if (existingMemory) {
        await storage.updateCustomerMemory(existingMemory.id, { content: contentJson, wordCount });
      } else {
        await storage.createCustomerMemory({
          customerProfileId: customerProfile.id,
          agentId: agent.id,
          userId,
          title: `Memory for ${args.customer_name || phoneNumber}`,
          content: contentJson,
          wordCount,
        });
      }

      console.log(`💾 Memory saved for ${customerProfile.customerName || phoneNumber} — fields: ${Object.keys(memoryData).filter(k => k !== 'booking_history').join(', ')}`);
      return res.json({ success: true, message: 'Customer memory updated' });
    } catch (error) {
      console.error('❌ Error in update_customer_memory:', error);
      res.status(500).json({ success: false, error: error instanceof Error ? error.message : 'Unknown error' });
    }
  });

