  // Create or update a contact
  app.post('/api/contacts', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const contactData = req.body;

      console.log('📥 POST /api/contacts - Request data:', {
        userId,
        phoneNumber: contactData.phoneNumber,
        customerName: contactData.customerName,
        notes: contactData.notes,
        hasNotes: !!contactData.notes
      });

      // Check if contact with this phone number already exists
      const existing = await storage.getCustomerProfileByPhone(
        contactData.phoneNumber,
        userId
      );

      console.log('🔍 Existing contact found:', existing ? { id: existing.id, phoneNumber: existing.phoneNumber } : 'No');

      if (existing) {
        // Update existing contact
        console.log('🔄 Updating existing contact:', existing.id, 'with data:', contactData);

        // Prepare update data - only include fields that are provided
        // IMPORTANT: Never include id, createdAt, or other system fields in updates
        const updateData: any = {
          updatedAt: new Date()
        };

        if (contactData.customerName !== undefined) updateData.customerName = contactData.customerName;
        if (contactData.notes !== undefined) updateData.notes = contactData.notes;
        if (contactData.email !== undefined) updateData.email = contactData.email;
        if (contactData.businessOrganization !== undefined) updateData.businessOrganization = contactData.businessOrganization;
        if (contactData.address !== undefined) updateData.address = contactData.address;

        // Handle array fields properly - PostgreSQL requires arrays, not strings
        if (contactData.tags !== undefined) {
          if (Array.isArray(contactData.tags)) {
            updateData.tags = contactData.tags;
          } else if (typeof contactData.tags === 'string') {
            // If tags is sent as a string, try to parse it as JSON or split by comma
            try {
              updateData.tags = JSON.parse(contactData.tags);
            } catch {
              updateData.tags = contactData.tags ? contactData.tags.split(',').map((t: string) => t.trim()) : [];
            }
          } else {
            updateData.tags = [];
          }
        }

        if (contactData.secondaryPhones !== undefined) {
          if (Array.isArray(contactData.secondaryPhones)) {
            updateData.secondaryPhones = contactData.secondaryPhones;
          } else if (typeof contactData.secondaryPhones === 'string') {
            try {
              updateData.secondaryPhones = JSON.parse(contactData.secondaryPhones);
            } catch {
              updateData.secondaryPhones = contactData.secondaryPhones ? contactData.secondaryPhones.split(',').map((p: string) => p.trim()) : [];
            }
          } else {
            updateData.secondaryPhones = [];
          }
        }

        // Handle date fields with validation
        if (contactData.firstCallDate !== undefined) {
          const date = new Date(contactData.firstCallDate);
          if (!isNaN(date.getTime())) {
            updateData.firstCallDate = date;
          } else {
            console.warn('⚠️ Invalid firstCallDate provided, skipping update');
          }
        }

        if (contactData.lastCallDate !== undefined) {
          const date = new Date(contactData.lastCallDate);
          if (!isNaN(date.getTime())) {
            updateData.lastCallDate = date;
          } else {
            console.warn('⚠️ Invalid lastCallDate provided, skipping update');
          }
        }

        // Remove any system fields that should never be updated
        delete updateData.id;
        delete updateData.createdAt;
        // updatedAt is set above, so we keep it

        console.log('📦 Prepared update data:', updateData);

        const updated = await storage.updateCustomerProfile(existing.id, updateData);
        console.log('✅ Contact updated successfully:', { id: updated.id, customerName: updated.customerName, notes: updated.notes });
        return res.json({ contact: updated, created: false });
      }

      // Create new contact
      console.log('➕ Creating new contact with data:', contactData);

      // Prepare contact data with proper types
      // Validate and parse dates
      const firstCallDate = contactData.firstCallDate ? new Date(contactData.firstCallDate) : new Date();
      const lastCallDate = contactData.lastCallDate ? new Date(contactData.lastCallDate) : new Date();

      // Check for invalid dates
      if (isNaN(firstCallDate.getTime())) {
        console.warn('⚠️ Invalid firstCallDate provided, using current date');
        firstCallDate.setTime(Date.now());
      }
      if (isNaN(lastCallDate.getTime())) {
        console.warn('⚠️ Invalid lastCallDate provided, using current date');
        lastCallDate.setTime(Date.now());
      }

      const newContactData = {
        phoneNumber: contactData.phoneNumber,
        normalizedPhone: contactData.normalizedPhone || contactData.phoneNumber,
        customerName: contactData.customerName || 'Guest',
        userId,
        firstCallDate,
        lastCallDate,
        totalCalls: contactData.totalCalls || 0,
        segment: contactData.segment || 'new',
        notes: contactData.notes || null,
        email: contactData.email || null,
        businessOrganization: contactData.businessOrganization || null,
        address: contactData.address || null,
      };

      console.log('📦 Prepared contact data for creation:', newContactData);

      const newContact = await storage.createCustomerProfile(newContactData);

      console.log('✅ Contact created successfully:', { id: newContact.id, customerName: newContact.customerName, notes: newContact.notes });
      res.json({ contact: newContact, created: true });
    } catch (error: any) {
      console.error('❌ Error creating/updating contact:', error);
      console.error('❌ Error stack:', error.stack);
      res.status(500).json({ error: 'Failed to create/update contact', details: error.message, stack: error.stack });
    }
  });

