  // Sync contacts from call history
  app.post('/api/contacts/sync-from-calls', isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      
      console.log('📞 Starting contact sync from call history for user:', userId);

      // Get user's phone numbers
      const phoneAssignments = await storage.getUserPhoneNumbers(userId);
      
      if (!phoneAssignments || phoneAssignments.length === 0) {
        return res.status(400).json({ 
          error: 'No phone numbers found for user',
          created: 0,
          updated: 0
        });
      }

      // Extract phone numbers from assignments
      const phoneNumbers = phoneAssignments.map(assignment => assignment.phoneNumber);

      // Import call history service
      const { callHistoryService } = await import('./services/callHistoryService');
      
      // Get all call history (last 90 days)
      const endDate = new Date();
      const startDate = new Date();
      startDate.setDate(startDate.getDate() - 90);

      const callHistory = await callHistoryService.getEnhancedCallHistory(
        userId,
        phoneNumbers,
        {
          startDate,
          endDate,
          limit: 1000
        }
      );

      console.log(`📊 Found ${callHistory.length} calls to process`);

      // Group calls by phone number
      const callsByPhone = new Map<string, any[]>();
      
      for (const call of callHistory) {
        const phoneKey = call.normalizedPhone || call.fromNumber;
        if (!phoneKey) continue;
        
        if (!callsByPhone.has(phoneKey)) {
          callsByPhone.set(phoneKey, []);
        }
        callsByPhone.get(phoneKey)!.push(call);
      }

      console.log(`👥 Found ${callsByPhone.size} unique phone numbers`);

      let created = 0;
      let updated = 0;

      // Create or update contact for each phone number
      for (const [phoneNumber, calls] of callsByPhone.entries()) {
        // Check if contact already exists
        const existing = await storage.getCustomerProfileByPhone(phoneNumber, userId);
        
        // Calculate aggregated data
        const sortedCalls = calls.sort((a, b) => 
          new Date(a.startTime).getTime() - new Date(b.startTime).getTime()
        );
        
        const firstCall = sortedCalls[0];
        const lastCall = sortedCalls[sortedCalls.length - 1];
        
        // Get customer name from any call that has it
        const callWithName = calls.find(c => c.customerName && c.customerName !== 'Unknown');
        const customerName = callWithName?.customerName || '';
        
        // Determine segment based on call count
        let segment = 'new';
        if (calls.length >= 10) segment = 'vip';
        else if (calls.length >= 3) segment = 'repeat';
        
        const contactData = {
          phoneNumber,
          normalizedPhone: phoneNumber,
          customerName,
          userId,
          firstCallDate: new Date(firstCall.startTime),
          lastCallDate: new Date(lastCall.startTime),
          totalCalls: calls.length,
          segment,
          vipStatus: calls.length >= 10,
          tags: [] as string[]
        };

        if (existing) {
          // Update existing contact
          await storage.updateCustomerProfile(existing.id, contactData);
          updated++;
          console.log(`✅ Updated contact for ${phoneNumber}`);
        } else {
          // Create new contact
          await storage.createCustomerProfile(contactData);
          created++;
          console.log(`➕ Created new contact for ${phoneNumber}`);
        }
      }

      console.log(`✨ Contact sync complete: ${created} created, ${updated} updated`);

      res.json({
        success: true,
        created,
        updated,
        total: created + updated
      });

    } catch (error) {
      console.error('Error syncing contacts from calls:', error);
      res.status(500).json({ error: 'Failed to sync contacts from call history' });
    }
  });

